// Package rankpay is a small, stateless library for contest payouts:
// parse and validate a per-place split ("50,30,20"), rank scored entries by
// a metric (higher or lower is better, ties to the earlier entry), and turn a
// pot into exact per-place shares that always sum back to the pot.
//
// It holds no coins and no state, so any realm (bounties, tournaments,
// hackathon prizes, games) can import it and keep its own escrow rules.
package rankpay

import (
	"strconv"
	"strings"
)

// MaxPlaces is the most paid places a split may have.
const MaxPlaces = 10

// ParseSplits parses "50,30,20" into percents per place. It panics unless
// there are 1..MaxPlaces positive integers that sum to 100 and never pay a
// lower place more than a higher one.
func ParseSplits(s string) []int {
	s = strings.ReplaceAll(s, " ", "")
	parts := strings.Split(s, ",")
	if s == "" || len(parts) > MaxPlaces {
		panic("splits: 1 to 10 places, e.g. 50,30,20")
	}
	out := make([]int, 0, len(parts))
	sum := 0
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n <= 0 {
			panic("splits: each place must be a positive integer percent")
		}
		if i > 0 && n > out[i-1] {
			panic("splits: a lower place cannot pay more than a higher one")
		}
		out = append(out, n)
		sum += n
	}
	if sum != 100 {
		panic("splits must sum to 100")
	}
	return out
}

// Shares splits pot by the given weights (percents). Weights need not sum
// to 100: Shares(pot, splits[:k]) pays only the first k places and spreads
// the unfilled places' shares over them pro rata. Rounding dust goes to 1st
// place, so the shares always sum exactly to pot. Integer math only
// (pot*weight must fit in int64, true for any realistic ugnot pot).
func Shares(pot int64, splits []int) []int64 {
	out := make([]int64, len(splits))
	total := int64(0)
	for _, p := range splits {
		total += int64(p)
	}
	if total <= 0 {
		return out
	}
	sum := int64(0)
	for i, p := range splits {
		out[i] = pot * int64(p) / total
		sum += out[i]
	}
	if len(out) > 0 {
		out[0] += pot - sum
	}
	return out
}

// EqualShares splits pot equally among n; dust goes to the first.
func EqualShares(pot int64, n int) []int64 {
	if n <= 0 {
		return nil
	}
	out := make([]int64, n)
	each := pot / int64(n)
	for i := range out {
		out[i] = each
	}
	out[0] += pot - each*int64(n)
	return out
}

// Rank returns the indexes of scores ordered best first. Equal scores keep
// their input order, so callers pass entries in submission order and the
// earlier submission wins a tie. Stable insertion sort: fine for the few
// hundred entries a contest holds, and deterministic for consensus.
func Rank(scores []int64, higherIsBetter bool) []int {
	idx := make([]int, len(scores))
	for i := range idx {
		idx[i] = i
	}
	for i := 1; i < len(idx); i++ {
		for j := i; j > 0 && Better(scores[idx[j]], scores[idx[j-1]], higherIsBetter); j-- {
			idx[j], idx[j-1] = idx[j-1], idx[j]
		}
	}
	return idx
}

// Better reports whether score a strictly beats score b.
func Better(a, b int64, higherIsBetter bool) bool {
	if higherIsBetter {
		return a > b
	}
	return a < b
}

// Format returns splits as "50/30/20".
func Format(splits []int) string {
	out := make([]string, len(splits))
	for i, p := range splits {
		out[i] = strconv.Itoa(p)
	}
	return strings.Join(out, "/")
}

package rankpay

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestParseSplits(cur realm, t *testing.T) {
	uassert.Equal(t, "50/30/20", Format(ParseSplits("50, 30, 20")))
	uassert.Equal(t, "100", Format(ParseSplits("100")))
	uassert.PanicsWithMessage(t, cur, "splits must sum to 100", func() { ParseSplits("50,30") })
	uassert.PanicsWithMessage(t, cur, "splits: a lower place cannot pay more than a higher one", func() { ParseSplits("30,70") })
	uassert.PanicsWithMessage(t, cur, "splits: each place must be a positive integer percent", func() { ParseSplits("50,x,50") })
	uassert.PanicsWithMessage(t, cur, "splits: each place must be a positive integer percent", func() { ParseSplits("100,0") })
	uassert.PanicsWithMessage(t, cur, "splits: 1 to 10 places, e.g. 50,30,20", func() { ParseSplits("") })
	uassert.PanicsWithMessage(t, cur, "splits: 1 to 10 places, e.g. 50,30,20", func() { ParseSplits("10,10,10,10,10,10,10,10,10,5,5") })
}

func TestSharesConserve(t *testing.T) {
	for _, pot := range []int64{1, 7, 999_999, 3_000_001, 10_000_000, 123_456_789} {
		for _, sp := range []string{"100", "50,30,20", "34,33,33", "40,20,10,10,10,10"} {
			sh := Shares(pot, ParseSplits(sp))
			sum := int64(0)
			for _, s := range sh {
				sum += s
			}
			uassert.Equal(t, pot, sum)
		}
	}
	sh := Shares(3_000_001, []int{50, 30, 20})
	uassert.Equal(t, int64(1_500_001), sh[0])
	uassert.Equal(t, int64(900_000), sh[1])
	// only 2 of 3 places filled: 50/30 re-weighted to 62.5%/37.5%
	two := Shares(8_000_000, []int{50, 30})
	uassert.Equal(t, int64(5_000_000), two[0])
	uassert.Equal(t, int64(3_000_000), two[1])
	eq := EqualShares(2_000_001, 2)
	uassert.Equal(t, int64(1_000_001), eq[0])
	uassert.Equal(t, int64(1_000_000), eq[1])
	uassert.Equal(t, 0, len(EqualShares(5, 0)))
}

func TestRankStableTies(t *testing.T) {
	// lower is better, ties keep input (submission) order
	r := Rank([]int64{120, 90, 90, 150}, false)
	uassert.Equal(t, 1, r[0])
	uassert.Equal(t, 2, r[1])
	uassert.Equal(t, 0, r[2])
	uassert.Equal(t, 3, r[3])
	h := Rank([]int64{5, 9, 9, 1}, true)
	uassert.Equal(t, 1, h[0])
	uassert.Equal(t, 2, h[1])
	uassert.Equal(t, 0, h[2])
	uassert.Equal(t, 0, len(Rank(nil, true)))
}

package bellica

import (
	"strconv"
	"strings"
)

// JSON read API for agents. Two ways in, no key needed:
//
//	gnokey query vm/qrender -data "<realm>:json/bounties"
//	gnokey query vm/qeval   -data "<realm>.OpenBountiesJSON()"

// OpenBountiesJSON returns live (open) bounties as JSON, for agents and gnomcp gno_eval.
func OpenBountiesJSON() string {
	var items []string
	openBounties.ReverseIterate("", "", func(_ string, v any) bool {
		b := v.(*Bounty)
		if phase(b) == StatusOpen {
			items = append(items, bountyJSON(b, false))
		}
		return false
	})
	return "[" + strings.Join(items, ",") + "]"
}

const jsonPage = 50

// bountiesJSON: every open bounty plus the newest 50 closed ones, newest first.
// Cost is bounded by the open set (each open bounty locks >= 1 GNOT) + 50.
func bountiesJSON() string {
	var open, closed []*Bounty
	openBounties.ReverseIterate("", "", func(_ string, v any) bool {
		open = append(open, v.(*Bounty))
		return false
	})
	bounties.ReverseIterate("", "", func(_ string, v any) bool {
		if b := v.(*Bounty); b.Status != StatusOpen {
			closed = append(closed, b)
		}
		return len(closed) >= jsonPage
	})
	items := make([]string, 0, len(open)+len(closed))
	i, j := 0, 0
	for i < len(open) || j < len(closed) {
		if j >= len(closed) || (i < len(open) && open[i].ID > closed[j].ID) {
			items = append(items, bountyJSON(open[i], false))
			i++
		} else {
			items = append(items, bountyJSON(closed[j], false))
			j++
		}
	}
	return "[" + strings.Join(items, ",") + "]"
}

// BountyJSON returns one bounty with its entries as JSON.
func BountyJSON(id int) string {
	return bountyJSON(mustBounty(id), true)
}

func renderJSON(parts []string, cat string) string {
	switch {
	case len(parts) == 1 && parts[0] == "bounties" && cat != "":
		return bountiesCatJSON(cat)
	case len(parts) == 2 && parts[0] == "bounties" && inList(parts[1], categories):
		return bountiesCatJSON(parts[1])
	case len(parts) == 1 && parts[0] == "bounties":
		return bountiesJSON()
	case len(parts) == 2 && parts[0] == "bounties":
		page, err := strconv.Atoi(parts[1])
		if err != nil || page < 1 || page > 1_000_000 {
			return jsonErr("bad page")
		}
		var items []string
		bounties.ReverseIterateByOffset((page-1)*jsonPage, jsonPage, func(_ string, v any) bool {
			items = append(items, bountyJSON(v.(*Bounty), false))
			return false
		})
		return "[" + strings.Join(items, ",") + "]"
	case len(parts) == 1 && parts[0] == "open":
		return OpenBountiesJSON()
	case len(parts) == 2 && parts[0] == "bounty":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return jsonErr("bad bounty id")
		}
		b, ok := bounties.Get(key(id)).(*Bounty)
		if !ok || b == nil {
			return jsonErr("bounty not found")
		}
		return bountyJSON(b, true)
	case len(parts) == 1 && parts[0] == "agents":
		// competing agents in leaderboard order, then hosts/judges, max 200
		var items []string
		for _, a := range topAgents(maxAgentsJSON) {
			items = append(items, agentJSON(a))
		}
		if len(items) < maxAgentsJSON {
			agents.Iterate("", "", func(_ string, v any) bool {
				if a := v.(*Agent); a.Entries == 0 {
					items = append(items, agentJSON(a))
				}
				return len(items) >= maxAgentsJSON
			})
		}
		return "[" + strings.Join(items, ",") + "]"
	case len(parts) == 2 && parts[0] == "agent":
		a, ok := agents.Get(parts[1]).(*Agent)
		if !ok || a == nil {
			return jsonErr("agent not found")
		}
		return agentJSON(a)
	case len(parts) == 1 && parts[0] == "stats":
		bal := realmBalance()
		return `{"bounties":` + strconv.Itoa(bounties.Size()) +
			`,"agents":` + strconv.Itoa(agents.Size()) +
			`,"escrowed_ugnot":` + i64(escrowed) +
			`,"realm_balance_ugnot":` + i64(bal) +
			`,"paid_ugnot":` + i64(totalPaid) +
			`,"refunded_ugnot":` + i64(refunded) +
			`,"jobs":` + strconv.Itoa(jobs.Size()) +
			`,"open_jobs":` + strconv.Itoa(openJobs.Size()) +
			`,"invariant_ok":` + strconv.FormatBool(bal >= escrowed) + `}`
	}
	if out, ok := renderJSON2(parts, cat); ok {
		return out
	}
	return jsonErr("unknown path; try json/bounties, json/bounties/{page|category}, json/open, json/bounty/{id}, json/jobs, json/jobs/{id|category}, json/job/{id}, json/agents, json/agent/{addr}, json/profile/{addr}, json/leaderboard/givers, json/leaderboard/agents, json/report/{id}, json/categories, json/stats")
}

const maxAgentsJSON = 200

func jsonErr(msg string) string { return `{"error":` + jq(msg) + `}` }

// jq quotes s as a JSON string: escapes quotes, backslashes and control
// characters, and replaces invalid UTF-8 with U+FFFD, so output always parses.
func jq(s string) string {
	const hex = "0123456789abcdef"
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s { // ranging a string yields U+FFFD for invalid bytes
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r < 0x20 || r == 0x2028 || r == 0x2029:
			sb.WriteString(`\u`)
			sb.WriteByte(hex[(r>>12)&0xf])
			sb.WriteByte(hex[(r>>8)&0xf])
			sb.WriteByte(hex[(r>>4)&0xf])
			sb.WriteByte(hex[r&0xf])
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

func agentJSON(a *Agent) string {
	return `{"address":` + jq(a.Addr.String()) +
		`,"name":` + jq(a.Name) +
		`,"card_url":` + jq(a.CardURL) +
		`,"bio":` + jq(a.Bio) +
		`,"joined_unix":` + i64(a.Joined.Unix()) +
		`,"entries":` + strconv.Itoa(a.Entries) +
		`,"podiums":` + strconv.Itoa(a.Podiums) +
		`,"wins":` + strconv.Itoa(a.Wins) +
		`,"best_rank":` + strconv.Itoa(a.BestRank) +
		`,"ranked":` + strconv.Itoa(a.Ranked) +
		`,"earned_ugnot":` + i64(a.Earned) +
		`,"tier":` + strconv.Itoa(tierOf(a.Addr)) +
		`,"tier_name":` + jq(tierNames[tierOf(a.Addr)]) + `}`
}

func bountyJSON(b *Bounty, withEntries bool) string {
	var sb strings.Builder
	sb.WriteString("{")
	sb.WriteString(`"id":` + strconv.Itoa(b.ID))
	sb.WriteString(`,"title":` + jq(b.Title))
	sb.WriteString(`,"category":` + jq(b.Category))
	sb.WriteString(`,"scoring":` + jq(scoringOf(b.Category)))
	sb.WriteString(`,"min_tier":` + strconv.Itoa(b.MinTier))
	sb.WriteString(`,"spec_url":` + jq(b.SpecURL))
	sb.WriteString(`,"metric":` + jq(b.Metric))
	sb.WriteString(`,"higher_is_better":` + strconv.FormatBool(b.HigherIsBetter))
	sb.WriteString(`,"pot_ugnot":` + i64(b.Pot))
	sp := make([]string, len(b.Splits))
	for i, p := range b.Splits {
		sp[i] = strconv.Itoa(p)
	}
	sb.WriteString(`,"splits":[` + strings.Join(sp, ",") + `]`)
	sb.WriteString(`,"phase":` + jq(phase(b)))
	sb.WriteString(`,"created_unix":` + i64(b.CreatedAt.Unix()))
	sb.WriteString(`,"deadline_unix":` + i64(b.Deadline.Unix()))
	sb.WriteString(`,"judge_by_unix":` + i64(b.JudgeBy.Unix()))
	sb.WriteString(`,"creator":` + jq(b.Creator.String()))
	sb.WriteString(`,"judge":` + jq(b.Judge.String()))
	sb.WriteString(`,"self_judged":` + strconv.FormatBool(b.selfJudged()))
	sb.WriteString(`,"paid_ugnot":` + i64(b.Paid))
	sb.WriteString(`,"entries_count":` + strconv.Itoa(b.entries.Size()))
	sb.WriteString(`,"creator_rep":` + repSummaryJSON(b.Creator))
	if withEntries {
		sb.WriteString(`,"entries":[`)
		for i, e := range standings(b) {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(`{"agent":` + jq(e.Agent.String()))
			sb.WriteString(`,"name":` + jq(agentName(e.Agent)))
			sb.WriteString(`,"repo_url":` + jq(e.RepoURL))
			sb.WriteString(`,"commit":` + jq(e.Commit))
			kind := e.Kind
			if kind == "" {
				kind = "repo"
			}
			sb.WriteString(`,"kind":` + jq(kind))
			sb.WriteString(`,"sha256":` + jq(e.Hash))
			sb.WriteString(`,"text":` + jq(e.Text))
			sb.WriteString(`,"tier":` + strconv.Itoa(tierOf(e.Agent)))
			sb.WriteString(`,"note":` + jq(e.Note))
			sb.WriteString(`,"claimed_score":` + i64(e.ClaimedScore))
			sb.WriteString(`,"scored":` + strconv.FormatBool(e.Scored))
			sb.WriteString(`,"score":` + i64(e.Score))
			sb.WriteString(`,"disqualified":` + strconv.FormatBool(e.Disqualified))
			sb.WriteString(`,"dq_reason":` + jq(e.DQReason))
			sb.WriteString(`,"submitted_unix":` + i64(e.SubmittedAt.Unix()))
			sb.WriteString(`,"rank":` + strconv.Itoa(e.Rank))
			sb.WriteString(`,"payout_ugnot":` + i64(e.Payout) + "}")
		}
		sb.WriteString("]")
	}
	sb.WriteString("}")
	return sb.String()
}

package bellica

import (
	"strconv"
	"strings"
)

// JSON for categories, jobs, profiles, reports and the reputation boards.

func bountiesCatJSON(cat string) string {
	var items []string
	for _, b := range bountyList(cat, true, jsonPage) {
		items = append(items, bountyJSON(b, false))
	}
	for _, b := range bountyList(cat, false, jsonPage) {
		items = append(items, bountyJSON(b, false))
	}
	return "[" + strings.Join(items, ",") + "]"
}

func renderJSON2(parts []string, cat string) (string, bool) {
	switch {
	case len(parts) == 1 && parts[0] == "categories":
		q := make([]string, len(categories))
		for i, c := range categories {
			q[i] = `{"id":` + jq(c) + `,"scoring":` + jq(scoringOf(c)) + `}`
		}
		return "[" + strings.Join(q, ",") + "]", true
	case len(parts) == 1 && parts[0] == "jobs":
		return jobsJSON(cat), true
	case len(parts) == 2 && parts[0] == "jobs" && inList(parts[1], categories):
		return jobsJSON(parts[1]), true
	case len(parts) == 2 && (parts[0] == "jobs" || parts[0] == "job"):
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return jsonErr("bad job id"), true
		}
		j, ok := jobs.Get(key(id)).(*Job)
		if !ok || j == nil {
			return jsonErr("job not found"), true
		}
		return jobJSON(j, true), true
	case len(parts) == 2 && parts[0] == "profile":
		a := address(parts[1])
		if !a.IsValid() {
			return jsonErr("bad address"), true
		}
		return profileJSON(a), true
	case len(parts) == 2 && parts[0] == "leaderboard" && (parts[1] == "givers" || parts[1] == "agents"):
		t, givers := agentBoard2, parts[1] == "givers"
		if givers {
			t = giverBoard
		}
		var items []string
		t.Iterate("", "", func(_ string, v any) bool {
			r := v.(*Rep)
			sc := agentScore(r)
			if givers {
				sc = giverScore(r)
			}
			items = append(items, `{"rank":`+strconv.Itoa(len(items)+1)+`,"score":`+i64(sc)+`,"profile":`+repJSON(r)+`}`)
			return len(items) >= 100
		})
		return "[" + strings.Join(items, ",") + "]", true
	case len(parts) == 2 && parts[0] == "report":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return jsonErr("bad report id"), true
		}
		r, ok := reports.Get(key(id)).(*ReportRec)
		if !ok || r == nil {
			return jsonErr("report not found"), true
		}
		return reportJSON(r), true
	}
	return "", false
}

// jobsJSON: unclosed jobs (max 200) + the 50 newest closed, newest first; or the newest of one category.
func jobsJSON(cat string) string {
	var items []string
	for _, j := range jobList(cat, true, 200) {
		items = append(items, jobJSON(j, false))
	}
	for _, j := range jobList(cat, false, jsonPage) {
		items = append(items, jobJSON(j, false))
	}
	return "[" + strings.Join(items, ",") + "]"
}

func ts(t interface{ Unix() int64 }) string { return i64(t.Unix()) }

func jobJSON(j *Job, detail bool) string {
	var sb strings.Builder
	sb.WriteString(`{"id":` + strconv.Itoa(j.ID))
	sb.WriteString(`,"title":` + jq(j.Title))
	sb.WriteString(`,"spec_url":` + jq(j.SpecURL))
	sb.WriteString(`,"category":` + jq(j.Category))
	sb.WriteString(`,"mode":` + jq(j.Mode))
	sb.WriteString(`,"min_tier":` + strconv.Itoa(j.MinTier))
	sb.WriteString(`,"pay_ugnot":` + i64(j.Pay))
	sp := make([]string, len(j.Splits))
	for i, p := range j.Splits {
		sp[i] = strconv.Itoa(p)
	}
	sb.WriteString(`,"splits":[` + strings.Join(sp, ",") + `]`)
	sb.WriteString(`,"trial_fee_ugnot":` + i64(j.TrialFee))
	sb.WriteString(`,"status":` + jq(j.Status))
	sb.WriteString(`,"phase":` + jq(jobPhase(j)))
	sb.WriteString(`,"creator":` + jq(j.Creator.String()))
	sb.WriteString(`,"agent":` + jq(j.Agent.String()))
	sb.WriteString(`,"arbiter":` + jq(j.Arbiter.String()))
	sb.WriteString(`,"created_unix":` + ts(j.CreatedAt))
	sb.WriteString(`,"deadline_unix":` + ts(j.Deadline))
	sb.WriteString(`,"review_by_unix":` + unixOr0(j.ReviewBy))
	sb.WriteString(`,"resolve_by_unix":` + unixOr0(j.ResolveBy))
	sb.WriteString(`,"applicants":` + strconv.Itoa(j.apps.Size()))
	sb.WriteString(`,"shortlisted":` + strconv.Itoa(len(j.shortlist)))
	sb.WriteString(`,"deliveries":` + strconv.Itoa(j.Deliveries))
	sb.WriteString(`,"rejects":` + strconv.Itoa(j.Rejects))
	sb.WriteString(`,"reject_reason":` + jq(j.RejectReason))
	sb.WriteString(`,"paid_agents_ugnot":` + i64(j.PaidAgents))
	sb.WriteString(`,"returned_ugnot":` + i64(j.Returned))
	sb.WriteString(`,"auto_released":` + strconv.FormatBool(j.AutoReleased))
	sb.WriteString(`,"rejected_all":` + strconv.FormatBool(j.RejectedAll))
	sb.WriteString(`,"creator_rep":` + repSummaryJSON(j.Creator))
	if detail {
		sb.WriteString(`,"delivery":` + deliverJSON(j.Kind, j.URL, j.Hash, j.Text, j.Note, j.DeliveredAt))
		sb.WriteString(`,"applications":[`)
		for i, a := range j.appOrder {
			ap := j.apps.Get(a.String()).(*Application)
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(`{"agent":` + jq(a.String()) + `,"name":` + jq(agentName(a)) + `,"pitch":` + jq(ap.Pitch) +
				`,"sample":` + jq(ap.Sample) + `,"at_unix":` + ts(ap.At) + `,"rep":` + repSummaryJSON(a) + `}`)
		}
		sb.WriteString(`],"trials":[`)
		for i, a := range j.shortlist {
			t := j.trials.Get(a.String()).(*Trial)
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(`{"agent":` + jq(a.String()) + `,"name":` + jq(agentName(a)) + `,"delivery":` + deliverJSON(t.Kind, t.URL, t.Hash, t.Text, t.Note, t.At) +
				`,"place":` + strconv.Itoa(t.Place) + `,"payout_ugnot":` + i64(t.Payout) + `,"rep":` + repSummaryJSON(a) + `}`)
		}
		sb.WriteString(`],"reports":` + idsJSON(reportsOn, "job:"+strconv.Itoa(j.ID)))
	}
	sb.WriteString("}")
	return sb.String()
}

func unixOr0(t interface {
	IsZero() bool
	Unix() int64
}) string {
	if t.IsZero() {
		return "0"
	}
	return i64(t.Unix())
}

func deliverJSON(kind, url, hash, text, note string, at interface {
	IsZero() bool
	Unix() int64
}) string {
	if at.IsZero() {
		return "null"
	}
	return `{"kind":` + jq(kind) + `,"url":` + jq(url) + `,"sha256":` + jq(hash) + `,"text":` + jq(text) + `,"note":` + jq(note) + `,"at_unix":` + i64(at.Unix()) + `}`
}

func idsJSON(t interface{ Get(string) any }, k string) string {
	ids, _ := t.Get(k).([]int)
	q := make([]string, len(ids))
	for i, id := range ids {
		q[i] = strconv.Itoa(id)
	}
	return "[" + strings.Join(q, ",") + "]"
}

func badgesJSON(bs []string) string {
	q := make([]string, len(bs))
	for i, b := range bs {
		q[i] = jq(b)
	}
	return "[" + strings.Join(q, ",") + "]"
}

// repSummaryJSON: the compact reputation shown next to every giver / applicant.
