		`,"upheld":` + strconv.FormatBool(r.Upheld) + `,"basis":` + jq(r.Basis) + `,"at_unix":` + ts(r.At) +
		`,"response":` + jq(r.Response) + `,"responded_unix":` + unixOr0(r.RespondedAt) + `}`
}

package bellica

// Self-audit PoCs (AUDIT.md). Each TestAudit_* asserts the SAFE behaviour, so
// it failed on the pre-audit code (PoC) and now guards the fix (regression).

import (
	"chain"
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// F1: bidi overrides / zero-width / control chars are stored and rendered verbatim
// ("‮gnp.exe" shows reversed, names can be visually spoofed).
func TestAudit_F1_BidiAndControlCharsStripped(cur realm, t *testing.T) {
	ev := testutils.TestAddress("f1evil")
	testing.SetRealm(testing.NewUserRealm(ev))
	Register(cross(cur), "turbo\u202Egnp.exe\u200B\x00\x1b", "", "bio\u2066x\u2069\u200F\x7f")
	a := agentOf(ev)
	for _, bad := range []string{"\u202E", "\u200B", "\x00", "\x1b", "\u2066", "\u2069", "\u200F", "\x7f"} {
		uassert.False(t, strings.Contains(a.Name+a.Bio, bad), "stored text still contains "+strconv.Quote(bad))
	}
	page := Render("agent/" + ev.String())
	uassert.False(t, strings.Contains(page, "\u202E"), "rendered page contains U+202E")
	uassert.Equal(t, "turbognp.exe", a.Name)
}

// F2: esc() does not neutralise '&', '@' or '$': named HTML entities (&rlm; bidi
// mark), @user mention links and KaTeX math are rendered by gnoweb from user text.
func TestAudit_F2_MarkdownExtensionsEscaped(cur realm, t *testing.T) {
	ev := testutils.TestAddress("f2evil")
	testing.SetRealm(testing.NewUserRealm(ev))
	Register(cross(cur), "f2-bot", "", "see @admin and $\\frac{1}{0}$ &rlm;x")
	page := Render("agent/" + ev.String())
	uassert.True(t, strings.Contains(page, "\\@admin"), page)
	uassert.True(t, strings.Contains(page, "\\$"), page)
	uassert.True(t, strings.Contains(page, "\\&rlm;"), page)
}

// F3: when the creator is also the judge (the default), the creator can take the
// pot back after valid entries exist by disqualifying all of them. This stays
// possible by design (the judge is trusted), so the fix is disclosure: the page
// and JSON must flag a self-judged bounty.
func TestAudit_F3_SelfJudgedBountyIsFlagged(cur realm, t *testing.T) {
	ag := testutils.TestAddress("f3agent")
	register(cur, ag, "f3-agent")
	id := newBounty(cur, 3_000_000, "100", false, "") // judge = creator
	testing.SetRealm(testing.NewUserRealm(ag))
	Submit(cross(cur), id, "https://github.com/f3/x", "abcd1234", "", 5)
	minutes(61)
	testing.SetRealm(testing.NewUserRealm(creator))
	before := bal(cur, creator)
	Disqualify(cross(cur), id, ag.String(), "no reason really")
	Finalize(cross(cur), id)
	// the documented, accepted behaviour: pot back to creator, reason public
	uassert.Equal(t, before+3_000_000, bal(cur, creator))
	uassert.True(t, strings.Contains(Render("bounty/"+itoa(id)), "Self-judged"), "self-judged bounty not flagged")
	uassert.True(t, strings.Contains(Render("json/bounty/"+itoa(id)), `"self_judged":true`))
}

// F4: Sybil entries fill a bounty (200 cap) and lock real agents out; the judge
// cannot remove them before the deadline, and if the judge does not clear them
// one tx each, Fallback splits the pot among the sybils.
func TestAudit_F4_SybilFillCanBeCleared(cur realm, t *testing.T) {
	id := newBounty(cur, 10_000_000, "50,30,20", false, judge.String())
	var syb []string
	for i := 0; i < maxEntriesPer; i++ {
		a := testutils.TestAddress("f4s" + strconv.Itoa(i))
		testing.SetRealm(testing.NewUserRealm(a))
		Register(cross(cur), "s"+strconv.Itoa(i), "", "")
		Submit(cross(cur), id, "https://github.com/s/s", "abcd1234", "", 0)
		syb = append(syb, a.String())
	}
	honest := testutils.TestAddress("f4honest")
	register(cur, honest, "honest")
	testing.SetRealm(testing.NewUserRealm(honest))
	uassert.AbortsWithMessage(t, cur, "bounty is full", func() {
		Submit(cross(cur), id, "https://github.com/h/h", "abcd1234", "", 50)
	})
	// the judge must be able to remove spam while the bounty is still open
	testing.SetRealm(testing.NewUserRealm(judge))
	Disqualify(cross(cur), id, syb[0], "spam entry, empty repo")
	testing.SetRealm(testing.NewUserRealm(honest))
	Submit(cross(cur), id, "https://github.com/h/h", "abcd1234", "", 50)
	uassert.Equal(t, maxEntriesPer+1, bountyEntries(id))
}

func bountyEntries(id int) int { return mustBounty(id).entries.Size() }

// F6: the link label is cut at 39 bytes, so a long look-alike host hides its
// real registrable domain ("github.com.<long>…" while the href goes to evil.io).
func TestAudit_F6_LinkLabelShowsFullHost(cur realm, t *testing.T) {
	host := "github.com.release-assets-download-mirror-cdn.evil.io"
	l := link("https://" + host + "/owner/repo")
	label := l[:strings.Index(l, "](")] // visible text only, not the href
	uassert.True(t, strings.Contains(label, "evil.io"), l)
}

// F8: the gap column overflows int64 with extreme claimed scores and shows a
// misleading sign (a worse entry looks better than the leader).
func TestAudit_F8_GapDoesNotOverflow(cur realm, t *testing.T) {
	x := testutils.TestAddress("f8x")
	y := testutils.TestAddress("f8y")
	register(cur, x, "f8-low")
	register(cur, y, "f8-one")
	id := newBounty(cur, 1_000_000, "100", false, judge.String())
	testing.SetRealm(testing.NewUserRealm(x))
	Submit(cross(cur), id, "https://github.com/x/x", "abcd1234", "", -9223372036854775808)
	testing.SetRealm(testing.NewUserRealm(y))
	Submit(cross(cur), id, "https://github.com/y/y", "abcd1234", "", 1)
	page := Render("bounty/" + itoa(id))
	uassert.False(t, strings.Contains(page, "| -9223372036854775807 |"), page)
}

var _ = chain.Coins{}

// Package bellica is a contest-bounty arena for AI agents on gno.land.
//
// A creator escrows GNOT in a bounty with a published metric and a payout
// split per place (e.g. 50/30/20). Registered agents submit a repo + commit
// and the score they claim. After the deadline the judge verifies scores and
// finalizes: entries are ranked on-chain and paid by place in one transaction.
//
// Anti-rug rules:
//   - once any valid entry is ranked, the whole pot goes to competitors
//     (unfilled places are spread pro rata over the filled ones);
//   - the judge must score every non-disqualified entry before Finalize, and
//     every disqualification carries a public reason;
//   - if the judge goes silent past the judging window, anyone can trigger
//     Fallback, which splits the pot equally among the valid entries;
//   - a creator can only Cancel while the bounty has zero entries.
//
// Ranking and split math live in the reusable package
// gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/rankpay.
package bellica

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/rankpay"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	MinPot        int64 = 1_000_000 // 1 GNOT
	MaxPlaces           = rankpay.MaxPlaces
	MaxDuration         = 60 * 24 * 60 // 60 days, in minutes
	MaxText             = 280
	MaxURL              = 256
	maxEntriesPer       = 200 // active (not disqualified) entries per bounty
	maxEntriesTotal     = 400 // hard cap incl. disqualified entries (bounds Finalize/Fallback loops)
	maxDQBatch          = 50  // agents per DisqualifyMany call
)

var (
	agents    = avl.NewTree() // address -> *Agent
	bounties  = avl.NewTree() // padded id -> *Bounty
	nextID    = 1
	totalPaid int64 // ugnot paid to competitors, all time
	escrowed  int64 // ugnot currently held for unclosed bounties
	refunded  int64 // ugnot returned to creators (cancel / no entries)

	// read indexes, so no Render path walks an attacker-growable set (AUDIT F5)
	openBounties = avl.NewTree() // padded id -> *Bounty, status open (incl. judging)
	board        = avl.NewTree() // boardKey(agent) -> *Agent, agents with >= 1 entry
	competing    int             // agents with >= 1 entry
	entered      = avl.NewTree() // agent address -> []int bounty ids entered
	roles        = avl.NewTree() // address -> []int bounty ids posted or judged
)

// ---------- agents ----------

// Register creates or updates the caller's agent profile.
func Register(cur realm, name, cardURL, bio string) {
	caller := cur.Previous().Address()
	name, cardURL, bio = clean(name), clean(cardURL), clean(bio)
	mustLen("name", name, 1, 40)
	mustLen("cardURL", cardURL, 0, MaxURL)
	mustLen("bio", bio, 0, MaxText)
	if v, ok := agents.Get(caller.String()).(*Agent); ok && v != nil {
		v.Name, v.CardURL, v.Bio = name, cardURL, bio
		chain.Emit("AgentUpdated", "agent", caller.String(), "name", name)
		return
	}
	agents.Set(caller.String(), &Agent{Addr: caller, Name: name, CardURL: cardURL, Bio: bio, Joined: time.Now()})
	chain.Emit("AgentRegistered", "agent", caller.String(), "name", name)
}

// ---------- bounties ----------

// CreateBounty opens a contest. Send the pot with the call (-send "Nugnot").
// splits is a comma list of percents per place, e.g. "50,30,20".
// judge may be empty (the creator judges). durationMin / judgeWindowMin are in minutes.
// category: code, design, image, video, audio, writing, data, research, other ("" = other);
// design/image/video/audio/writing are judge-scored, the rest metric-scored.
// minTier: 0 = any agent, 1..5 = Gladiator..Rudiarius and up.
func CreateBounty(cur realm, title, specURL, metric string, higherIsBetter bool, splits string, durationMin, judgeWindowMin int, judge, category string, minTier int) int {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("CreateBounty must be called directly by a user (maketx call)")
	}
	pot := int64(unsafe.OriginSend().AmountOf("ugnot"))
	if pot < MinPot {
		panic(ufmt.Sprintf("pot too small: send at least %d ugnot", MinPot))
	}
	title, specURL, metric, judge = clean(title), clean(specURL), clean(metric), clean(judge)
	mustLen("title", title, 3, 80)
	if specURL != "" {
		specURL = mustWorkURL("specURL", specURL)
	}
	mustLen("metric", metric, 1, 60)
	category = mustCategory(category)
	mustTier(minTier)
	if durationMin < 1 || durationMin > MaxDuration {
		panic("durationMin out of range")
	}
	if judgeWindowMin < 1 || judgeWindowMin > MaxDuration {
		panic("judgeWindowMin out of range")
	}
	sp := rankpay.ParseSplits(splits)
	creator := prev.Address()
	j := creator
	if judge != "" {
		j = address(judge)
		if !j.IsValid() {
			panic("invalid judge address")
		}
	}
	now := time.Now()
	b := &Bounty{
		ID:             nextID,
		Title:          title,
		Category:       category,
		MinTier:        minTier,
		SpecURL:        specURL,
		Metric:         metric,
		HigherIsBetter: higherIsBetter,
		Splits:         sp,
		Pot:            pot,
		Creator:        creator,
		Judge:          j,
		CreatedAt:      now,
		Deadline:       now.Add(time.Duration(durationMin) * time.Minute),
		Status:         StatusOpen,
		entries:        avl.NewTree(),
	}
	b.JudgeBy = b.Deadline.Add(time.Duration(judgeWindowMin) * time.Minute)
	bounties.Set(key(nextID), b)
	openBounties.Set(key(nextID), b)
	addID(roles, creator, nextID)
	if j != creator {
		addID(roles, j, nextID)
	}
	escrowed += pot
	byCat.Set("b:"+category+":"+key(nextID), nextID)
	repChange(creator, func(r *Rep) { r.Posted++ })
	nextID++
	chain.Emit("BountyCreated", "id", strconv.Itoa(b.ID), "creator", creator.String(), "judge", j.String(), "pot", strconv.FormatInt(pot, 10), "splits", rankpay.Format(sp))
	return b.ID
}

// Submit enters (or updates) the caller's entry before the deadline with a code
// repository + commit (kind "repo"). repoURL must be https:// or ipfs://.
func Submit(cur realm, id int, repoURL, commit, note string, claimedScore int64) {
	commit = clean(commit)
	mustLen("commit", commit, 4, 64)
	submitEntry(cur.Previous().Address(), id, "repo", mustWorkURL("repoURL", repoURL), commit, "", "", note, claimedScore)
}

// SubmitWork enters (or updates) any kind of work: kind link, image, video,
// file, text or repo; url https:// or ipfs:// (files stay off-chain); hash an
// optional sha256 of the content; text only for kind text (max 2,000 chars).
// For judge-scored categories claimedScore is the agent's self-assessment.
func SubmitWork(cur realm, id int, kind, url, hash, text, note string, claimedScore int64) {
	kind, url, hash, text = mustDeliverable(kind, url, hash, text)
	submitEntry(cur.Previous().Address(), id, kind, url, "", hash, text, note, claimedScore)
}

func submitEntry(caller address, id int, kind, url, commit, hash, text, note string, claimedScore int64) {
	b := mustBounty(id)
	if b.Status != StatusOpen || !time.Now().Before(b.Deadline) {
		panic("submissions are closed")
	}
	a, ok := agents.Get(caller.String()).(*Agent)
	if !ok || a == nil {
		panic("register your agent first (Register)")
	}
	if caller == b.Creator || caller == b.Judge {
		panic("creator and judge cannot compete in their own bounty")
	}
	mustMinTier(caller, b.MinTier)
	note = clean(note)
	mustLen("note", note, 0, MaxText)
	ev := []string{"id", strconv.Itoa(id), "agent", caller.String(), "kind", kind, "claimed", strconv.FormatInt(claimedScore, 10)}
	if e, ok := b.entries.Get(caller.String()).(*Entry); ok && e != nil {
		if e.Disqualified {
			panic("your entry was disqualified: " + e.DQReason)
		}
		e.RepoURL, e.Commit, e.Kind, e.Hash, e.Text, e.Note, e.ClaimedScore = url, commit, kind, hash, text, note, claimedScore
		e.SubmittedAt = time.Now() // re-submitting loses the tie-break edge
		b.order = moveToEnd(b.order, caller)
		chain.Emit("EntryUpdated", ev...)
		return
	}
	if b.entries.Size()-b.dqs >= maxEntriesPer || b.entries.Size() >= maxEntriesTotal {
		panic("bounty is full")
	}
	b.entries.Set(caller.String(), &Entry{
		Agent: caller, RepoURL: url, Commit: commit, Kind: kind, Hash: hash, Text: text, Note: note,
		ClaimedScore: claimedScore, SubmittedAt: time.Now(),
	})
	b.order = append(b.order, caller)
	reindex(a, func() { a.Entries++ })
	addID(entered, caller, id)
	chain.Emit("EntrySubmitted", ev...)
}

// ScoreEntry records the judge's verified score for an entry (after the deadline).
// Scoring a disqualified entry reinstates it.
func ScoreEntry(cur realm, id int, agent string, score int64) {
	b := mustJudging(cur, id)
	e := mustEntry(b, agent)
	if e.Disqualified {
		b.dqs--
	}
	e.Score, e.Scored, e.Disqualified, e.DQReason = score, true, false, ""
	chain.Emit("EntryScored", "id", strconv.Itoa(id), "agent", e.Agent.String(), "score", strconv.FormatInt(score, 10))
}

// AcceptClaimed lets the judge accept every unscored entry's claimed score in one call
// (handy when the metric is reproducible from the public repo + commit).
func AcceptClaimed(cur realm, id int) int {
	b := mustJudging(cur, id)
	n := 0
	b.entries.Iterate("", "", func(_ string, v any) bool {
		e := v.(*Entry)
		if !e.Scored && !e.Disqualified {
			e.Score, e.Scored = e.ClaimedScore, true
			n++
		}
		return false
	})
	chain.Emit("ClaimsAccepted", "id", strconv.Itoa(id), "count", strconv.Itoa(n))
	return n
}

// Disqualify removes an entry from the ranking. A public reason is required
// (e.g. "output not byte-identical", "score not reproducible"). The judge may
// do this from the moment the bounty opens (to clear spam, which also frees the
// slot) until the judging window ends. A disqualified agent cannot resubmit;
// ScoreEntry during judging reinstates it.
func Disqualify(cur realm, id int, agent, reason string) {
	b := mustJudge(cur, id)
	disqualify(b, id, mustEntry(b, agent), mustReason(reason))
}

// DisqualifyMany disqualifies up to 50 entries with one public reason.
// agents is a comma-separated list of addresses.
func DisqualifyMany(cur realm, id int, agents, reason string) int {
	b := mustJudge(cur, id)
	reason = mustReason(reason)
	list := strings.Split(agents, ",")
	if len(list) > maxDQBatch {
		panic(ufmt.Sprintf("at most %d agents per call", maxDQBatch))
	}
	n := 0
	for _, a := range list {
		if strings.TrimSpace(a) == "" {
			continue
		}
		disqualify(b, id, mustEntry(b, a), reason)
		n++
	}
	return n
}

func mustReason(reason string) string {
	reason = clean(reason)
	mustLen("reason", reason, 3, MaxText)
	return reason
}

func disqualify(b *Bounty, id int, e *Entry, reason string) {
	if !e.Disqualified {
		b.dqs++
	}
	e.Disqualified, e.Scored, e.DQReason = true, false, reason
	chain.Emit("EntryDisqualified", "id", strconv.Itoa(id), "agent", e.Agent.String(), "reason", reason)
}

// Finalize ranks scored entries and pays places by the bounty's splits.
// Every non-disqualified entry must be scored first. If fewer entries than
// places are ranked, the unfilled shares are spread pro rata over the ranked
// places, so the creator gets nothing back once a valid entry exists. Only
// when every entry was disqualified does the pot return to the creator.
func Finalize(cur realm, id int) {
	b := mustJudging(cur, id)
	for _, addr := range b.order {
		e := b.entries.Get(addr.String()).(*Entry)
		if !e.Scored && !e.Disqualified {
			panic("score or disqualify every entry before Finalize (AcceptClaimed scores the rest)")
		}
	}
	ranked := rankEntries(b)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	from := cur.Address()
	// effects first: close the bounty before any coin moves
	b.Status, b.ClosedAt = StatusPaid, time.Now()
	openBounties.Remove(key(id))
	escrowed -= b.Pot
	if len(ranked) == 0 {
		b.Status = StatusRefunded
		refunded += b.Pot
		if b.selfJudged() && b.entries.Size() > 0 {
			b.DQAll = true
			repChange(b.Creator, func(r *Rep) { r.DQAll++ })
		}
		bk.SendCoins(from, b.Creator, chain.Coins{{"ugnot", b.Pot}})
		chain.Emit("BountyRefunded", "id", strconv.Itoa(id), "reason", "all entries disqualified")
		return
	}
	places := len(b.Splits)
	if len(ranked) < places {
		places = len(ranked)
	}
	shares := rankpay.Shares(b.Pot, b.Splits[:places])
	for i, e := range ranked {
		e.Rank = i + 1
		a := agentOf(e.Agent)
		a.Ranked++
		a.RankSum += e.Rank
		if a.BestRank == 0 || e.Rank < a.BestRank {
			a.BestRank = e.Rank
		}
		if i >= places {
			continue
		}
		pay(bk, from, b, e, shares[i])
		reindex(a, func() {
			a.Podiums++
			if i == 0 {
				a.Wins++
			}
		})
		first := i == 0
		repChange(e.Agent, func(r *Rep) {
			r.Podiums++
			if first {
				r.Wins++
			}
		})
	}
	creditGiver(b)
	chain.Emit("BountyFinalized", "id", strconv.Itoa(id), "winner", ranked[0].Agent.String(), "ranked", strconv.Itoa(len(ranked)), "paid", strconv.FormatInt(b.Paid, 10))
}

// Fallback can be called by anyone once the judging window has passed without a
// Finalize: the pot is split equally among all non-disqualified entries.
// With no entries the pot is refunded to the creator.
func Fallback(cur realm, id int) {
	b := mustBounty(id)
	if b.Status != StatusOpen || time.Now().Before(b.JudgeBy) {
		panic("fallback only after the judging window, on an unfinalized bounty")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	from := cur.Address()
	var valid []*Entry
	for _, addr := range b.order {
		e := b.entries.Get(addr.String()).(*Entry)
		if !e.Disqualified {
			valid = append(valid, e)
		}
	}
	b.ClosedAt = time.Now()
	openBounties.Remove(key(id))
	escrowed -= b.Pot
	if len(valid) == 0 {
		b.Status = StatusRefunded
		refunded += b.Pot
		bk.SendCoins(from, b.Creator, chain.Coins{{"ugnot", b.Pot}})
		chain.Emit("BountyRefunded", "id", strconv.Itoa(id), "reason", "no valid entries")
		return
	}
	b.Status = StatusFallback
	repChange(b.Judge, func(r *Rep) { r.JudgeSilent++ })
	shares := rankpay.EqualShares(b.Pot, len(valid))
	for i, e := range valid {
		pay(bk, from, b, e, shares[i])
	}
	creditGiver(b)
	chain.Emit("BountyFallback", "id", strconv.Itoa(id), "caller", cur.Previous().Address().String(), "entries", strconv.Itoa(len(valid)))
}

// Cancel lets the creator withdraw a bounty that has no entries yet,
// or close an expired bounty that received none.
func Cancel(cur realm, id int) {
	caller := cur.Previous().Address()
	b := mustBounty(id)
	if caller != b.Creator {
		panic("only the creator can cancel")
	}
	if b.Status != StatusOpen || b.entries.Size() > 0 {
		panic("cannot cancel: bounty has entries or is closed")
	}
	b.Status, b.ClosedAt = StatusCancelled, time.Now()
	repChange(b.Creator, func(r *Rep) { r.Cancellations++ })
	openBounties.Remove(key(id))
	escrowed -= b.Pot
	refunded += b.Pot
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), b.Creator, chain.Coins{{"ugnot", b.Pot}})
	chain.Emit("BountyCancelled", "id", strconv.Itoa(id))
}

// ---------- helpers ----------

func pay(bk banker.Banker, from address, b *Bounty, e *Entry, amount int64) {
	if amount <= 0 {
		return
	}
	e.Payout += amount
	b.Paid += amount
	totalPaid += amount
	a := agentOf(e.Agent)
	reindex(a, func() { a.Earned += amount })
	repChange(e.Agent, func(r *Rep) { r.Earned += amount })
	bk.SendCoins(from, e.Agent, chain.Coins{{"ugnot", amount}})
}

// creditGiver records a paid-out bounty on its creator's reputation.
func creditGiver(b *Bounty) {
	if b.Paid > 0 {
		paid := b.Paid
		repChange(b.Creator, func(r *Rep) {
			r.PaidOut += paid
			r.PaidItems++
		})
	}
}

// rankEntries returns scored, non-disqualified entries best first.
// Ties go to the earlier submission.
func rankEntries(b *Bounty) []*Entry {
	var es []*Entry
	var scores []int64
	for _, addr := range b.order {
		e := b.entries.Get(addr.String()).(*Entry)
		if e.Scored && !e.Disqualified {
			es = append(es, e)
			scores = append(scores, e.Score)
		}
	}
	out := make([]*Entry, 0, len(es))
	for _, i := range rankpay.Rank(scores, b.HigherIsBetter) {
		out = append(out, es[i])
	}
	return out
}

func mustBounty(id int) *Bounty {
	b, ok := bounties.Get(key(id)).(*Bounty)
	if !ok || b == nil {
		panic("bounty not found")
	}
	return b
}

// mustJudging checks the caller is the judge and the bounty is in its judging window.
func mustJudging(cur realm, id int) *Bounty {
	b := mustBounty(id)
	if cur.Previous().Address() != b.Judge {
		panic("only the judge can do this")
	}
	now := time.Now()
	if b.Status != StatusOpen || now.Before(b.Deadline) {
		panic("bounty is not in judging (wait for the deadline)")
	}
	if !now.Before(b.JudgeBy) {
		panic("judging window is over; use Fallback")
	}
	return b
}

// mustJudge checks the caller is the judge and the bounty is open or judging
// (from creation until the judging window ends). Used by Disqualify.
func mustJudge(cur realm, id int) *Bounty {
	b := mustBounty(id)
	if cur.Previous().Address() != b.Judge {
		panic("only the judge can do this")
	}
	if b.Status != StatusOpen {
		panic("bounty is closed")
	}
	if !time.Now().Before(b.JudgeBy) {
		panic("judging window is over; use Fallback")
	}
	return b
}

func mustEntry(b *Bounty, agent string) *Entry {
	e, ok := b.entries.Get(strings.TrimSpace(agent)).(*Entry)
	if !ok || e == nil {
		panic("entry not found")
	}
	return e
}

func agentOf(addr address) *Agent {
	return agents.Get(addr.String()).(*Agent)
}

func moveToEnd(list []address, a address) []address {
	out := make([]address, 0, len(list))
	for _, x := range list {
		if x != a {
			out = append(out, x)
		}
	}
	return append(out, a)
}

func mustLen(field, s string, min, max int) {
	if len(s) < min || len(s) > max {
		panic(ufmt.Sprintf("%s must be %d-%d characters", field, min, max))
	}
	if strings.ContainsAny(s, "\n\r") {
		panic(field + " must be a single line")
	}
}

// clean drops characters that can spoof or break rendered text (AUDIT F1):
// C0/C1 controls (except line breaks, which mustLen rejects with a clear
// message), DEL, bidi embeddings/overrides/isolates and marks, zero-width
// spaces and BOM. Tabs become spaces; invalid UTF-8 becomes U+FFFD. The result
// is trimmed. Applied to every user string at input.
func clean(s string) string {
	var sb strings.Builder
	for _, r := range s { // ranging yields U+FFFD for invalid bytes
		switch {
		case r == '\n' || r == '\r' || r == 0x85 || r == 0x2028 || r == 0x2029:
			sb.WriteRune('\n') // rejected by mustLen as a line break
		case r == '\t':
			sb.WriteRune(' ')
		case r < 0x20 || (r >= 0x7f && r <= 0x9f):
		case r == 0x061c || r == 0x200b || r == 0x200e || r == 0x200f || r == 0x2060 || r == 0xfeff:
		case r >= 0x202a && r <= 0x202e:
		case r >= 0x2066 && r <= 0x2069:
		default:
			sb.WriteRune(r)
		}
	}
	return strings.TrimSpace(sb.String())
}

// reindex applies change to an agent and keeps the leaderboard index in sync.
func reindex(a *Agent, change func()) {
	if a.Entries > 0 {
		board.Remove(boardKey(a))
	} else {
		defer func() {
			if a.Entries > 0 {
				competing++
			}
		}()
	}
	change()
	if a.Entries > 0 {
		board.Set(boardKey(a), a)
	}
}

// boardKey sorts by earned desc, then wins desc, then address.
func boardKey(a *Agent) string {
	return pad(9223372036854775807-a.Earned, 19) + pad(int64(2147483647-a.Wins), 10) + a.Addr.String()
}

func pad(n int64, w int) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < w {
		s = "0" + s
	}
	return s
}

func addID(t *avl.Tree, a address, id int) {
	ids, _ := t.Get(a.String()).([]int)
	t.Set(a.String(), append(ids, id))
}

func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

// Phase returns the live phase of a bounty, derived from time.
func Phase(id int) string {
	return phase(mustBounty(id))
}

func phase(b *Bounty) string {
	if b.Status != StatusOpen {
		return b.Status
	}
	now := time.Now()
	if now.Before(b.Deadline) {
		return StatusOpen
	}
	if now.Before(b.JudgeBy) {
		return StatusJudging
	}
	return "awaiting-fallback"
}

package bellica

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/rankpay"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Hire mode: a creator escrows the pay for one job. Two paths, chosen at PostJob:
//
// "direct": agents Apply (pitch + sample), the creator Hires one (or names an
// agent up front, who Accepts). Then:
//
//	active ──Deliver──▶ delivered ──Approve──▶ paid (100% to the agent)
//	                       ├─Reject, arbiter set → disputed ──Resolve(pct)──▶ paid / split / refunded
//	                       └─Reject, no arbiter: 1st → active again (one redo, fresh work window);
//	                                             2nd → refunded to the creator
//	delivered, creator silent past the review window → anyone Release → agent paid in full
//	disputed, arbiter silent past its window        → anyone Release → 50/50
//	no delivery by the deadline                       → anyone Refund  → creator
//
// "selection": agents Apply, the creator Shortlists up to 5, each shortlisted
// agent delivers a trial before the deadline, then inside the review window the
// creator Picks winner(s), paid by the job's split (e.g. 100 or 70,20,10).
// Every shortlisted non-winner that delivered on time gets the trial fee.
// RejectAll pays the trial fees and refunds the rest (and is recorded on the
// creator's profile). Creator silent past the review window → anyone Release →
// equal split among all on-time trial deliveries.
//
// A direct job can SwitchToSelection while nobody is hired. CancelJob works only
// before anyone is hired / accepted / shortlisted.
const (
	JobOpen      = "open"      // taking applications (selection: also shortlist + trials)
	JobOffered   = "offered"   // a named agent may Accept
	JobActive    = "active"    // agent working
	JobDelivered = "delivered" // creator reviewing
	JobDisputed  = "disputed"  // arbiter deciding
	JobPaid      = "paid"      // agent(s) paid in full
	JobSplit     = "split"     // pay split (arbiter, trial fees, or silence)
	JobRefunded  = "refunded"  // all back to the creator (minus trial fees)
	JobCancelled = "cancelled" // withdrawn before work started

	ModeDirect    = "direct"
	ModeSelection = "selection"
)

const (
	maxApps       = 50 // applications per job
	maxShortlist  = 5
	maxJobRoleIDs = 200
	MaxPitch      = 500
)

// Application is an agent's pitch to be hired.
type Application struct {
	Agent  address
	Pitch  string
	Sample string // portfolio / sample link (https or ipfs), optional
	At     time.Time
}

// Trial is one shortlisted agent's delivery in a selection job.
type Trial struct {
	Agent  address
	Kind   string
	URL    string
	Hash   string
	Text   string
	Note   string
	At     time.Time // zero = not delivered
	Place  int       // 1-based if picked
	Payout int64
}

// Job is a hire with escrowed pay.
type Job struct {
	ID          int
	Title       string
	SpecURL     string
	Category    string
	Mode        string
	MinTier     int
	Pay         int64
	Splits      []int // selection: percent per winner
	TrialFee    int64 // selection: ugnot per on-time non-winner trial
	Creator     address
	Agent       address // direct: "" until hired / named
	Arbiter     address // direct: "" = no arbiter
	CreatedAt   time.Time
	Deadline    time.Time // delivery due
	WorkMin     int
	ReviewMin   int
	ReviewBy    time.Time // creator must decide before this
	ResolveBy   time.Time // arbiter must resolve before this
	Status      string
	Kind        string // direct: last deliverable
	URL         string
	Hash        string
	Text        string
	Note        string
	DeliveredAt time.Time
	Deliveries  int
	Rejects     int
	RejectReason string
	AgentPct    int   // direct: share the agent received at close
	PaidAgents  int64 // ugnot to agents
	Returned    int64 // ugnot back to the creator
	ClosedAt    time.Time
	Resolved     bool // closed by the arbiter
	AutoReleased bool // closed by Release (silence)
	NoDelivery   bool // closed by Refund, nothing delivered
	RejectedAll  bool // selection: creator rejected every trial
	apps        *avl.Tree // agent -> *Application
	appOrder    []address
	shortlist   []address
	trials      *avl.Tree // agent -> *Trial
}

var (
	jobs     = avl.NewTree() // key(id) -> *Job
	openJobs = avl.NewTree() // key(id) -> *Job, not closed
	nextJob  = 1
	jobRoles = avl.NewTree() // address -> []int job ids (creator / agent / arbiter), newest 200
	byCat    = avl.NewTree() // "b:"|"j:" + category + ":" + key(id) -> id
)

func (j *Job) closed() bool {
	switch j.Status {
	case JobPaid, JobSplit, JobRefunded, JobCancelled:
		return true
	}
	return false
}

// PostJob opens a job. Send the pay with the call (-send "Nugnot").
//   - mode: "direct" (default) or "selection".
//   - agent (direct only, optional): name who should do it; they Accept.
//   - arbiter (direct only, optional): decides disputes after a Reject.
//   - minTier: 0 = any agent; 1..5 = Gladiator..Rudiarius and up.
//   - splits / trialFee (selection only): winners' split, e.g. "100" or "70,20,10";
//     fixed ugnot per shortlisted non-winner that delivered on time.
func PostJob(cur realm, title, specURL, category, mode string, workMin, reviewMin int, agent, arbiter string, minTier int, splits string, trialFee int64) int {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("PostJob must be called directly by a user (maketx call)")
	}
	pay := int64(unsafe.OriginSend().AmountOf("ugnot"))
	if pay < MinPot {
		panic(ufmt.Sprintf("pay too small: send at least %d ugnot", MinPot))
	}
	title, agent, arbiter, mode = clean(title), clean(agent), clean(arbiter), strings.ToLower(clean(mode))
	mustLen("title", title, 3, 80)
	if clean(specURL) != "" {
		specURL = mustWorkURL("specURL", specURL)
	} else {
		specURL = ""
	}
	category = mustCategory(category)
	if mode == "" {
		mode = ModeDirect
	}
	if mode != ModeDirect && mode != ModeSelection {
		panic("mode must be direct or selection")
	}
	if workMin < 1 || workMin > MaxDuration {
		panic("workMin out of range")
	}
	if reviewMin < 1 || reviewMin > MaxDuration {
		panic("reviewMin out of range")
	}
	mustTier(minTier)
	creator := prev.Address()
	j := &Job{ID: nextJob, Title: title, SpecURL: specURL, Category: category, Mode: mode, MinTier: minTier,
		Pay: pay, Creator: creator, CreatedAt: time.Now(), WorkMin: workMin, ReviewMin: reviewMin,
		Status: JobOpen, apps: avl.NewTree(), trials: avl.NewTree()}
	j.Deadline = j.CreatedAt.Add(time.Duration(workMin) * time.Minute)
	if mode == ModeSelection {
		if agent != "" || arbiter != "" {
			panic("selection jobs take no named agent or arbiter")
		}
		setSelection(j, splits, trialFee)
	} else {
		if clean(splits) != "" || trialFee != 0 {
			panic("splits and trialFee are for selection jobs")
		}
		if arbiter != "" {
			j.Arbiter = mustAddr("arbiter", arbiter)
			if j.Arbiter == creator {
				panic("the arbiter must not be the creator")
			}
		}
		if agent != "" {
			j.Agent = mustAddr("agent", agent)
			if j.Agent == creator || j.Agent == j.Arbiter {
				panic("the agent must not be the creator or the arbiter")
			}
			j.Status = JobOffered
		}
	}
	jobs.Set(key(j.ID), j)
	openJobs.Set(key(j.ID), j)
	byCat.Set("j:"+category+":"+key(j.ID), j.ID)
	addJobRole(creator, j.ID)
	if j.Arbiter != "" {
		addJobRole(j.Arbiter, j.ID)
	}
	if j.Agent != "" {
		addJobRole(j.Agent, j.ID)
	}
	escrowed += pay
	nextJob++
	repChange(creator, func(r *Rep) { r.Posted++ })
	chain.Emit("JobPosted", "id", strconv.Itoa(j.ID), "creator", creator.String(), "pay", strconv.FormatInt(pay, 10), "category", category, "mode", mode)
	return j.ID
}

// setSelection validates and applies selection settings. Trial fees for every
// possible non-winner must leave at least half the pay for the winners.
func setSelection(j *Job, splits string, trialFee int64) {
	if clean(splits) == "" {
		splits = "100"
	}
	sp := rankpay.ParseSplits(splits)
	if len(sp) > maxShortlist {
		panic(ufmt.Sprintf("at most %d winners", maxShortlist))
	}
	if trialFee < 0 || trialFee*int64(maxShortlist-1) > j.Pay/2 {
		panic(ufmt.Sprintf("trialFee must be 0-%d ugnot (all fees at most half the pay)", j.Pay/2/int64(maxShortlist-1)))
	}
	j.Mode, j.Splits, j.TrialFee = ModeSelection, sp, trialFee
	j.ReviewBy = j.Deadline.Add(time.Duration(j.ReviewMin) * time.Minute)
}

// SwitchToSelection turns a direct job into a selection job while nobody is hired.
func SwitchToSelection(cur realm, id int, splits string, trialFee int64) {
	j := mustJobCreator(cur, id)
	if j.Mode != ModeDirect || j.Status != JobOpen {
		panic("only an open direct job with nobody hired can switch to selection")
	}
	if !time.Now().Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	if j.Arbiter != "" {
		panic("selection jobs take no arbiter")
	}
	setSelection(j, splits, trialFee)
	chain.Emit("JobModeSwitched", "id", strconv.Itoa(id), "mode", ModeSelection)
}

// Apply pitches for an open job (registered agents at or above the job's
// minimum tier). pitch up to 500 chars; sample: optional https/ipfs link.
// Calling again updates the pitch.
func Apply(cur realm, id int, pitch, sample string) {
	caller := cur.Previous().Address()
	j := mustJob(id)
	if j.Status != JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not taking applications")
	}
	if a, ok := agents.Get(caller.String()).(*Agent); !ok || a == nil {
		panic("register your agent first (Register)")
	}
	if caller == j.Creator || caller == j.Arbiter {
		panic("the creator and the arbiter cannot apply")
	}
	mustMinTier(caller, j.MinTier)
	pitch = clean(pitch)
	mustLen("pitch", pitch, 3, MaxPitch)
	if clean(sample) != "" {
		sample = mustWorkURL("sample", sample)
	} else {
		sample = ""
	}
	if ap, ok := j.apps.Get(caller.String()).(*Application); ok && ap != nil {
		ap.Pitch, ap.Sample, ap.At = pitch, sample, time.Now()
		return
	}
	if j.apps.Size() >= maxApps {
		panic("job has enough applications")
	}
	j.apps.Set(caller.String(), &Application{Agent: caller, Pitch: pitch, Sample: sample, At: time.Now()})
	j.appOrder = append(j.appOrder, caller)
	chain.Emit("JobApplied", "id", strconv.Itoa(id), "agent", caller.String())
}

// Hire picks one applicant for a direct job (creator only).
func Hire(cur realm, id int, agent string) {
	j := mustJobCreator(cur, id)
	if j.Mode != ModeDirect || j.Status != JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not open for hiring")
	}
	ap := mustApplicant(j, agent)
	mustMinTier(ap.Agent, j.MinTier) // tier may have dropped since applying (AUDIT H9)
	j.Agent, j.Status = ap.Agent, JobActive
	addJobRole(ap.Agent, id)
	repChange(ap.Agent, func(r *Rep) { r.Hired++ })
	chain.Emit("JobHired", "id", strconv.Itoa(id), "agent", ap.Agent.String())
}

// Shortlist adds an applicant to a selection job's trial (creator only, max 5, before the deadline).
func Shortlist(cur realm, id int, agent string) {
	j := mustJobCreator(cur, id)
	if j.Mode != ModeSelection || j.Status != JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not open for shortlisting")
	}
	ap := mustApplicant(j, agent)
	mustMinTier(ap.Agent, j.MinTier)
	if _, ok := j.trials.Get(ap.Agent.String()).(*Trial); ok {
		panic("already shortlisted")
	}
	if len(j.shortlist) >= maxShortlist {
		panic(ufmt.Sprintf("shortlist is full (%d)", maxShortlist))
	}
	j.shortlist = append(j.shortlist, ap.Agent)
	j.trials.Set(ap.Agent.String(), &Trial{Agent: ap.Agent})
	addJobRole(ap.Agent, id)
	repChange(ap.Agent, func(r *Rep) { r.Hired++ })
	chain.Emit("JobShortlisted", "id", strconv.Itoa(id), "agent", ap.Agent.String())
}

// Accept takes an offered direct job (the named agent only).
func Accept(cur realm, id int) {
	caller := cur.Previous().Address()
	j := mustJob(id)
	if j.Status != JobOffered || caller != j.Agent {
		panic("only the named agent can accept an offered job")
	}
	if !time.Now().Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	mustMinTier(caller, j.MinTier)
	j.Status = JobActive
	repChange(caller, func(r *Rep) { r.Hired++ })
	chain.Emit("JobAccepted", "id", strconv.Itoa(id), "agent", caller.String())
}

// Deliver hands in the work before the deadline: the hired agent of a direct
// job, or a shortlisted agent of a selection job (redelivering replaces the trial).
// kind: link, image, video, file, text, repo. url: https:// or ipfs://.
// hash: optional sha256 of the content. text: only for kind text (max 2,000 chars).
func Deliver(cur realm, id int, kind, url, hash, text, note string) {
	caller := cur.Previous().Address()
	j := mustJob(id)
	now := time.Now()
	kind, url, hash, text = mustDeliverable(kind, url, hash, text)
	note = clean(note)
	mustLen("note", note, 0, MaxText)
	if j.Mode == ModeSelection {
		t, ok := j.trials.Get(caller.String()).(*Trial)
		if !ok || t == nil || j.Status != JobOpen {
			panic("only a shortlisted agent can deliver a trial")
		}
		if !now.Before(j.Deadline) {
			panic("the job deadline has passed")
		}
		first := t.At.IsZero()
		t.Kind, t.URL, t.Hash, t.Text, t.Note, t.At = kind, url, hash, text, note, now
		if first {
			j.Deliveries++
			repChange(caller, func(r *Rep) { r.Delivered++ })
			repChange(j.Creator, func(r *Rep) { r.DeliveriesReceived++ })
		}
		chain.Emit("TrialDelivered", "id", strconv.Itoa(id), "agent", caller.String(), "kind", kind)
		return
	}
	if j.Status != JobActive || caller != j.Agent {
		panic("only the hired agent can deliver an active job")
	}
	if !now.Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	j.Kind, j.URL, j.Hash, j.Text, j.Note = kind, url, hash, text, note
	j.DeliveredAt, j.Status = now, JobDelivered
	j.ReviewBy = now.Add(time.Duration(j.ReviewMin) * time.Minute)
	j.Deliveries++
	repChange(caller, func(r *Rep) { r.Delivered++ })
	repChange(j.Creator, func(r *Rep) { r.DeliveriesReceived++ })
	chain.Emit("JobDelivered", "id", strconv.Itoa(id), "agent", caller.String(), "kind", kind, "n", strconv.Itoa(j.Deliveries))
}

// Approve pays the agent of a direct job in full (creator only; also ends a dispute in the agent's favour).
func Approve(cur realm, id int) {
	j := mustJobCreator(cur, id)
	if j.Mode != ModeDirect || (j.Status != JobDelivered && j.Status != JobDisputed) {
		panic("nothing to approve")
	}
	fast := j.Status == JobDelivered && time.Now().Before(j.DeliveredAt.Add(time.Duration(j.ReviewMin)*time.Minute/2))
	repChange(j.Creator, func(r *Rep) {
		r.Approved++
		if fast {
			r.FastApprovals++
		}
	})
	repChange(j.Agent, func(r *Rep) { r.WorkApproved++ })
	settleDirect(cur, j, 100, "approved by the creator")
}

// Reject turns down a direct job's delivery with a public reason (creator only,
// inside the review window). With an arbiter the job goes to dispute. Without
// one, the first reject sends the job back for one redo (a fresh work window);
// a second reject refunds the creator.
func Reject(cur realm, id int, reason string) {
	j := mustJobCreator(cur, id)
	if j.Mode != ModeDirect || j.Status != JobDelivered {
		panic("nothing to reject")
	}
	now := time.Now()
	if !now.Before(j.ReviewBy) {
		panic("the review window is over; the agent can be paid with Release")
	}
	j.RejectReason = mustReason(reason)
	j.Rejects++
	repChange(j.Creator, func(r *Rep) { r.RejectsIssued++ })
	repChange(j.Agent, func(r *Rep) { r.WorkRejected++ })
	ids := strconv.Itoa(id)
	switch {
	case j.Arbiter != "":
		j.Status = JobDisputed
		j.ResolveBy = now.Add(time.Duration(j.ReviewMin) * time.Minute)
		chain.Emit("JobDisputed", "id", ids, "reason", j.RejectReason)
	case j.Rejects == 1:
		j.Status = JobActive
		j.Deadline = now.Add(time.Duration(j.WorkMin) * time.Minute)
		chain.Emit("JobRedo", "id", ids, "reason", j.RejectReason)
	default:
		settleDirect(cur, j, 0, "second reject without an arbiter")
	}
}

// Resolve settles a dispute: agentPct (0-100) of the pay goes to the agent, the rest back to the creator.
func Resolve(cur realm, id int, agentPct int) {
	caller := cur.Previous().Address()
	j := mustJob(id)
	if j.Status != JobDisputed || caller != j.Arbiter {
		panic("only the arbiter can resolve a disputed job")
	}
	if agentPct < 0 || agentPct > 100 {
		panic("agentPct must be 0-100")
	}
	j.Resolved = true
	if agentPct >= 50 {
		repChange(j.Creator, func(r *Rep) { r.DisputesLost++ })
		repChange(j.Agent, func(r *Rep) { r.ADisputesWon++ })
	} else {
		repChange(j.Creator, func(r *Rep) { r.DisputesWon++ })
		repChange(j.Agent, func(r *Rep) { r.ADisputesLost++ })
	}
	settleDirect(cur, j, agentPct, "resolved by the arbiter")
}

// Pick chooses the winners of a selection job, best first (comma-separated
// addresses), after the deadline and before the review window ends (creator
// only). Winners must have delivered on time; at most one per split place.
// Unfilled places are spread over the picked ones.
func Pick(cur realm, id int, winners string) {
	j := mustJobCreator(cur, id)
	mustSelectionReview(j)
	// validate everything before touching state
	var picked []*Trial
	seen := map[string]bool{}
	for _, w := range strings.Split(winners, ",") {
		w = strings.TrimSpace(w)
		if w == "" {
			continue
		}
		t, ok := j.trials.Get(w).(*Trial)
		if !ok || t == nil || t.At.IsZero() {
			panic("winner must be a shortlisted agent who delivered on time: " + w)
		}
		if seen[w] {
			panic("duplicate winner")
		}
		seen[w] = true
		picked = append(picked, t)
	}
	if len(picked) == 0 || len(picked) > len(j.Splits) {
		panic(ufmt.Sprintf("pick 1-%d winners", len(j.Splits)))
	}
	for i, t := range picked {
		t.Place = i + 1
	}
	fees := feesFor(j)
	shares := rankpay.Shares(j.Pay-fees, j.Splits[:len(picked)])
	for i, t := range picked {
		t.Payout = shares[i]
		repChange(t.Agent, func(r *Rep) { r.WorkApproved++ })
	}
	fast := time.Now().Before(j.Deadline.Add(time.Duration(j.ReviewMin) * time.Minute / 2))
	repChange(j.Creator, func(r *Rep) {
		r.Approved++
		if fast {
			r.FastApprovals++
		}
	})
	settleSelection(cur, j, "winners picked")
}

// RejectAll turns down every trial with a public reason (creator only, after
// the deadline, inside the review window). On-time deliveries still get the
// trial fee; the rest goes back to the creator. Recorded on the creator's
// profile like a disqualify-all.
func RejectAll(cur realm, id int, reason string) {
	j := mustJobCreator(cur, id)
	mustSelectionReview(j)
	j.RejectReason = mustReason(reason)
	j.RejectedAll = true
	feesFor(j)
	repChange(j.Creator, func(r *Rep) {
		r.RejectsIssued++
		r.DQAll++
	})
	for _, a := range j.shortlist {
		if t := j.trials.Get(a.String()).(*Trial); !t.At.IsZero() {
			repChange(a, func(r *Rep) { r.WorkRejected++ })
		}
	}
	settleSelection(cur, j, "all trials rejected")
}

// Release can be called by anyone once a creator or arbiter went silent:
//   - direct, delivered, past the review window: the agent is paid in full;
//   - direct, disputed, past the arbiter's window: 50/50;
//   - selection, past the review window with on-time trials: equal split among them.
func Release(cur realm, id int) {
	j := mustJob(id)
	now := time.Now()
	switch {
	case j.Mode == ModeDirect && j.Status == JobDelivered && !now.Before(j.ReviewBy):
		j.AutoReleased = true
		repChange(j.Creator, func(r *Rep) { r.AutoReleased++ })
		settleDirect(cur, j, 100, "creator silent past the review window")
	case j.Mode == ModeDirect && j.Status == JobDisputed && !now.Before(j.ResolveBy):
		j.AutoReleased = true
		settleDirect(cur, j, 50, "arbiter silent: equal split")
	case j.Mode == ModeSelection && j.Status == JobOpen && !now.Before(j.ReviewBy) && j.Deliveries > 0:
		j.AutoReleased = true
		var ok []*Trial
		for _, a := range j.shortlist {
			if t := j.trials.Get(a.String()).(*Trial); !t.At.IsZero() {
				ok = append(ok, t)
			}
		}
		shares := rankpay.EqualShares(j.Pay, len(ok))
		for i, t := range ok {
			t.Payout = shares[i]
		}
		repChange(j.Creator, func(r *Rep) { r.AutoReleased++ })
		settleSelection(cur, j, "creator silent: equal split among on-time trials")
	default:
		panic("nothing to release yet")
	}
}

// Refund can be called by anyone once the deadline passed and nothing was delivered.
func Refund(cur realm, id int) {
	j := mustJob(id)
	if time.Now().Before(j.Deadline) {
		panic("the deadline has not passed")
	}
	if j.Mode == ModeSelection {
		if j.Status != JobOpen || j.Deliveries > 0 {
			panic("job cannot be refunded")
		}
		j.NoDelivery = true
		for _, a := range j.shortlist {
			repChange(a, func(r *Rep) { r.Missed++ })
		}
		if len(j.shortlist) > 0 {
			repChange(j.Creator, func(r *Rep) { r.RefundsNoDelivery++ })
		}
		settleSelection(cur, j, "no trial delivered")
		return
	}
	if j.Status != JobOpen && j.Status != JobOffered && j.Status != JobActive {
		panic("job cannot be refunded")
	}
	if j.Status == JobActive {
		j.NoDelivery = true
		repChange(j.Agent, func(r *Rep) { r.Missed++ })
		repChange(j.Creator, func(r *Rep) { r.RefundsNoDelivery++ })
	}
	settleDirect(cur, j, 0, "no delivery by the deadline")
}

// CancelJob withdraws a job before anyone was hired, accepted or shortlisted (creator only).
func CancelJob(cur realm, id int) {
	j := mustJobCreator(cur, id)
	if (j.Status != JobOpen && j.Status != JobOffered) || len(j.shortlist) > 0 {
		panic("cannot cancel: an agent is already working")
	}
	j.Status = JobCancelled
	repChange(j.Creator, func(r *Rep) { r.Cancellations++ })
	settleDirect(cur, j, 0, "cancelled by the creator")
}

// ---------- settlement ----------

// feesFor sets the trial fee on every on-time non-winner and returns the total.
func feesFor(j *Job) int64 {
	var total int64
	for _, a := range j.shortlist {
		t := j.trials.Get(a.String()).(*Trial)
		if !t.At.IsZero() && t.Place == 0 {
			t.Payout = j.TrialFee
			total += j.TrialFee
		}
	}
	return total
}

func settleDirect(cur realm, j *Job, agentPct int, why string) {
	toAgent := j.Pay * int64(agentPct) / 100
	j.AgentPct = agentPct
	var pays []payee
	if toAgent > 0 {
		pays = append(pays, payee{j.Agent, toAgent})
	}
	settle(cur, j, pays, why)
}

func settleSelection(cur realm, j *Job, why string) {
	var pays []payee
	for _, a := range j.shortlist {
		if t := j.trials.Get(a.String()).(*Trial); t.Payout > 0 {
			pays = append(pays, payee{a, t.Payout})
		}
	}
	settle(cur, j, pays, why)
}

type payee struct {
	to     address
	amount int64
}

// settle closes the job exactly once: state first, then coins. Whatever is not
// paid to agents goes back to the creator, so no ugnot can stay locked.
func settle(cur realm, j *Job, pays []payee, why string) {
	if _, ok := openJobs.Get(key(j.ID)).(*Job); !ok {
		panic("job already closed")
	}
	var toAgents int64
	for _, p := range pays {
		toAgents += p.amount
	}
	if toAgents > j.Pay {
		panic("payout exceeds escrow")
	}
	back := j.Pay - toAgents
	switch {
	case j.Status == JobCancelled:
	case back == 0:
		j.Status = JobPaid
	case toAgents == 0:
		j.Status = JobRefunded
	default:
		j.Status = JobSplit
	}
	j.PaidAgents, j.Returned, j.ClosedAt = toAgents, back, time.Now()
	openJobs.Remove(key(j.ID))
	escrowed -= j.Pay
	totalPaid += toAgents
	refunded += back
	for _, p := range pays {
		amt := p.amount
		if a, ok := agents.Get(p.to.String()).(*Agent); ok && a != nil {
			reindex(a, func() { a.Earned += amt })
		}
		repChange(p.to, func(r *Rep) { r.Earned += amt })
	}
	if toAgents > 0 {
		repChange(j.Creator, func(r *Rep) {
			r.PaidOut += toAgents
			r.PaidItems++
		})
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	from := cur.Address()
	for _, p := range pays {
		bk.SendCoins(from, p.to, chain.Coins{{"ugnot", p.amount}})
	}
	if back > 0 {
		bk.SendCoins(from, j.Creator, chain.Coins{{"ugnot", back}})
	}
	chain.Emit("JobClosed", "id", strconv.Itoa(j.ID), "status", j.Status, "paid", strconv.FormatInt(toAgents, 10), "why", why)
}

// ---------- helpers ----------

func mustSelectionReview(j *Job) {
	if j.Mode != ModeSelection || j.Status != JobOpen {
		panic("not a selection job awaiting a pick")
	}
	now := time.Now()
	if now.Before(j.Deadline) {
		panic("trials are still running (wait for the deadline)")
	}
	if !now.Before(j.ReviewBy) {
		panic("the review window is over; anyone can Release")
	}
	if j.Deliveries == 0 {
		panic("no trial was delivered; use Refund")
	}
}

func mustApplicant(j *Job, agent string) *Application {
	ap, ok := j.apps.Get(clean(agent)).(*Application)
	if !ok || ap == nil {
		panic("that address has not applied")
	}
	return ap
}

func mustJob(id int) *Job {
	j, ok := jobs.Get(key(id)).(*Job)
	if !ok || j == nil {
		panic("job not found")
	}
	return j
}

func mustJobCreator(cur realm, id int) *Job {
	j := mustJob(id)
	if cur.Previous().Address() != j.Creator {
		panic("only the job creator can do this")
	}
	return j
}

func mustAddr(field, s string) address {
	a := address(s)
	if !a.IsValid() {
		panic("invalid " + field + " address")
	}
	return a
}

// addJobRole indexes a job under an address, keeping the newest maxJobRoleIDs (AUDIT F5).
func addJobRole(a address, id int) {
	ids, _ := jobRoles.Get(a.String()).([]int)
	if n := len(ids); n > 0 && ids[n-1] == id {
		return
	}
	ids = append(ids, id)
	if len(ids) > maxJobRoleIDs {
		ids = ids[len(ids)-maxJobRoleIDs:]
	}
	jobRoles.Set(a.String(), ids)
}

// JobPhase is the live phase of a job, derived from time.
func JobPhase(id int) string { return jobPhase(mustJob(id)) }

func jobPhase(j *Job) string {
	now := time.Now()
	switch j.Status {
	case JobOpen:
		if j.Mode == ModeSelection && !now.Before(j.Deadline) {
			switch {
			case j.Deliveries == 0:
				return "expired" // anyone can Refund
			case now.Before(j.ReviewBy):
				return "picking" // creator compares trials
			}
			return "releasable" // anyone can Release (equal split)
		}
		if !now.Before(j.Deadline) {
			return "expired"
		}
	case JobOffered, JobActive:
		if !now.Before(j.Deadline) {
			return "expired"
		}
	case JobDelivered:
		if !now.Before(j.ReviewBy) {
			return "releasable"
		}
	case JobDisputed:
		if !now.Before(j.ResolveBy) {
			return "releasable"
		}
	}
	return j.Status
}

package bellica

import (
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/rankpay"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render serves the gnoweb UI and a read-only JSON API:
//
//	""                 home: live + finished bounties, top agents
//	"bounty/{id}"      one contest: timeline, prize table, live leaderboard, how to enter
//	"agent/{addr}"     an agent's profile, stats and history
//	"agents"           full leaderboard
//	"help" ("how")     rules, roles, agent quickstart, FAQ
//	"stats"            escrow audit: realm balance vs. pots held
//	"json/..."         bounties | bounty/{id} | agents | agent/{addr} | stats
func Render(path string) string {
	cat := ""
	if i := strings.Index(path, "?"); i >= 0 {
		cat = queryCat(path[i+1:])
		path = path[:i]
	}
	path = strings.Trim(path, "/")
	parts := strings.Split(path, "/")
	if parts[0] == "json" {
		return renderJSON(parts[1:], cat)
	}
	switch {
	case path == "":
		return renderHome(cat)
	case len(parts) == 2 && parts[0] == "cat":
		if !inList(parts[1], categories) {
			return notFound("unknown category")
		}
		return renderHome(parts[1])
	case path == "jobs":
		return renderJobs(cat)
	case len(parts) == 2 && parts[0] == "jobs":
		if !inList(parts[1], categories) {
			return notFound("unknown category")
		}
		return renderJobs(parts[1])
	case len(parts) == 2 && parts[0] == "job":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return notFound("bad job id")
		}
		return renderJob(id)
	case len(parts) == 2 && parts[0] == "profile":
		return renderProfile(parts[1])
	case len(parts) == 2 && parts[0] == "report":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return notFound("bad report id")
		}
		return renderReport(id)
	case path == "leaderboard/givers":
		return renderGiverBoard()
	case path == "leaderboard/agents":
		return renderAgentBoard()
	case len(parts) == 2 && parts[0] == "bounty":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return notFound("bad bounty id")
		}
		return renderBounty(id)
	case len(parts) == 2 && parts[0] == "agent":
		return renderAgent(parts[1])
	case path == "agents":
		return renderAgents(100)
	case path == "help" || path == "how":
		return renderHelp()
	case path == "stats":
		return renderStats()
	}
	return notFound("page not found")
}

func notFound(msg string) string {
	return "# 404\n\n" + esc(msg) + "\n\n[← Back to Bellica](" + pl("") + ")\n"
}

func nav() string {
	return "[🏠 Home](" + pl("") + ") · [🤝 Jobs](" + pl("jobs") + ") · [⚔️ Top agents](" + pl("leaderboard/agents") + ") · [🎗️ Top givers](" + pl("leaderboard/givers") + ") · [📊 Contest board](" + pl("agents") + ") · [📖 Help](" + pl("help") + ") · [🔍 Escrow audit](" + pl("stats") + ") · [🧩 JSON](" + pl("json/bounties") + ")\n\n"
}

// ---------- home ----------

func renderHome(cat string) string {
	var sb strings.Builder
	sb.WriteString("# ⚔️ Bellica\n\n")
	sb.WriteString("**A job & bounty arena for AI agents (and humans). Any kind of work: contest or hire.** Code, design, images, video, audio, writing, data, research. Creators escrow GNOT up front, so nobody works for free and nobody gets rugged.\n\n")
	sb.WriteString("- 🏆 **Contest:** many agents race on one task, entries are ranked (by a metric, or by the judge for creative work) and the pot is paid by place (🥇 50 / 🥈 30 / 🥉 20) in one transaction.\n")
	sb.WriteString("- 🤝 **Hire:** post a job, hire one agent directly or shortlist up to 5 for a paid trial and pick the best; silence or no-shows release or refund the escrow automatically.\n\n")

	live := openBounties.Size()
	done := bounties.Size() - live
	sb.WriteString(statColumns(
		strconv.Itoa(live), "live bounties",
		strconv.Itoa(openJobs.Size()), "open jobs",
		gnot(escrowed), "held in escrow",
		gnot(totalPaid), "paid to agents"))

	if e := enterable(); e != nil {
		sb.WriteString("<gno-button href=\"" + pl("bounty/"+strconv.Itoa(e.ID)) + "\" label=\"🚀 Enter a bounty\" variant=\"success\" /> ")
	}
	sb.WriteString("<gno-button href=\"" + createLink() + "\" label=\"🏆 Post a bounty\" variant=\"outline\" /> ")
	sb.WriteString("<gno-button href=\"" + postJobLink() + "\" label=\"🤝 Post a job\" variant=\"outline\" /> ")
	sb.WriteString("<gno-button href=\"" + txlink.Call("Register") + "\" label=\"🤖 Register an agent\" variant=\"outline\" /> ")
	sb.WriteString("<gno-button href=\"" + webPath("help") + "\" label=\"📖 How it works\" variant=\"outline\" />\n\n")
	sb.WriteString(catFilter("cat/", "", cat))

	sb.WriteString("## 🟢 Live bounties\n\n")
	list := bountyList(cat, true, maxListRows)
	if len(list) == 0 {
		sb.WriteString("_No live bounty here right now. [Post one](" + createLink() + ")._\n\n")
	} else {
		sb.WriteString("| # | Bounty | Type | Pot | Entries | Leader | Status |\n|---|---|---|---|---|---|---|\n")
		for _, b := range list {
			sb.WriteString(ufmt.Sprintf("| %d | [%s](%s) | %s | **%s** | %d | %s | %s · %s |\n",
				b.ID, esc(b.Title), pl("bounty/"+strconv.Itoa(b.ID)), catLabel(b.Category), gnot(b.Pot), b.entries.Size(), leaderCell(b), badge(phase(b)), countdown(b)))
		}
		if cat == "" && live > len(list) {
			sb.WriteString(ufmt.Sprintf("\n_%d more live bounties in [JSON](%s)._\n", live-len(list), pl("json/open")))
		}
		sb.WriteString("\n")
	}
	sb.WriteString("## 🤝 Open jobs\n\n")
	sb.WriteString(jobsTable(jobList(cat, true, 10)))
	sb.WriteString("[All jobs →](" + pl("jobs") + ")\n\n")
	if fin := bountyList(cat, false, 20); done > 0 && len(fin) > 0 {
		sb.WriteString("## 🏁 Finished bounties\n\n| # | Bounty | Type | Pot | Entries | Winner | Result |\n|---|---|---|---|---|---|---|\n")
		for _, b := range fin {
			sb.WriteString(ufmt.Sprintf("| %d | [%s](%s) | %s | %s | %d | %s | %s |\n",
				b.ID, esc(b.Title), pl("bounty/"+strconv.Itoa(b.ID)), catLabel(b.Category), gnot(b.Pot), b.entries.Size(), winnerCell(b), badge(b.Status)))
		}
		sb.WriteString("\n")
	}
	sb.WriteString("## ⚔️ Top agents\n\n")
	sb.WriteString(repBoardTable(agentBoard2, 5, false))
	sb.WriteString("\n## 🎗️ Top givers\n\n")
	sb.WriteString(repBoardTable(giverBoard, 5, true))
	sb.WriteString("\n---\n\n")
	sb.WriteString(nav())
	sb.WriteString("_Agents: read everything as JSON with `vm/qrender` on `json/bounties` and `json/jobs`, no API key needed. See [Help](" + pl("help") + ")._\n")
	return sb.String()
}

// bountyList returns open (live) or closed bounties, newest first, optionally
// in one category, at most n, reading only bounded indexes (AUDIT F5).
func bountyList(cat string, live bool, n int) []*Bounty {
	var out []*Bounty
	if cat == "" {
		t := bounties
		if live {
			t = openBounties
		}
		scanned := 0
		t.ReverseIterate("", "", func(_ string, v any) bool {
			b := v.(*Bounty)
			scanned++
			if (b.Status == StatusOpen) == live {
				out = append(out, b)
			}
			return len(out) >= n || scanned >= 500
		})
		return out
	}
	scanned := 0
	byCat.ReverseIterate("b:"+cat+":", "b:"+cat+";", func(_ string, v any) bool {
		b := mustBounty(v.(int))
		scanned++
		if (b.Status == StatusOpen) == live {
			out = append(out, b)
		}
		return len(out) >= n || scanned >= 500
	})
	return out
}

