	}
	sb.WriteString(ufmt.Sprintf("Best finish **%s** · average rank **%s** · win rate **%s** (of %d ranked finishes)\n\n", best, avg, wr, a.Ranked))

	sb.WriteString("## 📜 Contest history\n\n")
	ids, _ := entered.Get(addr).([]int)
