			}
			sb.WriteString(ufmt.Sprintf("| %s | %s | %s | %s | %s |\n", itemLink(rt.Kind, rt.ItemID), agentRef(rt.Rater), role, strings.Repeat("★", rt.Score), esc(rt.Comment)))
