package bellica

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Reputation for both sides, computed only from escrow outcomes and from
// ratings/reports by counterparties of finished, escrowed items.
//
// Escrow already makes non-payment impossible: once GNOT is posted it can only
// go to agents or, by the rules, back to the creator. Reputation covers what
// escrow cannot: unfair rejects, silence, self-judged disqualify-all.

// Rep holds outcome counters per address (giver side and agent side).
type Rep struct {
	Addr address
	// giver
	Posted             int   // bounties + jobs posted
	PaidOut            int64 // ugnot actually paid to agents
	PaidItems          int   // finished items that paid at least one agent
	Approved           int   // jobs approved / trial winners picked by the creator
	FastApprovals      int   // ... within the first half of the review window
	AutoReleased       int   // jobs paid only because the creator went silent
	JudgeSilent        int   // bounties where this judge missed the window (Fallback)
	RejectsIssued      int
	DeliveriesReceived int
	DisputesWon        int // arbiter ruled < 50% to the agent
	DisputesLost       int // arbiter ruled >= 50% to the agent
	RefundsNoDelivery  int // refunded because the hired agent never delivered
	DQAll              int // self-judged bounty with every entry DQ'd, or every trial rejected
	Cancellations      int
	// agent
	Hired         int // hired, accepted or shortlisted
	Delivered     int
	WorkApproved  int // approved jobs + picked trials
	WorkRejected  int
	Missed        int // hired but never delivered
	Wins          int // contest 1st places
	Podiums       int // contest paid places
	Earned        int64
	ADisputesWon  int
	ADisputesLost int
	// ratings and reports (by counterparties only)
	GiverRatingSum, GiverRatingN int
	AgentRatingSum, AgentRatingN int
	ReportsAgainst               int
	UpheldAgainst                int // reports with evidence that on-chain facts confirm
	ReportsFiled                 int
	giverKey, agentKey           string // current keys in the leaderboards
}

var (
	reps        = avl.NewTree() // address -> *Rep
	giverBoard  = avl.NewTree() // score key -> *Rep (givers who paid out)
	agentBoard2 = avl.NewTree() // score key -> *Rep (agents who earned)
	ratings     = avl.NewTree() // "kind:id:rater:target" -> *Rating
	ratingsOf   = avl.NewTree() // target -> []*Rating, newest 50
	reports     = avl.NewTree() // key(id) -> *Report
	nextReport  = 1
	reportPair  = avl.NewTree() // "kind:id:reporter:target" -> report id
	reportsOn   = avl.NewTree() // "kind:id" -> []int, newest 100
	reportsAbout = avl.NewTree() // target -> []int, newest 50
)

const (
	maxRatingsShown = 50
	maxReportsItem  = 100
	maxReportsAddr  = 50
	MinReportText   = 30
	MaxReportText   = 500
)

func repOf(a address) *Rep {
	if r, ok := reps.Get(a.String()).(*Rep); ok && r != nil {
		return r
	}
	return &Rep{Addr: a}
}

func peekRep(a address) *Rep {
	if r, ok := reps.Get(a.String()).(*Rep); ok && r != nil {
		return r
	}
	return nil
}

// repChange applies a change and keeps both leaderboards in sync.
func repChange(a address, change func(r *Rep)) {
	if a == "" {
		return
	}
	r := repOf(a)
	change(r)
	reps.Set(a.String(), r)
	if r.giverKey != "" {
		giverBoard.Remove(r.giverKey)
		r.giverKey = ""
	}
	if r.agentKey != "" {
		agentBoard2.Remove(r.agentKey)
		r.agentKey = ""
	}
	if r.PaidOut > 0 {
		r.giverKey = pad(9223372036854775807-giverScore(r), 19) + a.String()
		giverBoard.Set(r.giverKey, r)
	}
	if r.Earned > 0 {
		r.agentKey = pad(9223372036854775807-agentScore(r), 19) + a.String()
		agentBoard2.Set(r.agentKey, r)
	}
}

// ---------- scores, tiers, badges (documented in README) ----------

// avg10 is the average rating in tenths (e.g. 43 = 4.3), or -1 with no ratings.
func avg10(sum, n int) int {
	if n == 0 {
		return -1
	}
	return sum * 10 / n
}

func penalty(p int) int64 {
	if p < 0 {
		return 0
	}
	return int64(p)
}

// giverScore = paid out (milli-GNOT) × rating factor (avg/5, or 3/5 unrated)
// × max(0, 100 − 10·silent − 20·disputes lost − 25·upheld reports − 25·DQ-all) %.
func giverScore(r *Rep) int64 {
	a := avg10(r.GiverRatingSum, r.GiverRatingN)
	if a < 0 {
		a = 30
	}
	p := penalty(100 - 10*(r.AutoReleased+r.JudgeSilent) - 20*r.DisputesLost - 25*r.UpheldAgainst - 25*r.DQAll)
	return (r.PaidOut / 1000) * int64(a) * p / 5000
}

// agentScore = earned (milli-GNOT) × rating factor × max(0, 100 − 20·missed − 20·disputes lost − 25·upheld) %.
func agentScore(r *Rep) int64 {
	a := avg10(r.AgentRatingSum, r.AgentRatingN)
	if a < 0 {
		a = 30
	}
	p := penalty(100 - 20*r.Missed - 20*r.ADisputesLost - 25*r.UpheldAgainst)
	return (r.Earned / 1000) * int64(a) * p / 5000
}

var tierNames = []string{"Tiro", "Gladiator", "Veteran", "Centurion", "Champion", "Rudiarius"}
var tierIcons = []string{"🪵", "🗡️", "🛡️", "🦅", "🏆", "👑"}

// tier rule per level: successes, earned (GNOT), min average (tenths), min ratings.
var tierRules = [][4]int64{
	{0, 0, 0, 0},
	{1, 0, 0, 0},
	{3, 5, 35, 0},
	{10, 25, 40, 3},
	{25, 100, 43, 10},
	{50, 500, 46, 25},
}

// agentTier: the highest level whose rule holds (successes = approved work +
// contest paid places), then one level down per 2 strikes (upheld reports + missed deadlines).
func agentTier(r *Rep) int {
	if r == nil {
		return 0
	}
	succ := int64(r.WorkApproved + r.Podiums)
	a := avg10(r.AgentRatingSum, r.AgentRatingN)
	t := 0
	for lvl := 1; lvl < len(tierRules); lvl++ {
		rule := tierRules[lvl]
		if succ < rule[0] || r.Earned < rule[1]*1_000_000 || int64(r.AgentRatingN) < rule[3] {
			break
		}
		if rule[2] > 0 && a >= 0 && int64(a) < rule[2] {
			break
		}
		t = lvl
	}
	t -= (r.UpheldAgainst + r.Missed) / 2
	if t < 0 {
		t = 0
	}
	return t
}

func tierOf(a address) int { return agentTier(peekRep(a)) }

func tierLabel(t int) string { return tierIcons[t] + " " + tierNames[t] }

// Patron ladder for givers: 0 none, 1..3 Patron I..III, minus one per 2 strikes
// (silent auto-releases + lost disputes + upheld reports + DQ-all).
func patronLevel(r *Rep) int {
	if r == nil || r.PaidItems == 0 {
		return 0
	}
	a := avg10(r.GiverRatingSum, r.GiverRatingN)
	lvl := 1
	if r.PaidItems >= 5 && r.PaidOut >= 10_000_000 && (a < 0 || a >= 35) {
		lvl = 2
	}
	if lvl == 2 && r.PaidItems >= 20 && r.PaidOut >= 100_000_000 && r.GiverRatingN >= 5 && a >= 40 {
		lvl = 3
	}
	lvl -= (r.AutoReleased + r.DisputesLost + r.UpheldAgainst + r.DQAll) / 2
	if lvl < 0 {
		lvl = 0
	}
	return lvl
}

func patronLabel(l int) string {
	switch l {
	case 1:
		return "🎗️ Patron I"
	case 2:
		return "🎗️ Patron II"
	case 3:
		return "🎗️ Patron III"
	}
	return ""
}

// giverBadges: positive badges first, then warnings for agents' safety.
func giverBadges(r *Rep) []string {
	if r == nil || r.Posted == 0 {
		return nil
	}
	var out []string
	a := avg10(r.GiverRatingSum, r.GiverRatingN)
	silent := r.AutoReleased + r.JudgeSilent
	if r.PaidItems >= 3 && r.GiverRatingN >= 1 && a >= 40 {
		out = append(out, "🏅 Patron")
	}
	if r.FastApprovals >= 2 && silent == 0 {
		out = append(out, "⚡ Fast reviewer")
	}
	if r.PaidItems >= 3 && silent == 0 && r.DisputesLost == 0 && r.DQAll == 0 && r.UpheldAgainst == 0 {
		out = append(out, "✅ Reliable payer")
	}
	if silent >= 2 || (silent >= 1 && silent*4 >= r.PaidItems) {
		out = append(out, "🔕 Often silent")
	}
	if (r.DisputesLost >= 1 && r.DisputesLost >= r.DisputesWon) || r.UpheldAgainst >= 2 {
		out = append(out, "⚠️ Disputed")
	}
	if r.DQAll >= 1 {
		out = append(out, "🚫 Rejected everyone")
	}
	if r.RejectsIssued >= 3 && r.RejectsIssued*2 > r.DeliveriesReceived {
		out = append(out, "✂️ Harsh reviewer")
	}
	if len(out) == 0 && r.PaidItems == 0 {
		out = append(out, "🆕 New giver")
	}
	return out
}

func agentBadges(r *Rep) []string {
	if r == nil || (r.Hired == 0 && r.Podiums == 0 && r.Earned == 0) {
		return nil
	}
	var out []string
	a := avg10(r.AgentRatingSum, r.AgentRatingN)
	if r.WorkApproved+r.Podiums >= 3 && r.Missed == 0 && (a < 0 || a >= 40) {
		out = append(out, "⭐ Proven")
	}
	if r.Missed >= 2 || (r.Missed >= 1 && r.Missed*3 >= r.Hired) {
		out = append(out, "⏰ Misses deadlines")
	}
	if (r.ADisputesLost >= 1 && r.ADisputesLost >= r.ADisputesWon) || r.UpheldAgainst >= 2 {
		out = append(out, "⚠️ Disputed")
	}
	return out
}

// ---------- items and parties ----------

// partySides reports whether addr is on the giver side and/or the worker side
// of a finished, escrowed item ("job" or "bounty").
func partySides(kind string, id int, addr address) (giver, worker bool) {
	switch kind {
	case "job":
		j := mustJob(id)
		if !j.closed() || j.Status == JobCancelled {
			panic("only finished jobs can be rated or reported")
		}
		if addr == j.Creator {
			giver = true
		}
		if j.Mode == ModeSelection {
			if t, ok := j.trials.Get(addr.String()).(*Trial); ok && t != nil && !t.At.IsZero() {
				worker = true
			}
		} else if addr == j.Agent && j.Agent != "" {
			if j.Status != JobCancelled {
				worker = true
			}
		}
	case "bounty":
		b := mustBounty(id)
		if b.Status == StatusOpen || b.Status == StatusCancelled {
			panic("only finished bounties can be rated or reported")
		}
		if addr == b.Creator || addr == b.Judge {
			giver = true
		}
		if e, ok := b.entries.Get(addr.String()).(*Entry); ok && e != nil && (e.Payout > 0 || e.Disqualified) {
			worker = true
		}
	default:
		panic("kind must be job or bounty")
	}
	return
}

// mustCounterparties checks rater and target sit on opposite sides of the item.
// Returns true when the target is on the giver side.
func mustCounterparties(kind string, id int, rater, target address) bool {
	if rater == target {
		panic("you cannot rate or report yourself")
	}
	rg, rw := partySides(kind, id, rater)
	tg, tw := partySides(kind, id, target)
	switch {
	case rg && tw:
		return false
	case rw && tg:
		return true
	}
	panic("only counterparties of this item can rate or report each other")
}

// ---------- ratings ----------

type Rating struct {
	Kind    string
	ItemID  int
	Rater   address
	Target  address
	Score   int
	Comment string
	AsGiver bool // the target was rated in their giver role
	At      time.Time
}

// Rate scores a counterparty of a finished job or bounty from 1 to 5 with an
// optional comment (max 280 chars). One rating per rater, target and item.
func Rate(cur realm, kind string, id int, target string, score int, comment string) {
	rater := cur.Previous().Address()
	kind = strings.ToLower(clean(kind))
	t := mustAddr("target", clean(target))
	asGiver := mustCounterparties(kind, id, rater, t)
	if score < 1 || score > 5 {
		panic("score must be 1-5")
	}
	comment = clean(comment)
	mustLen("comment", comment, 0, MaxText)
	k := kind + ":" + strconv.Itoa(id) + ":" + rater.String() + ":" + t.String()
	if ratings.Has(k) {
		panic("you already rated this counterparty for this item")
	}
	rt := &Rating{Kind: kind, ItemID: id, Rater: rater, Target: t, Score: score, Comment: comment, AsGiver: asGiver, At: time.Now()}
	ratings.Set(k, rt)
	list, _ := ratingsOf.Get(t.String()).([]*Rating)
	list = append(list, rt)
	if len(list) > maxRatingsShown {
		list = list[len(list)-maxRatingsShown:]
	}
	ratingsOf.Set(t.String(), list)
	repChange(t, func(r *Rep) {
		if asGiver {
			r.GiverRatingSum += score
			r.GiverRatingN++
		} else {
			r.AgentRatingSum += score
			r.AgentRatingN++
		}
	})
	chain.Emit("Rated", "kind", kind, "id", strconv.Itoa(id), "rater", rater.String(), "target", t.String(), "score", strconv.Itoa(score))
}

// ---------- reports ----------

var reportReasons = []string{"non_payment_attempt", "unfair_reject", "unfair_dq", "spam", "plagiarism", "other"}

func evidenceRequired(reason string) bool {
	switch reason {
	case "non_payment_attempt", "unfair_reject", "unfair_dq", "plagiarism":
		return true
	}
	return false
}

type ReportRec struct {
	ID          int
	Kind        string
	ItemID      int
	Reporter    address
	Target      address
	Reason      string
	Text        string
	Evidence    string
	Facts       string // on-chain facts of the item, snapshot at report time
	Upheld      bool   // evidence given and the on-chain facts confirm it
	Basis       string // why it is upheld
	At          time.Time
	Response    string
	RespondedAt time.Time
}

// Report files a public report against a counterparty of a finished job or
// bounty. reason: non_payment_attempt, unfair_reject, unfair_dq, spam,
// plagiarism or other. text: 30-500 chars explaining what happened. evidence:
// https/ipfs link, required for every reason except spam and other.
// No on-chain punishment: reports are shown on the item and the profile, and
// only upheld ones (evidence + confirming on-chain facts) count in badges/scores.
func Report(cur realm, kind string, id int, target, reason, text, evidence string) int {
	rep := cur.Previous().Address()
	kind = strings.ToLower(clean(kind))
	t := mustAddr("target", clean(target))
	targetIsGiver := mustCounterparties(kind, id, rep, t)
	reason = strings.ToLower(clean(reason))
	if !inList(reason, reportReasons) {
		panic("reason must be one of " + strings.Join(reportReasons, ", "))
	}
	text = mustReportText(text)
	if clean(evidence) != "" {
		evidence = mustWorkURL("evidence", evidence)
	} else {
		evidence = ""
	}
	if evidenceRequired(reason) && evidence == "" {
		panic("an evidence link (https or ipfs) is required for " + reason)
	}
	pk := kind + ":" + strconv.Itoa(id) + ":" + rep.String() + ":" + t.String()
	if reportPair.Has(pk) {
		panic("you already reported this counterparty for this item")
	}
	r := &ReportRec{ID: nextReport, Kind: kind, ItemID: id, Reporter: rep, Target: t, Reason: reason, Text: text, Evidence: evidence, At: time.Now()}
	r.Facts = itemFacts(kind, id, rep, t)
	if evidence != "" {
		r.Upheld, r.Basis = upheld(kind, id, rep, t, targetIsGiver, reason)
	}
	reports.Set(key(r.ID), r)
	reportPair.Set(pk, r.ID)
	nextReport++
	ik := kind + ":" + strconv.Itoa(id)
	ids, _ := reportsOn.Get(ik).([]int)
	if len(ids) < maxReportsItem {
		reportsOn.Set(ik, append(ids, r.ID))
	}
	aids, _ := reportsAbout.Get(t.String()).([]int)
	aids = append(aids, r.ID)
	if len(aids) > maxReportsAddr {
		aids = aids[len(aids)-maxReportsAddr:]
	}
	reportsAbout.Set(t.String(), aids)
	repChange(t, func(x *Rep) {
		x.ReportsAgainst++
		if r.Upheld {
			x.UpheldAgainst++
		}
	})
	repChange(rep, func(x *Rep) { x.ReportsFiled++ })
	chain.Emit("Reported", "report", strconv.Itoa(r.ID), "kind", kind, "id", strconv.Itoa(id), "target", t.String(), "reason", reason, "upheld", strconv.FormatBool(r.Upheld))
	return r.ID
}

// Respond posts the reported party's single public answer to a report.
func Respond(cur realm, reportID int, text string) {
	caller := cur.Previous().Address()
	r, ok := reports.Get(key(reportID)).(*ReportRec)
	if !ok || r == nil {
		panic("report not found")
	}
	if caller != r.Target {
		panic("only the reported party can respond")
	}
	if r.Response != "" {
		panic("already responded")
	}
	r.Response = mustReportText(text)
	r.RespondedAt = time.Now()
	chain.Emit("ReportAnswered", "report", strconv.Itoa(reportID))
}

// mustReportText: 30-500 chars, single line, and not filler (AUDIT H5): at
// least 8 distinct letters/digits and no single character over half the text.
func mustReportText(s string) string {
	s = clean(s)
	mustLen("text", s, MinReportText, MaxReportText)
	seen := map[rune]int{}
	total, distinct, top := 0, 0, 0
	for _, r := range s {
		if r == ' ' {
			continue
		}
		total++
		if seen[r] == 0 && (r >= '0' && r <= '9' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r > 127) {
			distinct++
		}
		seen[r]++
		if seen[r] > top {
			top = seen[r]
		}
	}
	if distinct < 8 || top*2 > total {
		panic("text must explain what happened (not repeated characters)")
	}
	return s
}

// itemFacts snapshots the recorded on-chain facts relevant to a report.
func itemFacts(kind string, id int, reporter, target address) string {
	if kind == "job" {
		j := mustJob(id)
		s := ufmt.Sprintf("job #%d (%s) %s · pay %s · outcome %s", j.ID, j.Mode, j.Status, gnot(j.Pay), j.Status)
		if j.Mode == ModeDirect {
			if !j.DeliveredAt.IsZero() {
				s += " · delivered " + when(j.DeliveredAt) + " (" + j.Kind + ")"
			} else {
				s += " · never delivered"
			}
			s += ufmt.Sprintf(" · %d reject(s)", j.Rejects)
			if j.RejectReason != "" {
				s += " · last reject reason: " + j.RejectReason
			}
			s += ufmt.Sprintf(" · agent got %d%%", j.AgentPct)
		} else {
			s += ufmt.Sprintf(" · %d trial(s) delivered of %d shortlisted", j.Deliveries, len(j.shortlist))
			if j.RejectedAll {
				s += " · creator rejected all trials: " + j.RejectReason
			}
		}
		if j.Resolved {
			s += " · resolved by the arbiter"
		}
		if j.AutoReleased {
			s += " · paid by auto-release (silence)"
		}
		return s
	}
	b := mustBounty(id)
	s := ufmt.Sprintf("bounty #%d %s · pot %s · paid %s", b.ID, b.Status, gnot(b.Pot), gnot(b.Paid))
	if b.selfJudged() {
		s += " · self-judged"
	}
	for _, a := range []address{reporter, target} {
		if e, ok := b.entries.Get(a.String()).(*Entry); ok && e != nil {
			if e.Disqualified {
				s += " · " + a.String()[:10] + "… DQ'd: " + e.DQReason
			} else if e.Payout > 0 {
				s += " · " + a.String()[:10] + "… paid " + gnot(e.Payout)
			}
		}
	}
	return s
}

// upheld: does the item's recorded outcome confirm the report? Never decided
// by votes, only by escrow facts (arbiter ruling, silence, self-judged DQ-all).
func upheld(kind string, id int, reporter, target address, targetIsGiver bool, reason string) (bool, string) {
	if kind == "job" {
		j := mustJob(id)
		if j.Resolved {
			if targetIsGiver && j.AgentPct >= 50 {
				return true, "the arbiter ruled for the agent"
			}
			if !targetIsGiver && j.AgentPct < 50 {
				return true, "the arbiter ruled for the creator"
			}
		}
		if targetIsGiver && j.AutoReleased && j.Mode == ModeDirect && (reason == "unfair_reject" || reason == "non_payment_attempt") {
			return true, "the creator went silent and the pay was auto-released"
		}
		if !targetIsGiver && j.NoDelivery {
			return true, "the agent never delivered"
		}
		return false, ""
	}
	b := mustBounty(id)
	if targetIsGiver && reason == "unfair_dq" && b.DQAll {
		if e, ok := b.entries.Get(reporter.String()).(*Entry); ok && e != nil && e.Disqualified {
			return true, "self-judged bounty disqualified every entry"
		}
	}
	return false, ""
}

func mustTier(t int) {
	if t < 0 || t >= len(tierNames) {
		panic("minTier must be 0-5 (0 = any)")
	}
}

// mustMinTier gates Apply / Accept / Submit on a job or bounty's minimum tier.
func mustMinTier(a address, min int) {
	if min > 0 && tierOf(a) < min {
		panic("this requires tier " + tierNames[min] + " or higher; yours is " + tierNames[tierOf(a)])
	}
}

package bellica

import (
	"strings"
)

// Any kind of work: categories, deliverables and their validation.
// Files never live on-chain: a deliverable is a kind + an https:// or ipfs://
// URL + an optional sha256 of the content + a short note (or, for kind
// "text", up to 2,000 characters of text).

// Categories (fixed list). Empty input means "other".
var categories = []string{"code", "design", "image", "video", "audio", "writing", "data", "research", "other"}

// Deliverable kinds.
var deliverKinds = []string{"link", "image", "video", "file", "text", "repo"}

const (
	MaxDeliverText  = 2000 // bytes, kind "text"
	maxDeliverLines = 40
)

func inList(s string, list []string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// mustCategory normalizes and validates a category ("" -> "other").
func mustCategory(c string) string {
	c = strings.ToLower(clean(c))
	if c == "" {
		return "other"
	}
	if !inList(c, categories) {
		panic("unknown category: use one of " + strings.Join(categories, ", "))
	}
	return c
}

// subjective categories are scored by the judge's assessment, not a metric.
func subjective(c string) bool {
	switch c {
	case "design", "image", "video", "audio", "writing":
		return true
	}
	return false
}

func scoringOf(c string) string {
	if subjective(c) {
		return "judge"
	}
	return "metric"
}

// mustWorkURL accepts only https:// (with a real host, no userinfo) or
// ipfs://<cid>[/path], at most MaxURL bytes, without characters that can
// break markdown links or HTML attributes (AUDIT H1).
func mustWorkURL(field, u string) string {
	u = clean(u)
	mustLen(field, u, 10, MaxURL)
	if strings.ContainsAny(u, " ()<>[]{}\"'`|\\^") {
		panic(field + " contains characters that are not allowed in a URL")
	}
	switch {
	case strings.HasPrefix(u, "https://"):
		rest := u[len("https://"):]
		host := rest
		if i := strings.IndexAny(rest, "/?#"); i >= 0 {
			host = rest[:i]
		}
		if host == "" || strings.Contains(host, "@") || !strings.Contains(host, ".") && host != "localhost" {
			panic(field + " needs a valid https host")
		}
	case strings.HasPrefix(u, "ipfs://"):
		rest := u[len("ipfs://"):]
		cid := rest
		if i := strings.Index(rest, "/"); i >= 0 {
			cid = rest[:i]
		}
		if len(cid) < 10 || !alnum(cid) {
			panic(field + " needs a valid ipfs CID")
		}
	default:
		panic(field + " must start with https:// or ipfs://")
	}
	return u
}

func alnum(s string) bool {
	for _, r := range s {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z') {
			return false
		}
	}
	return true
}

// mustHash accepts "" or a sha256 hex digest (optionally "sha256:"-prefixed), stored lowercase.
func mustHash(h string) string {
	h = strings.ToLower(clean(h))
	h = strings.TrimPrefix(h, "sha256:")
	if h == "" {
		return ""
	}
	if len(h) != 64 {
		panic("sha256 must be 64 hex characters")
	}
	for _, r := range h {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') {
			panic("sha256 must be 64 hex characters")
		}
	}
	return h
}

// cleanText is clean() for multi-line text: line breaks are kept (as \n),
// everything else clean() drops is dropped.
func cleanText(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	return clean(s)
}

// mustDeliverable validates a deliverable and returns its normalized parts.
// kind "text" carries text (URL optional); every other kind needs a URL and no text.
func mustDeliverable(kind, url, hash, text string) (string, string, string, string) {
	kind = strings.ToLower(clean(kind))
	if !inList(kind, deliverKinds) {
		panic("unknown deliverable kind: use one of " + strings.Join(deliverKinds, ", "))
	}
	hash = mustHash(hash)
	text = cleanText(text)
	if kind == "text" {
		if len(text) < 1 || len(text) > MaxDeliverText {
			panic("text must be 1-2000 characters")
		}
		if strings.Count(text, "\n") >= maxDeliverLines {
			panic("text must be at most 40 lines")
		}
		if clean(url) != "" {
			url = mustWorkURL("url", url)
		} else {
			url = ""
		}
		return kind, url, hash, text
	}
	if text != "" {
		panic("text is only for kind text; link the file instead")
	}
	return kind, mustWorkURL("url", url), hash, ""
}

// ---------- rendering ----------

func kindIcon(k string) string {
	switch k {
	case "image":
		return "🖼️"
	case "video":
		return "🎬"
	case "file":
		return "📄"
	case "text":
		return "📝"
	case "repo":
		return "💻"
	}
	return "🔗"
}

func catIcon(c string) string {
	switch c {
	case "code":
		return "💻"
	case "design":
		return "🎨"
	case "image":
		return "🖼️"
	case "video":
		return "🎬"
	case "audio":
		return "🎧"
	case "writing":
		return "✍️"
	case "data":
		return "📊"
	case "research":
		return "🔬"
	}
	return "🧩"
}

func catLabel(c string) string { return catIcon(c) + " " + c }

// workLink renders a stored work URL. https links become markdown links with
// the full host visible (AUDIT F6); ipfs:// links point at a public gateway.
func workLink(u string) string {
	if strings.HasPrefix(u, "ipfs://") {
		rest := u[len("ipfs://"):]
		label := rest
		if r := []rune(label); len(r) > 24 {
			label = string(r[:23]) + "…"
		}
		return "[ipfs://" + esc(label) + "](https://ipfs.io/ipfs/" + rest + ")"
	}
	return link(u)
}

// deliverableLine renders kind + link + hash (+ commit for repos).
func deliverableLine(kind, url, hash, commit string) string {
	s := kindIcon(kind) + " " + esc(kind)
	if url != "" {
		s += " · " + workLink(url)
	}
	if commit != "" {
		s += " @ `" + esc(shortCommit(commit)) + "`"
	}
	if hash != "" {
		s += " · sha256 `" + hash[:12] + "…`"
	}
	return s
}

// quoteText renders multi-line user text as an escaped blockquote. Every line
// is escaped, and line starts that markdown would read as a list, rule or
// setext heading are escaped too (AUDIT H2).
func quoteText(t string) string {
	var sb strings.Builder
	for _, line := range strings.Split(t, "\n") {
		sb.WriteString("> " + escLine(line) + "\n")
	}
	return sb.String()
}

func escLine(line string) string {
	line = strings.TrimSpace(line)
	if line == "" {
		return ""
	}
	out := esc(line)
	switch line[0] {
	case '-', '+', '=', '.':
		out = "\\" + out
	}
	// "1." / "1)" ordered-list starts
	i := 0
	for i < len(line) && line[i] >= '0' && line[i] <= '9' {
		i++
	}
	if i > 0 && i < len(line) && (line[i] == '.' || line[i] == ')') {
		out = line[:i] + "\\" + esc(line[i:])
	}
	return out
}

// catFilter renders a row of category filter links for a page prefix ("cat/" or "jobs/").
func catFilter(prefix, all, cur string) string {
	var sb strings.Builder
	sb.WriteString("Filter: ")
	if cur == "" {
		sb.WriteString("**all**")
	} else {
		sb.WriteString("[all](" + pl(all) + ")")
	}
	for _, c := range categories {
		sb.WriteString(" · ")
		if c == cur {
			sb.WriteString("**" + catLabel(c) + "**")
		} else {
			sb.WriteString("[" + catLabel(c) + "](" + pl(prefix+c) + ")")
		}
	}
	return sb.String() + "\n\n"
}

package agentmarketplace

import (
	"chain"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"time"
)

// PostHashTask is like PostTask, but settlement requires the winning agent
// to reveal a preimage of commitHash (lowercase hex SHA-256 of the expected
// result). If they miss RevealBy, anyone may call TimeoutHashTask to refund
// the poster. The budget is still sent with the call and held in escrow.
func PostHashTask(cur realm, title, description, specialty string, budgetUgnot int64, commitHash string, deadlineSecs int64) int {
	caller := mustUserCall(cur)
	checkText("title", title, minTitleLen, maxTitleLen)
	checkText("description", description, minDescLen, maxDescLen)
	spec := checkSpecialty(specialty)
	checkBudget(budgetUgnot)
	hash := checkCommitHash(commitHash)
	checkRevealDeadline(deadlineSecs)
	requireExactUgnotSend(budgetUgnot)
	if tasks.Size() >= maxTasks {
		panic("the task board is full")
	}

	now := time.Now()
	t := &Task{
		ID:          nextTaskID,
		Poster:      caller,
		Title:       title,
		Description: description,
		Specialty:   spec,
		BudgetUgnot: budgetUgnot,
		Status:      StatusOpen,
		PostedAt:    now,
		CommitHash:  hash,
		RevealBy:    now.Add(time.Duration(deadlineSecs) * time.Second),
	}
	nextTaskID++
	tasks.Set(padID(t.ID), t)
	chain.Emit("TaskPosted",
		"id", strconv.Itoa(t.ID),
		"poster", caller.String(),
		"specialty", spec,
		"budgetUgnot", strconv.FormatInt(budgetUgnot, 10),
		"commitHash", hash,
	)
	return t.ID
}

// RevealAndComplete is the hash-commit settle path: only the winning agent
// may call it, and only if sha256(preimage) matches the posted commit hash.
// On a match, escrow is released exactly as in CompleteTask.
func RevealAndComplete(cur realm, taskID int, preimage string) {
	caller := mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.CommitHash == "" {
		panic("this task does not use hash-commit settlement; call CompleteTask")
	}
	if t.Status != StatusInProgress {
		panic("only an in-progress task can be completed")
	}
	if t.Winner != caller {
		panic("only the winning agent can mark this task complete")
	}
	if t.Settled {
		panic("this task has already been settled")
	}
	if preimage == "" {
		panic("preimage must not be empty")
	}
	got := sha256Hex(preimage)
	if got != t.CommitHash {
		panic("preimage does not match the commit hash")
	}
	if !t.RevealBy.IsZero() && time.Now().After(t.RevealBy) {
		panic("the reveal deadline has passed; the poster can be refunded with TimeoutHashTask")
	}
	settleTask(cur, t, "hash")
}

// TimeoutHashTask refunds a hash-commit task to the poster after the
// reveal deadline, if it is still in progress and unpaid. Anyone may call it.
func TimeoutHashTask(cur realm, taskID int) {
	mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.CommitHash == "" {
		panic("this task does not use hash-commit settlement")
	}
	if t.Status != StatusInProgress {
		panic("only an in-progress hash task can time out")
	}
	if t.Settled {
		panic("this task has already been settled")
	}
	if t.RevealBy.IsZero() || !time.Now().After(t.RevealBy) {
		panic("the reveal deadline has not passed")
	}

	t.Status = StatusCancelled
	t.Settled = true
	chain.Emit("TaskCancelled",
		"task", strconv.Itoa(taskID),
		"poster", t.Poster.String(),
		"refundedUgnot", strconv.FormatInt(t.BudgetUgnot, 10),
		"reason", "reveal-timeout",
	)
	sendUgnot(cur, t.Poster, t.BudgetUgnot)
}

func sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

package agentmarketplace

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const knownPhrase = "the expected result phrase"

func TestHashCommitHappyPath(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	hash := sha256Hex(knownPhrase)
	id := postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 2000000, hash, 3600)
	tk := mustGetTask(id)
	uassert.Equal(t, hash, tk.CommitHash)
	uassert.False(t, tk.RevealBy.IsZero())

	bidID := bid(cur, carol, id, 1500000, "I know it")
	accept(cur, alice, id, bidID)

	urequire.AbortsWithMessage(t, cur, "this task requires a hash reveal: call RevealAndComplete", func() {
		complete(cur, carol, id)
	})
	urequire.AbortsWithMessage(t, cur, "preimage does not match the commit hash", func() {
		reveal(cur, carol, id, "wrong phrase")
	})
	urequire.AbortsWithMessage(t, cur, "preimage must not be empty", func() {
		reveal(cur, carol, id, "")
	})
	urequire.AbortsWithMessage(t, cur, "only the winning agent can mark this task complete", func() {
		reveal(cur, alice, id, knownPhrase)
	})

	reveal(cur, carol, id, knownPhrase)
	tk = mustGetTask(id)
	uassert.Equal(t, StatusCompleted, tk.Status)
	uassert.True(t, tk.Settled)
	uassert.Equal(t, 1, mustGetAgent(carol).Completed)

	// poster can rate after a hash settlement just like a normal one
	rid := rate(cur, alice, id, 5, "Hash matched")
	uassert.Equal(t, 1, rid)
	_, trust, _, _ := ScoreOf(carol)
	uassert.Equal(t, int64(5000), trust)
}

func TestHashCommitRefusesOrdinaryCompleteAndViceVersa(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	ordinary := settleJob(cur, alice, carol, "Ordinary research", "This task has no commit hash.", "research", 2000000)
	urequire.AbortsWithMessage(t, cur, "this task does not use hash-commit settlement; call CompleteTask", func() {
		reveal(cur, carol, ordinary, knownPhrase)
	})

	hash := sha256Hex(knownPhrase)
	id := postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 1000000, hash, 3600)
	bidID := bid(cur, carol, id, 1000000, "ready")
	accept(cur, alice, id, bidID)
	urequire.AbortsWithMessage(t, cur, "this task requires a hash reveal: call RevealAndComplete", func() {
		complete(cur, carol, id)
	})
}

func TestHashCommitTimeoutRefund(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	hash := sha256Hex(knownPhrase)
	id := postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 2000000, hash, minRevealSecs)
	bidID := bid(cur, carol, id, 2000000, "ready")
	accept(cur, alice, id, bidID)

	urequire.AbortsWithMessage(t, cur, "the reveal deadline has not passed", func() {
		timeoutHash(cur, bob, id)
	})

	// min reveal is 60s; each height is 5s, so 13 heights is past the deadline.
	testing.SkipHeights(13)
	urequire.AbortsWithMessage(t, cur, "the reveal deadline has passed; the poster can be refunded with TimeoutHashTask", func() {
		reveal(cur, carol, id, knownPhrase)
	})

	timeoutHash(cur, bob, id) // anyone may time it out
	tk := mustGetTask(id)
	uassert.Equal(t, StatusCancelled, tk.Status)
	uassert.True(t, tk.Settled)

	urequire.AbortsWithMessage(t, cur, "only an in-progress hash task can time out", func() {
		timeoutHash(cur, alice, id)
	})
	urequire.AbortsWithMessage(t, cur, "only a settled, completed task can be rated", func() {
		rate(cur, alice, id, 5, "timed out")
	})
}

func TestHashCommitValidation(cur realm, t *testing.T) {
	reset()
	urequire.AbortsWithMessage(t, cur, "commit hash must be a 64-character hex SHA-256 digest", func() {
		postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 1000000, "abc", 3600)
	})
	urequire.AbortsWithMessage(t, cur, "commit hash must be a 64-character hex SHA-256 digest", func() {
		postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 1000000, "gg"+sha256Hex(knownPhrase)[2:], 3600)
	})
	urequire.AbortsWithMessage(t, cur, "reveal deadline must be between 60 seconds and 30 days", func() {
		postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 1000000, sha256Hex(knownPhrase), 59)
	})
	// uppercase hex is accepted and stored in lowercase
	lower := sha256Hex(knownPhrase)
	upper := toUpperHex(lower)
	id := postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 1000000, upper, 3600)
	uassert.Equal(t, lower, mustGetTask(id).CommitHash)
}

func TestHashCommitOpenCancelStillWorks(cur realm, t *testing.T) {
	reset()
	id := postHash(cur, alice, "Known answer task", "Reveal the phrase I already committed to.", "research", 2000000, sha256Hex(knownPhrase), 3600)
	cancel(cur, alice, id)
	uassert.Equal(t, StatusCancelled, mustGetTask(id).Status)
	uassert.True(t, mustGetTask(id).Settled)
}

func toUpperHex(s string) string {
	out := ""
	for _, c := range s {
		if c >= 'a' && c <= 'f' {
			out += string(c - ('a' - 'A'))
		} else {
			out += string(c)
		}
	}
	return out
}

package agentmarketplace

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Tunables.
const (
	maxAgents      = 1000
	maxTasks       = 5000
	maxBidsPerTask = 50
)

var (
	nextTaskID = 1
	nextBidID  = 1

	agents     = avl.NewTree() // owner.String() -> *Agent
	tasks      = avl.NewTree() // padID(taskID) -> *Task
	bids       = avl.NewTree() // padID(taskID) + "/" + padID(bidID) -> *Bid
	bidByAgent = avl.NewTree() // owner + "/" + padID(taskID) -> bidID
)

// realmURL is this realm's gnoweb path, e.g. /r/demo/agentmarketplace.
var realmURL string

func init(cur realm) {
	realmURL = strings.TrimPrefix(cur.PkgPath(), "gno.land")
}

// ---------------------------------------------------------------------------
// Agent actions. Every crossing function is a signed transaction, so the
// caller address is authenticated by the chain itself.

// RegisterAgent registers the caller as an agent. name is a display name,
// tags is a comma-separated list of specialties, rateKind is "hourly" or
// "flat", and rateUgnot is the listed price in ugnot (1 GNOT = 1,000,000 ugnot).
// The caller's address is the agent id; an address may register only once.
func RegisterAgent(cur realm, name, tags, rateKind string, rateUgnot int64) {
	caller := mustUserCall(cur)
	if agents.Get(caller.String()) != nil {
		panic("this address is already registered as an agent")
	}
	if agents.Size() >= maxAgents {
		panic("the agent registry is full")
	}
	checkText("name", name, minNameLen, maxNameLen)
	canonical := parseTags(tags)
	checkRateKind(rateKind)
	checkRate(rateUgnot)

	a := &Agent{
		Owner:        caller,
		Name:         name,
		Tags:         canonical,
		RateKind:     rateKind,
		RateUgnot:    rateUgnot,
		RegisteredAt: time.Now(),
	}
	agents.Set(caller.String(), a)
	chain.Emit("AgentRegistered",
		"agent", caller.String(),
		"name", name,
		"tags", canonical,
		"rateKind", rateKind,
		"rateUgnot", strconv.FormatInt(rateUgnot, 10),
	)
}

// UpdateAgent changes the caller's display name, specialties and rate.
func UpdateAgent(cur realm, name, tags, rateKind string, rateUgnot int64) {
	caller := mustUserCall(cur)
	a := mustGetAgent(caller)
	checkText("name", name, minNameLen, maxNameLen)
	canonical := parseTags(tags)
	checkRateKind(rateKind)
	checkRate(rateUgnot)
	a.Name = name
	a.Tags = canonical
	a.RateKind = rateKind
	a.RateUgnot = rateUgnot
	chain.Emit("AgentUpdated",
		"agent", caller.String(),
		"name", name,
		"tags", canonical,
		"rateKind", rateKind,
		"rateUgnot", strconv.FormatInt(rateUgnot, 10),
	)
}

// ---------------------------------------------------------------------------
// Tasks and escrow.

// PostTask posts a new open task and escrows the budget. The caller must
// attach exactly budgetUgnot ugnot with the transaction (-send). Only a
// direct user call is accepted, so OriginSend cannot be spoofed by an
// intermediate realm. Returns the new task ID.
func PostTask(cur realm, title, description, specialty string, budgetUgnot int64) int {
	caller := mustUserCall(cur)
	checkText("title", title, minTitleLen, maxTitleLen)
	checkText("description", description, minDescLen, maxDescLen)
	spec := checkSpecialty(specialty)
	checkBudget(budgetUgnot)
	requireExactUgnotSend(budgetUgnot)
	if tasks.Size() >= maxTasks {
		panic("the task board is full")
	}

	t := &Task{
		ID:          nextTaskID,
		Poster:      caller,
		Title:       title,
		Description: description,
		Specialty:   spec,
		BudgetUgnot: budgetUgnot,
		Status:      StatusOpen,
		PostedAt:    time.Now(),
	}
	nextTaskID++
	tasks.Set(padID(t.ID), t)
	chain.Emit("TaskPosted",
		"id", strconv.Itoa(t.ID),
		"poster", caller.String(),
		"specialty", spec,
		"budgetUgnot", strconv.FormatInt(budgetUgnot, 10),
	)
	return t.ID
}

// PlaceBid lets a registered agent offer to do an open task. The agent must
// list the task's required specialty. One bid per agent per task; a later
// call updates the amount and note. Returns the bid ID. Agents cannot bid
// on their own tasks.
func PlaceBid(cur realm, taskID int, amountUgnot int64, note string) int {
	caller := mustUserCall(cur)
	a := mustGetAgent(caller)
	t := mustGetTask(taskID)
	if t.Status != StatusOpen {
		panic("bids are only accepted on open tasks")
	}
	if t.Poster == caller {
		panic("the task poster cannot bid on their own task")
	}
	if !agentHasSpecialty(a.Tags, t.Specialty) {
		panic("this agent does not list the required specialty: " + t.Specialty)
	}
	if amountUgnot < 1 || amountUgnot > t.BudgetUgnot {
		panic("bid amount must be between 1 and the task budget of " + strconv.FormatInt(t.BudgetUgnot, 10) + " ugnot")
	}
	if note != "" {
		checkText("note", note, 1, maxNoteLen)
	}

	if existing := bidByAgent.Get(caller.String() + "/" + padID(taskID)); existing != nil {
		bidID := existing.(int)
		b := mustGetBid(taskID, bidID)
		b.Amount = amountUgnot
		b.Note = note
		b.PlacedAt = time.Now()
		chain.Emit("BidUpdated",
			"task", strconv.Itoa(taskID),
			"bid", strconv.Itoa(bidID),
			"agent", caller.String(),
			"amountUgnot", strconv.FormatInt(amountUgnot, 10),
		)
		return bidID
	}
	if taskBidCount(taskID) >= maxBidsPerTask {
		panic("this task already has the maximum number of bids")
	}

	b := &Bid{
		ID:       nextBidID,
		TaskID:   taskID,
		Agent:    caller,
		Amount:   amountUgnot,
		Note:     note,
		PlacedAt: time.Now(),
	}
	nextBidID++
	bids.Set(bidKey(taskID, b.ID), b)
	bidByAgent.Set(caller.String()+"/"+padID(taskID), b.ID)
	chain.Emit("BidPlaced",
		"task", strconv.Itoa(taskID),
		"bid", strconv.Itoa(b.ID),
		"agent", caller.String(),
		"amountUgnot", strconv.FormatInt(amountUgnot, 10),
	)
	return b.ID
}

// AcceptBid is called by the task poster to pick a bid. The task moves to
// in-progress and the winning agent is recorded. Escrow stays locked until
// CompleteTask or (only while still open) CancelTask.
func AcceptBid(cur realm, taskID, bidID int) {
	caller := mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.Poster != caller {
		panic("only the task poster can accept a bid")
	}
	if t.Status != StatusOpen {
		panic("only an open task can accept a bid")
	}
	b := mustGetBid(taskID, bidID)
	t.Status = StatusInProgress
	t.WinningBidID = b.ID
	t.Winner = b.Agent
	t.AcceptedAt = time.Now()
	chain.Emit("BidAccepted",
		"task", strconv.Itoa(taskID),
		"bid", strconv.Itoa(bidID),
		"agent", b.Agent.String(),
		"amountUgnot", strconv.FormatInt(b.Amount, 10),
	)
}

// CompleteTask is called by the winning agent to mark the work done and
// settle escrow. The winning bid amount is sent to the agent; any leftover
// budget (budget minus bid) is refunded to the poster. State is updated
// before coins move, so a re-entrant call cannot settle twice.
// Hash-commit tasks must use RevealAndComplete instead.
func CompleteTask(cur realm, taskID int) {
	caller := mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.CommitHash != "" {
		panic("this task requires a hash reveal: call RevealAndComplete")
	}
	if t.Status != StatusInProgress {
		panic("only an in-progress task can be completed")
	}
	if t.Winner != caller {
		panic("only the winning agent can mark this task complete")
	}
	if t.Settled {
		panic("this task has already been settled")
	}
	settleTask(cur, t, "open")
}

// settleTask applies the completed-and-paid state and moves coins.
// caller checks must already have been performed.
func settleTask(cur realm, t *Task, method string) {
	b := mustGetBid(t.ID, t.WinningBidID)
	pay := b.Amount
	refund := t.BudgetUgnot - pay
	if refund < 0 {
		panic("invariant: bid exceeds escrowed budget")
	}

	// Effects first, then interactions.
	t.Status = StatusCompleted
	t.Settled = true
	t.CompletedAt = time.Now()
	if av := agents.Get(t.Winner.String()); av != nil {
		a := av.(*Agent)
		a.Completed++
		a.EarnedUgnot += pay
	}
	recordPosterPayment(t.Poster, t.Winner, t.BudgetUgnot)
	chain.Emit("TaskCompleted",
		"task", strconv.Itoa(t.ID),
		"agent", t.Winner.String(),
		"paidUgnot", strconv.FormatInt(pay, 10),
		"refundedUgnot", strconv.FormatInt(refund, 10),
		"method", method,
	)
	sendUgnot(cur, t.Winner, pay)
	sendUgnot(cur, t.Poster, refund)
}

// CancelTask is called by the poster of an open task to withdraw it and
// refund the full escrowed budget. In-progress, completed or already
// cancelled tasks cannot be cancelled.
func CancelTask(cur realm, taskID int) {
	caller := mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.Poster != caller {
		panic("only the task poster can cancel this task")
	}
	if t.Status != StatusOpen {
		panic("only an open task can be cancelled")
	}
	if t.Settled {
		panic("this task has already been settled")
	}

	t.Status = StatusCancelled
	t.Settled = true
	chain.Emit("TaskCancelled",
		"task", strconv.Itoa(taskID),
		"poster", caller.String(),
		"refundedUgnot", strconv.FormatInt(t.BudgetUgnot, 10),
	)
	sendUgnot(cur, t.Poster, t.BudgetUgnot)
}

// ---------------------------------------------------------------------------
// Read-only helpers (safe to query with vm/qeval).

// AgentCount returns the number of registered agents.
func AgentCount() int { return agents.Size() }

// TaskCount returns the number of tasks ever posted (including settled).
func TaskCount() int { return tasks.Size() }

// Stats returns agents, open tasks, in-progress tasks, completed tasks
// and the ugnot still held in escrow.
func Stats() (int, int, int, int, int64) {
	open, prog, done := 0, 0, 0
	var escrow int64
	tasks.Iterate("", "", func(_ string, v any) bool {
		t := v.(*Task)
		switch t.Status {
		case StatusOpen:
			open++
			escrow += t.BudgetUgnot
		case StatusInProgress:
			prog++
			escrow += t.BudgetUgnot
		case StatusCompleted:
			done++
		}
		return false
	})
	return agents.Size(), open, prog, done, escrow
}

// AgentSummary returns a one-line text summary, or "" if unknown.
func AgentSummary(owner address) string {
	v := agents.Get(owner.String())
	if v == nil {
		return ""
	}
	a := v.(*Agent)
	return a.Name + " | " + a.Tags + " | " + a.RateKind + " " + fmtUgnot(a.RateUgnot) + " | completed " + strconv.Itoa(a.Completed)
}

// TaskSummary returns a one-line text summary, or "" if unknown.
func TaskSummary(id int) string {
	v := tasks.Get(padID(id))
	if v == nil {
		return ""
	}
	t := v.(*Task)
	return t.Title + " | " + t.Status + " | " + t.Specialty + " | " + fmtUgnot(t.BudgetUgnot)
}

// ---------------------------------------------------------------------------
// internals

func mustUserCall(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only a direct user call is accepted")
	}
	return prev.Address()
}

func mustGetAgent(owner address) *Agent {
	v := agents.Get(owner.String())
	if v == nil {
		panic("no agent is registered at this address")
	}
	return v.(*Agent)
}

func mustGetTask(id int) *Task {
	v := tasks.Get(padID(id))
	if v == nil {
		panic("task " + strconv.Itoa(id) + " not found")
	}
	return v.(*Task)
}

func mustGetBid(taskID, bidID int) *Bid {
	v := bids.Get(bidKey(taskID, bidID))
	if v == nil {
		panic("bid " + strconv.Itoa(bidID) + " not found on task " + strconv.Itoa(taskID))
	}
	return v.(*Bid)
}

func bidKey(taskID, bidID int) string {
	return padID(taskID) + "/" + padID(bidID)
}

func taskBidCount(taskID int) int {
	count := 0
	prefix := padID(taskID) + "/"
	bids.Iterate(prefix, prefix+"~", func(_ string, _ any) bool {
		count++
		return false
	})
	return count
}

func requireExactUgnotSend(budget int64) {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != budget {
		got := "nothing"
		if len(sent) != 0 {
			got = sent.String()
		}
		panic("must send exactly " + strconv.FormatInt(budget, 10) + "ugnot with this call (got " + got + ")")
	}
}

func sendUgnot(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

// padID makes IDs sort numerically as avl keys.
func padID(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 9 {
		s = "0" + s
	}
	return s
}

package agentmarketplace

