func reset() {
	nextTaskID = 1
	nextBidID = 1
	nextRatingID = 1
	agents = avl.NewTree()
	tasks = avl.NewTree()
	bids = avl.NewTree()
	bidByAgent = avl.NewTree()
	ratings = avl.NewTree()
	ratingsByAgent = avl.NewTree()
