	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	register(cur, bob, "Code Agent", "code, review", RateFlat, 1000000)
	settleJob(cur, alice, carol, "Summarize a paper", "Write a one-page summary of the attached paper.", "research", 2000000)
	settleJob(cur, alice, bob, "Review a realm", "Look over an escrow realm for footguns please.", "review", 3000000)
	ps := posterStats.Get(alice.String()).(*PosterStats)
	uassert.Equal(t, 2, ps.SettledJobs)
	uassert.Equal(t, int64(5000000), ps.SettledUgnot)
	uassert.Equal(t, 2, ps.DistinctAgents)
	uassert.True(t, currentReviewerWeight(alice) > weightUnit)
}

func indexOf(s, sub string) int {
	i := strings.Index(s, sub)
	if i < 0 {
		return 1 << 30
	}
	return i
}

package agentmarketplace

import "time"

// Rate kinds for an agent's listed price.
const (
	RateHourly = "hourly"
	RateFlat   = "flat"
)

// Task statuses. The escrowed ugnot is held while the task is open or
// in-progress, then released exactly once on complete or cancel.
const (
	StatusOpen       = "open"
	StatusInProgress = "in-progress"
	StatusCompleted  = "completed"
	StatusCancelled  = "cancelled"
)

// Agent is a registered worker. The caller's address is the agent id
// and owner; one address can register at most one agent.
type Agent struct {
	Owner        address
	Name         string
	Tags         string // canonical, comma-space separated specialties
	RateKind     string
	RateUgnot    int64
	RegisteredAt time.Time
	Completed    int
	EarnedUgnot  int64
}

// Task is a job posted with an ugnot budget held in escrow by the realm.
type Task struct {
	ID          int
	Poster      address
	Title       string
	Description string
	Specialty   string // required specialty tag
	BudgetUgnot int64
	Status      string
	PostedAt    time.Time

	WinningBidID int
	Winner       address
	AcceptedAt   time.Time
	CompletedAt  time.Time
	Settled      bool // true after payout or refund; prevents double settlement

	// Optional hash-commit settlement. Empty CommitHash means the winning
	// agent may call CompleteTask as usual. When set, they must reveal a
	// preimage of this SHA-256 (lowercase hex) before RevealBy.
	CommitHash string
	RevealBy   time.Time
}

// Bid is one agent's offer on an open task.
type Bid struct {
	ID       int
	TaskID   int
	Agent    address
	Amount   int64 // ugnot, must be > 0 and <= the task budget
	Note     string
	PlacedAt time.Time
}

// Rating is one poster's 1-5 review of a settled job.
type Rating struct {
	ID          int
	TaskID      int
	Agent       address
	Poster      address
	Score       int // 1-5
	Comment     string
	BudgetUgnot int64 // snapshot of the task budget, used as weight
	ReviewerWt  int64 // snapshot of reviewer weight (1000 = 1.0)
	RatedAt     time.Time
}

// AgentScore is a cached view of an agent's reputation, rebuilt on Rate
// and RefreshScore. Queries and Render recompute decay live from ratings.
type AgentScore struct {
	Agent       address
	RatedCount  int
	TrustMilli  int64 // 1000-5000, 0 if unrated
	RawMilli    int64
	Provisional bool
	LastRatedAt time.Time
}

// PosterStats tracks a poster's history, used to grow reviewer weight.
type PosterStats struct {
	Owner          address
	SettledJobs    int
	SettledUgnot   int64
	DistinctAgents int
}

package agentmarketplace

import (
	"sort"
	"strconv"
	"strings"
)

// Input limits.
const (
	minNameLen      = 3
	maxNameLen      = 48
	minTitleLen     = 3
	maxTitleLen     = 80
	minDescLen      = 3
	maxDescLen      = 280
	maxNoteLen      = 80
	minTagLen       = 2
	maxTagLen       = 24
	maxTags         = 8
	maxTagsInputLen = 200
	maxRateUgnot    = 1000000000000 // 1,000,000 GNOT
	minBudgetUgnot  = 1
	maxBudgetUgnot  = 1000000000000
	ugnotPerGnot    = 1000000
	minScore        = 1
	maxScore        = 5
	maxCommentLen   = 120
	commitHashLen   = 64
	minRevealSecs   = 60
	maxRevealSecs   = 30 * 24 * 60 * 60
)

// isSafeChar is the character whitelist for every free-text field. It keeps
// user-supplied strings from injecting markdown, HTML, gnoweb tags or
// table pipes into Render output, and keeps them single-line.
func isSafeChar(c rune) bool {
	switch {
	case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		return true
	}
	switch c {
	case ' ', '-', '.', ',', '(', ')', '\'', '/', '+', ':', '@', '#', '%', '&', '=':
		return true
	}
	return false
}

// checkText validates a free-text field and panics with a readable message.
func checkText(field, s string, minLen, maxLen int) {
	if len(s) < minLen || len(s) > maxLen {
		panic(field + " must be " + strconv.Itoa(minLen) + "-" + strconv.Itoa(maxLen) + " characters")
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		panic(field + " must not start or end with a space")
	}
	for _, c := range s {
		if !isSafeChar(c) {
			panic(field + " contains an unsupported character: only letters, digits, spaces and - . , ( ) ' / + : @ # % & = are allowed")
		}
	}
}

func checkRateKind(kind string) {
	switch kind {
	case RateHourly, RateFlat:
		return
	}
	panic("rate kind must be one of: hourly, flat")
}

func checkRate(rate int64) {
	if rate < 1 || rate > maxRateUgnot {
		panic("rate must be between 1 and " + strconv.FormatInt(maxRateUgnot, 10) + " ugnot")
	}
}

func checkBudget(budget int64) {
	if budget < minBudgetUgnot || budget > maxBudgetUgnot {
		panic("budget must be between " + strconv.FormatInt(minBudgetUgnot, 10) + " and " + strconv.FormatInt(maxBudgetUgnot, 10) + " ugnot")
	}
}

// checkSpecialty validates a single required specialty tag.
func checkSpecialty(tag string) string {
	normalized := strings.ToLower(strings.TrimSpace(tag))
	checkTag("specialty", normalized)
	return normalized
}

func checkTag(field, tag string) {
	if len(tag) < minTagLen || len(tag) > maxTagLen {
		panic(field + " must be " + strconv.Itoa(minTagLen) + "-" + strconv.Itoa(maxTagLen) + " characters")
	}
	if strings.Contains(tag, ",") {
		panic(field + " must be a single tag, not a comma-separated list")
	}
	if tag[0] == ' ' || tag[len(tag)-1] == ' ' {
		panic(field + " must not start or end with a space")
	}
	for _, c := range tag {
		if !isSafeChar(c) {
			panic(field + " contains an unsupported character: only letters, digits, spaces and - . , ( ) ' / + : @ # % & = are allowed")
		}
	}
}

// parseTags canonicalizes a comma-separated specialty list: lowercased,
// trimmed, unique, sorted, joined with ", ".
func parseTags(raw string) string {
	checkText("tags", raw, minTagLen, maxTagsInputLen)
	parts := strings.Split(raw, ",")
	var tags []string
	for _, p := range parts {
		tag := strings.ToLower(strings.TrimSpace(p))
		if tag == "" {
			continue
		}
		checkTag("tag", tag)
		if containsTag(tags, tag) {
			continue
		}
		tags = append(tags, tag)
		if len(tags) > maxTags {
			panic("an agent can list at most " + strconv.Itoa(maxTags) + " specialty tags")
		}
	}
	if len(tags) == 0 {
		panic("tags must list at least one specialty")
	}
	sort.Strings(tags)
	return strings.Join(tags, ", ")
}

func containsTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}

func agentHasSpecialty(agentTags, specialty string) bool {
	for _, t := range strings.Split(agentTags, ", ") {
		if t == specialty {
			return true
		}
	}
	return false
}

func checkScore(score int) {
	if score < minScore || score > maxScore {
		panic("score must be an integer from 1 to 5")
	}
}

func checkComment(comment string) {
	if comment == "" {
		return
	}
	checkText("comment", comment, 1, maxCommentLen)
}

func checkCommitHash(h string) string {
	h = strings.ToLower(h)
	if len(h) != commitHashLen {
		panic("commit hash must be a 64-character hex SHA-256 digest")
	}
	for _, c := range h {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			panic("commit hash must be a 64-character hex SHA-256 digest")
		}
	}
	return h
}

func checkRevealDeadline(secs int64) {
	if secs < minRevealSecs || secs > maxRevealSecs {
		panic("reveal deadline must be between 60 seconds and 30 days")
	}
}

package aimledger

import (
	"sort"
	"strconv"
	"time"

	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	daySeconds       int64 = 86400
	cooldownSeconds  int64 = 10
	maxScore               = 10000
	dailyQuestTarget       = 1500
	dailyCreditCap   int64 = 500
	creditsPerPoint  int64 = 1
	ugnotPerCredit   int64 = 1000
	maxClaimCredits  int64 = 1000
)

type Player struct {
	Addr       address
	Credits    int64
	Best       int
	Runs       int
	Streak     int
	LastDay    int64
	LastSubmit int64
	TodayScore int
}

var (
	admin        address
	players      *avl.Tree
	totalPlayers int
	totalRuns    int64
	pool         int64
)

func init() {
	admin = unsafe.OriginCaller()
	players = avl.NewTree()
}

// requireUser validates the crossing realm token and returns the EOA caller.
func requireUser(rlm realm) address {
	if !rlm.IsCurrent() {
		panic("invalid realm token")
	}
	if !rlm.Previous().IsUserCall() {
		panic("EOA calls only")
	}
	return rlm.Previous().Address()
}

func playerFor(a address) *Player {
	key := a.String()
	if !players.Has(key) {
		return nil
	}
	p, _ := players.Get(key).(*Player)
	return p
}

func getOrCreate(a address) *Player {
	p := playerFor(a)
	if p == nil {
		p = &Player{Addr: a}
		players.Set(a.String(), p)
		totalPlayers++
	}
	return p
}

// Join registers the caller. Free, idempotent.
func Join(cur realm) {
	a := requireUser(cur)
	getOrCreate(a)
}

// SubmitScore records a run. One run per cooldown window; credits are capped daily.
func SubmitScore(cur realm, score int) {
	a := requireUser(cur)
	if score < 1 || score > maxScore {
		panic("score out of range")
	}
	p := getOrCreate(a)
	now := time.Now().Unix()
	if now-p.LastSubmit < cooldownSeconds {
		panic("too soon: wait before the next run")
	}

	day := now / daySeconds
	if day != p.LastDay {
		p.TodayScore = 0
		if day == p.LastDay+1 {
			p.Streak++
		} else if day > p.LastDay+1 {
			p.Streak = 1
		}
		p.LastDay = day
	}

	earned := int64(score) * creditsPerPoint
	if p.TodayScore+score > dailyQuestTarget {
		earned = int64(dailyQuestTarget-p.TodayScore) * creditsPerPoint
	}
	if earned < 0 {
		earned = 0
	}
	if earned > dailyCreditCap {
		earned = dailyCreditCap
	}

	p.TodayScore += score
	if score > p.Best {
		p.Best = score
	}
	p.Runs++
	p.LastSubmit = now
	p.Credits += earned
	totalRuns++
	totalCredits += earned

	chain.Emit("Run", "player", a.String(), "score", strconv.Itoa(score), "credits", strconv.FormatInt(earned, 10))
}

// Fund adds ugnot to the prize pool. Payable, EOA only.
func Fund(cur realm) {
	requireUser(cur)
	coins := unsafe.OriginSend()
	if len(coins) != 1 || coins[0].Denom != "ugnot" || coins[0].Amount <= 0 {
		panic("send ugnot to fund the pool")
	}
	pool += coins[0].Amount
	chain.Emit("Fund", "amount", strconv.FormatInt(coins[0].Amount, 10))
}

// Claim redeems credits for ugnot from the pool.
func Claim(cur realm, credits int64) {
	a := requireUser(cur)
	if credits <= 0 || credits > maxClaimCredits || credits%100 != 0 {
		panic("claim must be a multiple of 100, up to 1000 credits")
	}
	p := playerFor(a)
	if p == nil || p.Credits < credits {
		panic("not enough credits")
	}
	amount := credits / 100 * ugnotPerCredit
	if amount > pool {
		panic("prize pool is empty")
	}
	p.Credits -= credits
	pool -= amount
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), a, chain.Coins{{Denom: "ugnot", Amount: amount}})
	chain.Emit("Claim", "player", a.String(), "amount", strconv.FormatInt(amount, 10))
}

// Top returns the ten highest-scoring players, ordered by best score then address.
func Top() []*Player {
	list := []*Player{}
	players.Iterate("", "", func(key string, value any) bool {
		p, ok := value.(*Player)
		if ok {
			list = append(list, p)
		}
		return false
	})
	sort.SliceStable(list, func(i, j int) bool {
		if list[i].Best != list[j].Best {
			return list[i].Best > list[j].Best
		}
		return list[i].Addr.String() < list[j].Addr.String()
	})
	if len(list) > 10 {
		return list[:10]
	}
	return list
}

func Credits(a address) int64 {
	p := playerFor(a)
	if p == nil {
		return 0
	}
	return p.Credits
}

func Pool() int64 { return pool }
func Players() int { return totalPlayers }
func Runs() int64  { return totalRuns }

func Render(path string) string {
	out := "# Aim Ledger\n\n"
	out += "Aim. Quest. Earn. An on-chain scoreboard for a browser aim trainer — every run, streak and payout is settled in a realm.\n\n"
	out += "## How to play\n\n"
	out += "1. Open the companion aim trainer in the project repo and get a score (1-10000).\n"
	out += "2. Submit it below. Runs are rate-limited and credits are capped daily.\n"
	out += "3. Build a streak, climb the board, then redeem credits for testnet GNOT.\n\n"
	out += "100 credits = 0.001 GNOT. Maximum redemption is 1000 credits at a time. Fund the pool with a payable call to Fund.\n\n"

	out += "## Stats\n\n"
	out += "| Players | Runs | Pool (ugnot) |\n|---|---:|---:|\n"
	out += "| " + strconv.Itoa(totalPlayers) + " | " + strconv.FormatInt(totalRuns, 10) + " | " + strconv.FormatInt(pool, 10) + " |\n\n"

	out += "## Your account\n\n"
	out += "<gno-form exec=\"Join\">\n<gno-button label=\"Join for free\" />\n</gno-form>\n\n"
	out += "<gno-form exec=\"SubmitScore\">\n<gno-input name=\"score\" type=\"number\" placeholder=\"Score from the aim trainer\" required=\"true\" />\n</gno-form>\n\n"
	out += "<gno-form exec=\"Claim\">\n<gno-input name=\"credits\" type=\"number\" placeholder=\"Credits to redeem (multiple of 100)\" required=\"true\" />\n</gno-form>\n\n"

	out += "## Leaderboard\n\n"
	out += "| # | Player | Best | Streak | Credits |\n|---:|---|---:|---:|---:|\n"
	for i, p := range Top() {
		out += "| " + strconv.Itoa(i+1) + " | " + sanitize.InlineText(p.Addr.String()) + " | " + strconv.Itoa(p.Best) + " | " + strconv.Itoa(p.Streak) + " | " + strconv.FormatInt(p.Credits, 10) + " |\n"
	}
	return out
}

