// Package arena implements the on-chain economy for Arena Ledger, a
// play-to-earn 3D shooter. Every token value is an integer count of
// millitokens (mtok): 1 token == 1000 mtok, so fractional rewards stay
// exact. All balances live in this realm's internal ledger; no external
// GRC20 package is imported.
package arena

import (
	"strconv"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Token amounts, in millitokens (mtok).
const (
	unitPerToken int64 = 1000 // 1 token = 1000 mtok

	entryFee    int64 = 2000 // 2.0 tokens: cost of one match
	baseBounty  int64 = 1200 // 1.2 tokens: escrowed kill bounty
	poolShare   int64 = 800  // 0.8 tokens: community-pool contribution
	boostBounty int64 = 2400 // 2.4 tokens: doubled boosted kill bounty

	startingBalance int64 = entryFee // onboarding grant: one free first entry

	xpPerKill int64 = 40 // base XP for a kill
	xpPerWin  int64 = 60 // base XP for a win

	level1XP int64 = 100 // XP needed for level 1
	level2XP int64 = 300 // XP needed for level 2
	level3XP int64 = 700 // XP needed for level 3

	leaderboardSize = 10
)

// boostedHours are the three UTC hours -- 06:00, 12:00 and 18:00 -- in
// which the kill bounty doubles to 2.4 tokens. The extra 1.2 tokens come
// out of the community pool, not out of the victim's entry allocation.
var boostedHours = []int{6, 12, 18}

// multiplierPct is the XP multiplier applied to kills and wins using the
// player's level BEFORE the award: level 0 = 100% (no bonus),
// level 1 = 110%, level 2 = 120%, level 3 = 130%.
var multiplierPct = []int64{100, 110, 120, 130}

// Player is a single account in the realm's internal token ledger.
type Player struct {
	Addr    address
	Balance int64 // spendable tokens (mtok)
	Pending int64 // earned bounty not yet claimed (mtok)
	Bounty  int64 // bounty escrowed on this player from entries (mtok)
	XP      int64 // cumulative XP
	Kills   int
	Deaths  int
	Wins    int
	Entries int
}

var (
	players          *avl.Tree
	pool             int64 // community pool (mtok)
	totalPlayers     int
	totalEntries     int64
	totalKills       int64
	totalBoostKills  int64
	totalDistributed int64
)

func init() {
	players = avl.NewTree()
}

// callerOf validates a realm token and returns the EOA that crossed into
// this realm. Any helper receiving a realm token must check IsCurrent;
// the exported crossing functions additionally check Previous().IsUserCall().
func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("invalid realm token")
	}
	return cur.Previous().Address()
}

func playerFor(a address) *Player {
	key := a.String()
	if !players.Has(key) {
		return nil
	}
	p, _ := players.Get(key).(*Player)
	return p
}

func getOrCreate(a address) *Player {
	p := playerFor(a)
	if p == nil {
		// A small onboarding grant lets a new player enter their first match.
		p = &Player{Addr: a, Balance: startingBalance}
		players.Set(a.String(), p)
		totalPlayers++
	}
	return p
}

// formatTokens renders millitokens as a decimal token string, trimming
// trailing zeros: 1200 -> "1.2", 2400 -> "2.4", 800 -> "0.8", 2000 -> "2".
// The game client prefixes this with "+" to display "+1.2" in the HUD.
func formatTokens(mtok int64) string {
	sign := ""
	if mtok < 0 {
		sign = "-"
		mtok = -mtok
	}
	whole := mtok / unitPerToken
	frac := mtok % unitPerToken
	if frac == 0 {
		return sign + strconv.FormatInt(whole, 10)
	}
	fs := strconv.FormatInt(frac, 10)
	for len(fs) < 3 {
		fs = "0" + fs
	}
	for len(fs) > 0 && fs[len(fs)-1] == '0' {
		fs = fs[:len(fs)-1]
	}
	return sign + strconv.FormatInt(whole, 10) + "." + fs
}

// entrySplit returns the bounty and community-pool parts of an entry fee.
// Their sum is exactly entryFee (1.2 + 0.8 = 2.0 tokens).
func entrySplit() (bounty, community int64) {
	return baseBounty, poolShare
}

// isBoosted reports whether t is inside one of the three boosted UTC hours.
func isBoosted(t time.Time) bool {
	h := t.UTC().Hour()
	for _, bh := range boostedHours {
		if h == bh {
			return true
		}
	}
	return false
}

// bountyForKill returns the payout and the portion funded by the community
// pool for a kill at time t. A normal kill pays 1.2 tokens entirely from
// the victim's bounty allocation. A boosted kill pays 2.4 tokens: 1.2 from
// the victim and 1.2 from the community pool.
func bountyForKill(t time.Time) (payout, fromPool int64) {
	if isBoosted(t) {
		return boostBounty, boostBounty - baseBounty
	}
	return baseBounty, 0
}

// levelForXP maps cumulative XP to a level. Players start unranked (0) and
// reach level 1 at 100 XP, level 2 at 300 XP and level 3 at 700 XP.
func levelForXP(xp int64) int {
	switch {
	case xp >= level3XP:
		return 3
	case xp >= level2XP:
		return 2
	case xp >= level1XP:
		return 1
	default:
		return 0
	}
}

// awardXP grants base XP modified by the player's current level and
// returns the amount actually awarded.
func awardXP(p *Player, base int64) int64 {
	lvl := levelForXP(p.XP)
	gained := base * multiplierPct[lvl] / 100
	p.XP += gained
	return gained
}

// Enter charges the caller 2 tokens to join a match. Of that, 1.2 tokens
// become a bounty on the entrant and 0.8 tokens go to the community pool.
func Enter(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Enter: EOA calls only")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	if p.Balance < entryFee {
		panic("Enter: not enough balance (need 2 tokens)")
	}
	bounty, community := entrySplit()
	p.Balance -= entryFee
	p.Bounty += bounty
	pool += community
	p.Entries++
	totalEntries++
	chain.Emit("Enter", "player", a.String(), "cost", formatTokens(entryFee),
		"bounty", formatTokens(bounty), "pool", formatTokens(community))
}

// ReportKill credits the caller for killing victim. The caller is the
// killer; the victim must already have an entry bounty escrowed. During a
// boosted hour the payout is 2.4 tokens, with the extra 1.2 taken from the
// community pool. The Kill event carries the numeric "amount" (e.g. 1.2)
// so the client can display "+1.2".
func ReportKill(cur realm, victim string) {
	if !cur.Previous().IsUserCall() {
		panic("ReportKill: EOA calls only")
	}
	killerAddr := callerOf(cur)
	victimAddr := address(victim)
	if victimAddr == killerAddr {
		panic("ReportKill: cannot score a kill on yourself")
	}
	victimPlayer := playerFor(victimAddr)
	if victimPlayer == nil {
		panic("ReportKill: unknown victim")
	}
	killer := getOrCreate(killerAddr)

	payout, fromPool := bountyForKill(time.Now())
	if victimPlayer.Bounty < baseBounty {
		panic("ReportKill: victim has no bounty allocation")
	}
	if fromPool > pool {
		panic("ReportKill: community pool cannot fund the boost")
	}

	// Settle: consume the victim's base bounty, draw any boost from the pool.
	victimPlayer.Bounty -= baseBounty
	pool -= fromPool
	killer.Pending += payout
	killer.Kills++
	victimPlayer.Deaths++
	totalKills++
	totalDistributed += payout
	boosted := fromPool > 0
	if boosted {
		totalBoostKills++
	}
	gained := awardXP(killer, xpPerKill)

	chain.Emit("Kill", "killer", killerAddr.String(), "victim", victim,
		"amount", formatTokens(payout), "boosted", strconv.FormatBool(boosted),
		"xp", strconv.FormatInt(gained, 10))
	if boosted {
		chain.Emit("Boost", "killer", killerAddr.String(),
			"amount", formatTokens(payout), "hour", strconv.Itoa(time.Now().UTC().Hour()))
	}
}

// ReportWin records a match win for the caller. Wins grant XP (with the
// caller's level multiplier) but do not move tokens.
func ReportWin(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("ReportWin: EOA calls only")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	p.Wins++
	gained := awardXP(p, xpPerWin)
	chain.Emit("Win", "player", a.String(), "xp", strconv.FormatInt(gained, 10))
}

// Claim moves the caller's pending kill rewards into their spendable
// balance so they can pay for another entry.
func Claim(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Claim: EOA calls only")
	}
	a := callerOf(cur)
	p := playerFor(a)
	if p == nil {
		panic("Claim: no player record")
	}
	amount := p.Pending
	if amount <= 0 {
		panic("Claim: nothing to claim")
	}
	p.Pending = 0
	p.Balance += amount
	chain.Emit("Claim", "player", a.String(), "amount", formatTokens(amount),
		"amount_mtok", strconv.FormatInt(amount, 10))
}

// better ranks a above b by XP, then kills, then wins, then address.
// It is the strict ordering used to build the leaderboard.
func better(a, b *Player) bool {
	if a.XP != b.XP {
		return a.XP > b.XP
	}
	if a.Kills != b.Kills {
		return a.Kills > b.Kills
	}
	if a.Wins != b.Wins {
		return a.Wins > b.Wins
	}
	return a.Addr.String() < b.Addr.String()
}

// Top returns the ten highest-ranked players according to better.
func Top() []*Player {
	list := []*Player{}
	players.Iterate("", "", func(key string, value any) bool {
		if p, ok := value.(*Player); ok {
			list = append(list, p)
		}
		return false
	})
	for i := 1; i < len(list); i++ {
		j := i
		for j > 0 && better(list[j], list[j-1]) {
			list[j], list[j-1] = list[j-1], list[j]
			j--
		}
	}
	if len(list) > leaderboardSize {
		return list[:leaderboardSize]
	}
	return list
}

// Pool returns the community pool balance in millitokens.
func Pool() int64 { return pool }

// Players returns the number of registered players.
func Players() int { return totalPlayers }

// TotalEntries returns the number of paid entries.
func TotalEntries() int64 { return totalEntries }

// TotalKills returns the number of reported kills.
func TotalKills() int64 { return totalKills }

// TotalBoostKills returns the number of kills settled in a boosted window.
func TotalBoostKills() int64 { return totalBoostKills }

// TotalDistributed returns the total tokens paid out as bounties (mtok).
func TotalDistributed() int64 { return totalDistributed }

// Balance returns a player's spendable internal balance in millitokens.
func Balance(a address) int64 {
	if p := playerFor(a); p != nil {
		return p.Balance
	}
	return 0
}

// Render draws the realm documentation, gno-forms for every public
// crossing function, and the current leaderboard.
func Render(path string) string {
	out := "# Arena Ledger\n\n"
	out += "Pay 2 tokens to drop into the arena, take down opponents, and earn their bounty. "
	out += "Every entry, kill and payout is settled in this realm's internal token ledger.\n\n"

	out += "## Economy\n\n"
	out += "| Event | Tokens | Detail |\n|---|---:|---|\n"
	out += "| Entry | " + formatTokens(entryFee) + " | 2 tokens per match |\n"
	out += "| Kill bounty | " + formatTokens(baseBounty) + " | from the victim's entry allocation; shown as +" + formatTokens(baseBounty) + " |\n"
	out += "| Community pool | " + formatTokens(poolShare) + " | from each entry; funds boost windows |\n"
	out += "| Boosted kill | " + formatTokens(boostBounty) + " | 1.2 from the victim + 1.2 from the community pool |\n\n"
	out += "Boosted windows are the UTC hours 06:00, 12:00 and 18:00 (each lasts one hour). "

	out += "## Levels\n\n"
	out += "Level 1 at 100 XP, level 2 at 300 XP, level 3 at 700 XP. Kills grant "
	out += strconv.FormatInt(xpPerKill, 10) + " base XP and wins grant "
	out += strconv.FormatInt(xpPerWin, 10) + " base XP; the current level multiplies both by "
	out += "100% / 110% / 120% / 130% (levels 0 / 1 / 2 / 3).\n\n"

	out += "## Stats\n\n"
	out += "| Players | Entries | Kills | Boosted kills | Pool | Distributed |\n"
	out += "|---:|---:|---:|---:|---:|---:|\n"
	out += "| " + strconv.Itoa(totalPlayers) + " | " + strconv.FormatInt(totalEntries, 10) +
		" | " + strconv.FormatInt(totalKills, 10) + " | " + strconv.FormatInt(totalBoostKills, 10) +
		" | " + formatTokens(pool) + " | " + formatTokens(totalDistributed) + " |\n\n"

	out += "## Actions\n\n"
	out += "<gno-form exec=\"Enter\">\n<gno-button label=\"Enter match (2 tokens)\" />\n</gno-form>\n\n"
	out += "<gno-form exec=\"ReportKill\">\n<gno-input name=\"victim\" type=\"text\" placeholder=\"Victim g1... address\" required=\"true\" />\n<gno-button label=\"Report kill\" />\n</gno-form>\n\n"
	out += "<gno-form exec=\"ReportWin\">\n<gno-button label=\"Report win\" />\n</gno-form>\n\n"
	out += "<gno-form exec=\"Claim\">\n<gno-button label=\"Claim pending bounty\" />\n</gno-form>\n\n"

	out += "## Leaderboard\n\n"
	out += "| # | Player | Level | XP | Kills | Wins | Balance |\n"
	out += "|---:|---|---:|---:|---:|---:|---:|\n"
	for i, p := range Top() {
		// Addresses originate from user calls, so sanitize before rendering.
		who := sanitize.InlineText(p.Addr.String())
		out += "| " + strconv.Itoa(i+1) + " | " + who + " | " + strconv.Itoa(levelForXP(p.XP)) +
			" | " + strconv.FormatInt(p.XP, 10) + " | " + strconv.Itoa(p.Kills) +
			" | " + strconv.Itoa(p.Wins) + " | " + formatTokens(p.Balance) + " |\n"
	}
	return out
}

package heirloom

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/nt/grc20reg/v0"
)

type assetInfo struct {
	label    string
	symbol   string
	unit     string
	decimals int
}

type assetInfos map[string]assetInfo

func describe(asset string) assetInfo {
	if asset == gnot {
		return assetInfo{label: "GNOT", symbol: "GNOT", unit: gnot, decimals: 6}
	}
	tok := grc20reg.MustGet(asset)
	return assetInfo{
		label:    sanitize.TableCell(tok.GetName()) + " (`" + asset + "`)",
		symbol:   sanitize.TableCell(tok.GetSymbol()),
		unit:     "units",
		decimals: tok.GetDecimals(),
	}
}

func describeAll(assets []string) assetInfos {
	infos := assetInfos{}
	for _, asset := range assets {
		infos[asset] = describe(asset)
	}
	return infos
}

func (a assetInfo) unitNote() string {
	if a.decimals == 0 {
		return ""
	}
	return "1 " + a.symbol + " = 1" + strings.Repeat("0", a.decimals) + " " + a.unit
}

func (a assetInfo) amount(units int64) string {
	s := strconv.FormatInt(units, 10)
	if a.decimals > 0 {
		if len(s) <= a.decimals {
			s = strings.Repeat("0", a.decimals-len(s)+1) + s
		}
		whole, frac := s[:len(s)-a.decimals], strings.TrimRight(s[len(s)-a.decimals:], "0")
		if frac != "" {
			whole += "." + frac
		}
		s = whole
	}
	return strings.TrimSpace(s + " " + a.symbol)
}

package heirloom

import (
	"chain"
	"chain/banker"

	"gno.land/r/nt/grc20reg/v0"
)

const gnot = "ugnot"

func credit(w *Will, asset string, amount int64) {
	w.add(asset, amount)
	if asset == gnot {
		state.totalGNOT += amount
	}
}

func payOut(cur realm, w *Will, asset string, to address, amount int64) {
	w.take(asset, amount)
	if asset == gnot {
		state.totalGNOT -= amount
	}
	send(cur, asset, to, amount)
}

func pullToken(cur realm, w *Will, token string, amount int64) {
	grc20reg.TransferFrom(0, cur, token, w.Owner, cur.Address(), amount)
	credit(w, token, amount)
}

func send(cur realm, asset string, to address, amount int64) {
	if asset != gnot {
		grc20reg.Transfer(0, cur, asset, to, amount)
		return
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.Coins{{gnot, amount}})
}

package heirloom

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
)

func enter(cur realm) address {
	caller := callerOf(cur)
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this function does not accept coins")
	}
	return caller
}

func enterWithGNOT(cur realm) (address, int64) {
	caller := callerOf(cur)
	if !cur.Previous().IsUserCall() {
		panic("coins must be sent with a direct call (gnokey maketx call or a wallet)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != gnot || sent[0].Amount <= 0 {
		panic("attach the GNOT to deposit")
	}
	return caller, sent[0].Amount
}

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	return cur.Previous().Address()
}

func touchOwnWill(caller address, id int) *Will {
	w := mustGetWill(id)
	if w.Owner != caller {
		panic("only the owner can change will " + strconv.Itoa(id))
	}
	if w.isReleased() {
		panic("will " + strconv.Itoa(id) + " is already released")
	}
	mustUseMasterKey()
	w.touch()
	return w
}

func enterAsOutsider(cur realm, id int) *Will {
	enter(cur)
	signer := unsafe.OriginCaller()
	w := mustGetWill(id)
	if signer == w.Owner && !w.isReleased() {
		panic("you own this will: call Ping to show a sign of life")
	}
	markAlive(signer)
	return w
}

func mustUseMasterKey() {
	if signedWithSessionKey() {
		panic("sign with your master key: a session key cannot create, change or ping a will")
	}
}

func markAlive(addr address) {
	if signedWithSessionKey() {
		return
	}
	if w := getActiveWill(addr); w != nil {
		w.touch()
	}
}

func signedWithSessionKey() bool {
	_, _, _, isSession := runtime.GetSessionInfo()
	return isSession
}

func mustGetWill(id int) *Will {
	w := getWill(id)
	if w == nil {
		panic("will not found")
	}
	return w
}

package heirloom

import (
	"time"

	"gno.land/p/nt/ufmt/v0"
)

func formatTime(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04 UTC")
}

func formatTimeFrom(t time.Time) string {
	if m := t.Truncate(time.Minute); m.Before(t) {
		t = m.Add(time.Minute)
	}
	return formatTime(t)
}

func formatDuration(d time.Duration) string {
	days, hours, minutes := int(d/day), int(d%day/time.Hour), int(d%time.Hour/time.Minute)
	switch {
	case days > 0 && hours > 0:
		return ufmt.Sprintf("%dd %dh", days, hours)
	case days > 0:
		return ufmt.Sprintf("%dd", days)
	case hours > 0 && minutes > 0:
		return ufmt.Sprintf("%dh %dm", hours, minutes)
	case hours > 0:
		return ufmt.Sprintf("%dh", hours)
	case minutes > 0:
		return ufmt.Sprintf("%dm", minutes)
	}
	return "<1m"
}

func shortAddr(addr address) string {
	s := addr.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package heirloom

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"time"
)

// CreateWill makes your will; you can have one unreleased will at a time.
// heirs: address:percent pairs adding up to 100, at most 10, e.g.
// "g1abc...:70, g1def...:30"; the first heir gets any rounding remainder.
// silence: days without a sign of life before release, 1 to 3650, e.g. "180".
// successor: gets your admin rights in realms that check Holder, or empty.
// Needs your master key.
func CreateWill(cur realm, heirs, silence string, successor address) int {
	owner := enter(cur)
	mustUseMasterKey()
	if getActiveWill(owner) != nil {
		panic("you already have an unreleased will")
	}
	w := newWill(owner, parseHeirs(heirs, owner), parseSilence(silence))
	setSuccessor(w, parseSuccessor(successor, owner))
	emit("WillCreated", w)
	return w.ID
}

// SetHeirs replaces the heirs of your will id, in the CreateWill format.
func SetHeirs(cur realm, id int, heirs string) {
	w := touchOwnWill(enter(cur), id)
	indexHeirs(w, parseHeirs(heirs, w.Owner))
	emit("HeirsChanged", w)
}

// SetSuccessor sets the successor of your will id, the address that inherits
// your admin rights in realms that check Holder when the will is released. Use
// any address but yours, or leave it empty for nobody. Refused once a released
// will of yours has handed your admin rights over.
func SetSuccessor(cur realm, id int, successor address) {
	w := touchOwnWill(enter(cur), id)
	setSuccessor(w, parseSuccessor(successor, w.Owner))
	emit("SuccessorChanged", w, "successor", w.Successor.String())
}

// SetSilence changes the silence period of your will id, in the CreateWill
// format.
func SetSilence(cur realm, id int, silence string) {
	w := touchOwnWill(enter(cur), id)
	w.Silence = parseSilence(silence)
	emit("SilenceChanged", w)
}

// Ping is a sign of life for your will id: it restarts the silence period.
// Needs your master key.
func Ping(cur realm, id int) {
	touchOwnWill(enter(cur), id)
}

// Touch is a sign of life for the account that signed the transaction. Any
// realm can call it. Transactions signed with a session key do not count.
func Touch(cur realm) {
	enter(cur)
	markAlive(unsafe.OriginCaller())
}

// Deposit adds the GNOT sent with this call to your will id. Send it directly
// from a wallet or gnokey maketx call, not through another realm.
func Deposit(cur realm, id int) {
	caller, amount := enterWithGNOT(cur)
	w := touchOwnWill(caller, id)
	credit(w, gnot, amount)
	emit("Deposited", w, amountAttrs(gnot, amount)...)
}

// DepositToken moves amount of a GRC20 token, in its smallest unit, into your
// will id. token is its grc20reg key, e.g. "gno.land/r/gnoland/wugnot.wugnot".
// First approve this realm's address as a spender in the token's realm. A will
// holds at most 10 different assets, GNOT included.
func DepositToken(cur realm, id int, token string, amount int64) {
	w := touchOwnWill(enter(cur), id)
	mustBePositive(amount)
	pullToken(cur, w, token, amount)
	emit("Deposited", w, amountAttrs(token, amount)...)
}

// Withdraw sends amount of an asset from your will id back to you. asset is
// "ugnot" or a token key; amount is in its smallest unit (1 GNOT = 1000000
// ugnot).
func Withdraw(cur realm, id int, asset string, amount int64) {
	w := touchOwnWill(enter(cur), id)
	mustBePositive(amount)
	payOut(cur, w, asset, w.Owner, amount)
	emit("Withdrawn", w, amountAttrs(asset, amount)...)
}

// Revoke returns everything in your will id to you and deletes the will.
func Revoke(cur realm, id int) {
	w := touchOwnWill(enter(cur), id)
	for _, asset := range w.assets() {
		payOut(cur, w, asset, w.Owner, w.balance(asset))
	}
	removeWill(w)
	emit("WillRevoked", w)
}

// Release makes will id claimable once its owner has been silent for the
// whole silence period. Anyone but the owner can call it. Releasing also hands
// the owner's admin rights to the successor for good, unless an earlier
// released will has done so or the successor's admin rights already pass to
// the owner.
func Release(cur realm, id int) {
	w := enterAsOutsider(cur, id)
	if w.isReleased() {
		panic("the will is already released")
	}
	mustRelease(w)
}

// Claim sends heir's share of one asset ("ugnot" or a token key) from will id
// to heir, releasing the will first if it is due. Anyone can call it, except
// the owner before the will is released. Claim each asset separately.
func Claim(cur realm, id int, heir address, asset string) {
	w := enterAsOutsider(cur, id)
	h := w.heir(normalize(heir.String()))
	if h == nil {
		panic(heir.String() + " is not an heir of this will")
	}
	if !w.isReleased() {
		mustRelease(w)
	}
	if !w.snapshot.Has(asset) {
		panic("the will held no " + asset + " when it was released")
	}
	if h.hasClaimed(asset) {
		panic(h.Addr.String() + " has already been paid their share of " + asset)
	}

	share := w.shareOf(h, asset)
	if share == 0 {
		panic(h.Addr.String() + "'s share of " + asset + " rounds down to 0")
	}
	h.claimed.Set(asset, true)
	payOut(cur, w, asset, h.Addr, share)
	emit("Claimed", w, append([]string{"heir", h.Addr.String()}, amountAttrs(asset, share)...)...)
}

// Holder returns who holds the admin rights of addr: addr itself until a
// released will of addr hands them to a successor, then that successor's
// holder.
func Holder(addr address) address {
	return holderOf(normalize(addr.String()))
}

// ActiveWill returns the id of the unreleased will of owner, the one they can
// still change. Its status is "active" or "due".
func ActiveWill(owner address) (id int, ok bool) {
	if w := getActiveWill(normalize(owner.String())); w != nil {
		return w.ID, true
	}
	return 0, false
}

// WillInfo returns the owner and status ("active", "due" or "released") of
// will id. releaseAt is when it can be released, or when it was. ok is false
// if the will does not exist or was revoked.
func WillInfo(id int) (owner address, status string, releaseAt time.Time, ok bool) {
	w := getWill(id)
	if w == nil {
		return "", "", time.Time{}, false
	}
	releaseAt = w.releaseAt()
	if w.isReleased() {
		releaseAt = w.ReleasedAt
	}
	return w.Owner, string(w.status()), releaseAt, true
}

func mustRelease(w *Will) {
	if !w.isDue() {
		panic("the owner was last seen on " + formatTime(w.LastSeen) + "; the will can be released from " + formatTimeFrom(w.releaseAt()))
	}
	w.release()
	deactivate(w)
	recordRelease(w)
	if recordHandover(w) {
		emit("WillReleased", w, "successor", w.Successor.String())
		return
	}
	emit("WillReleased", w)
}

func mustBePositive(amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
}

func amountAttrs(asset string, amount int64) []string {
	return []string{"asset", asset, "amount", strconv.FormatInt(amount, 10)}
}

func emit(event string, w *Will, attrs ...string) {
	chain.Emit(event, append([]string{"id", strconv.Itoa(w.ID), "owner", w.Owner.String()}, attrs...)...)
}

