package heirloom

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

func renderUser(addr address, page int) string {
	made, madeMore := willsMadeBy(addr, page)
	named, namedMore := willsNaming(addr, page)
	succeeding, succeedingMore := willsPassingRightsTo(addr, page)
	if page > 1 && len(made) == 0 && len(named) == 0 && len(succeeding) == 0 {
		return notFound("Page not found")
	}

	var b strings.Builder
	b.WriteString("# " + shortAddr(addr) + "\n\n" + backLink() + "\n\n`" + addr.String() + "`\n\n")
	if holder := holderOf(addr); holder != addr {
		b.WriteString("Admin rights of this address now belong to " + userLink(holder) + ".\n\n")
	}
	b.WriteString(section("Wills made", made, page, func(w *Will) string {
		return ufmt.Sprintf("- %s: %s\n", willLink(w.ID), string(w.status()))
	}))
	b.WriteString(section("Named as heir", named, page, func(w *Will) string {
		return ufmt.Sprintf("- %s of %s: %d%%, %s\n", willLink(w.ID), userLink(w.Owner), w.heir(addr).Percent, string(w.status()))
	}))
	b.WriteString(section("Named as successor", succeeding, page, func(w *Will) string {
		return ufmt.Sprintf("- %s of %s: %s\n", willLink(w.ID), userLink(w.Owner), string(w.status()))
	}))
	if madeMore || namedMore || succeedingMore {
		b.WriteString(userPageLink("More", addr, page+1) + "\n")
	}
	return b.String()
}

func section(title string, ws []*Will, page int, line func(*Will) string) string {
	if len(ws) == 0 {
		if page == 1 {
			return "## " + title + "\n\nNone.\n\n"
		}
		return ""
	}
	var b strings.Builder
	b.WriteString("## " + title + "\n\n")
	for _, w := range ws {
		b.WriteString(line(w))
	}
	return b.String() + "\n"
}

package heirloom

import (
	"strconv"
	"strings"

	"gno.land/p/jeronimoalbi/mdform/v0"
	"gno.land/p/nt/ufmt/v0"
)

func renderWill(w *Will) string {
	held, snapshot := w.assets(), w.snapshotAssets()
	listed := held
	if w.isReleased() {
		listed = snapshot
	}
	infos := describeAll(listed)

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Will %d of %s\n\n", w.ID, shortAddr(w.Owner)))
	b.WriteString(backLink() + " · " + userLink(w.Owner) + "\n\n")
	b.WriteString(countdownRing(w) + "\n\n")
	b.WriteString(statusTable(w))
	b.WriteString(assetsSection(w, held, infos))
	b.WriteString(heirsSection(w))
	b.WriteString(adminSection(w))
	if w.isReleased() {
		b.WriteString(claimSection(w, snapshot, infos))
	} else {
		b.WriteString(actionsSection(w, held, infos))
	}
	return b.String()
}

func statusTable(w *Will) string {
	label, whenLabel, when := string(w.status()), "Releasable from", formatTimeFrom(w.releaseAt())
	switch w.status() {
	case statusReleased:
		whenLabel, when = "Released on", formatTime(w.ReleasedAt)
	case statusDue:
		label += ": anyone but the owner can release it"
	}
	return "| Status | Last sign of life | Silence period | " + whenLabel + " |\n| :--- | :--- | :--- | :--- |\n" +
		ufmt.Sprintf("| %s | %s | %s | %s |\n\n", label, formatTime(w.LastSeen), formatDuration(w.Silence), when)
}

func assetsSection(w *Will, held []string, infos assetInfos) string {
	if len(held) == 0 {
		return "## Assets\n\nNothing held.\n\n"
	}
	var b strings.Builder
	b.WriteString("## Assets\n\n| Asset | Held |\n| :--- | ---: |\n")
	for _, asset := range held {
		b.WriteString("| " + infos[asset].label + " | " + infos[asset].amount(w.balance(asset)) + " |\n")
	}
	return b.String() + "\n"
}

func heirsSection(w *Will) string {
	var b strings.Builder
	b.WriteString("## Heirs\n\n| Heir | Share |\n| :--- | ---: |\n")
	for _, heir := range w.Heirs {
		b.WriteString(ufmt.Sprintf("| %s | %d%% |\n", userLink(heir.Addr), heir.Percent))
	}
	return b.String() + "\n"
}

func adminSection(w *Will) string {
	outcome, h := adminOutcomeOf(w)
	released := w.isReleased()
	text := ""
	switch {
	case outcome == adminHandedOverHere:
		text = "When this will was released, it handed them to " + userLink(h.To) + "." + nowHeldBy(h.To)
	case outcome == adminHandedOverByAnother:
		text = "Releasing " + willLink(h.WillID) + " handed them to " + userLink(h.To) + "." + nowHeldBy(h.To)
	case outcome == adminNoSuccessor && released:
		text = "No successor was named, so the owner kept them."
	case outcome == adminNoSuccessor:
		text = "No successor: the owner keeps them after release."
	case outcome == adminStaysWithOwner && released:
		text = "The owner kept them: the rights of the successor, " + userLink(w.Successor) + ", already passed to the owner."
	case outcome == adminStaysWithOwner:
		text = "The owner will keep them: the rights of the successor, " + userLink(w.Successor) + ", already pass to the owner."
	default:
		text = "On release, they pass to the successor, " + userLink(w.Successor) + "."
		if holder := holderOf(w.Successor); holder != w.Successor {
			text += " The successor's own rights already passed to " + userLink(holder) + ", so they will end up there."
		}
	}
	return "## Admin rights\n\n" + text + "\n\n"
}

func nowHeldBy(successor address) string {
	if holder := holderOf(successor); holder != successor {
		return " They are now held by " + userLink(holder) + "."
	}
	return ""
}

func claimSection(w *Will, snapshot []string, infos assetInfos) string {
	if len(snapshot) == 0 {
		return "## Claims\n\nNothing to claim.\n\n"
	}
	id := strconv.Itoa(w.ID)
	var b strings.Builder
	b.WriteString("## Claims\n\nAnyone can pay out a share; it always goes to the heir.\n\n")
	b.WriteString("| Heir | Asset | Share | Status |\n| :--- | :--- | ---: | :--- |\n")
	for _, asset := range snapshot {
		for _, h := range w.Heirs {
			share := w.shareOf(h, asset)
			status := "paid"
			switch {
			case share == 0:
				status = "nothing to pay"
			case !h.hasClaimed(asset):
				status = link("pay out", txURL("Claim", 0, "id", id, "heir", h.Addr.String(), "asset", asset))
			}
			b.WriteString("| " + userLink(h.Addr) + " | " + infos[asset].label + " | " + infos[asset].amount(share) + " | " + status + " |\n")
		}
	}
	return b.String() + "\n"
}

func actionsSection(w *Will, held []string, infos assetInfos) string {
	id := strconv.Itoa(w.ID)
	var b strings.Builder
	b.WriteString("## Actions\n\n")
	if w.isDue() {
		b.WriteString("Anyone but the owner: " + link("release the will", txURL("Release", 0, "id", id)) + ". Then anyone can pay out each heir's share.\n\n")
	}
	b.WriteString("### Owner only\n\n")
	b.WriteString(link("I am alive", txURL("Ping", 0, "id", id)) + " · Deposit " +
		link("1 GNOT", txURL("Deposit", 1_000_000, "id", id)) + " · " + link("10 GNOT", txURL("Deposit", 10_000_000, "id", id)) + " · " +
		link("Revoke the will", txURL("Revoke", 0, "id", id)) + "\n\n")

	b.WriteString("Deposit a GRC20 token, in its smallest unit. First approve `" + selfAddr.String() + "` as a spender in the token's realm.\n\n")
	b.WriteString(ownerForm("DepositToken", id).
		Input("token", "placeholder", "gno.land/r/gnoland/wugnot.wugnot", "description", "Token key").
		Input("amount", "type", mdform.InputTypeNumber, "description", "Amount").
		String() + "\n\n")

	if len(held) > 0 {
		var units []string
		form := ownerForm("Withdraw", id)
		for i, asset := range held {
			if note := infos[asset].unitNote(); note != "" {
				units = append(units, note)
			}
			if i == 0 {
				form.Select("asset", asset, "description", "Asset")
			} else {
				form.Select("asset", asset)
			}
		}
		note := ""
		if len(units) > 0 {
			note = " (" + strings.Join(units, ", ") + ")"
		}
		b.WriteString("Withdraw, in the asset's smallest unit" + note + ":\n\n")
		b.WriteString(form.Input("amount", "type", mdform.InputTypeNumber, "description", "Amount").String() + "\n\n")
	}

	b.WriteString("Change heirs:\n\n")
	b.WriteString(ownerForm("SetHeirs", id).Input("heirs", "value", heirList(w), "description", "Heirs").String() + "\n\n")

	if _, done := handoverOf(w.Owner); !done {
		b.WriteString("Successor, who inherits your admin rights; leave empty for nobody:\n\n")
		b.WriteString(ownerForm("SetSuccessor", id).Input("successor", "value", w.Successor.String(), "placeholder", "g1...", "description", "Successor").String() + "\n\n")
	}

	b.WriteString("Change the silence period, in days:\n\n")
	b.WriteString(ownerForm("SetSilence", id).Input("silence", "type", mdform.InputTypeNumber, "value", strconv.Itoa(int(w.Silence/day)), "description", "Silence, in days").String() + "\n")
	return b.String()
}

func ownerForm(fn, id string) *mdform.Form {
	return mdform.New("exec", fn).Input("id", "value", id, "readonly", "true", "description", "Will")
}

func heirList(w *Will) string {
	items := make([]string, len(w.Heirs))
	for i, h := range w.Heirs {
		items[i] = h.Addr.String() + ":" + strconv.Itoa(h.Percent)
	}
	return strings.Join(items, ", ")
}

package heirloom

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

func parseHeirs(list string, owner address) []*Heir {
	var heirs []*Heir
	total := 0
	for _, item := range strings.Split(list, ",") {
		addr, pct, ok := strings.Cut(strings.TrimSpace(item), ":")
		percent, err := strconv.Atoi(strings.TrimSpace(pct))
		heir := normalize(addr)
		switch {
		case !ok || err != nil:
			panic("heirs must look like g1...:70, g1...:30")
		case !heir.IsValid():
			panic("invalid heir address: " + addr)
		case heir == owner:
			panic("you cannot be your own heir")
		case heir == selfAddr:
			panic("this realm cannot be an heir")
		case percent < 1 || percent > 100:
			panic("each heir's percent must be between 1 and 100")
		}
		if len(heirs) == MaxHeirs {
			panic(ufmt.Sprintf("a will can have at most %d heirs", MaxHeirs))
		}
		for _, h := range heirs {
			if h.Addr == heir {
				panic("heir listed twice: " + heir.String())
			}
		}
		heirs = append(heirs, &Heir{Addr: heir, Percent: percent})
		total += percent
	}
	if total != 100 {
		panic(ufmt.Sprintf("heir percentages add up to %d, not 100", total))
	}
	return heirs
}

func parseSuccessor(raw address, owner address) address {
	successor := normalize(raw.String())
	switch {
	case successor == "":
		return ""
	case !successor.IsValid():
		panic("invalid successor address: " + raw.String())
	case successor == owner:
		panic("you cannot be your own successor")
	case successor == selfAddr:
		panic("this realm cannot be a successor")
	}
	return successor
}

func parseSilence(s string) time.Duration {
	digits, _ := strings.CutSuffix(strings.TrimSpace(s), "d")
	n, err := strconv.Atoi(digits)
	if err != nil || n < int(MinSilence/day) || n > int(MaxSilence/day) {
		panic(ufmt.Sprintf("silence must be a number of days from %d to %d, e.g. 180", int(MinSilence/day), int(MaxSilence/day)))
	}
	return time.Duration(n) * day
}

func normalize(addr string) address {
	return address(strings.ToLower(strings.TrimSpace(addr)))
}

package heirloom

import (
	"strconv"
	"time"

	"gno.land/p/nt/avl/pager/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const listPageLen = 20

func newWill(owner address, heirs []*Heir, silence time.Duration) *Will {
	w := &Will{
		ID:       int(state.lastID.Next()),
		Owner:    owner,
		Silence:  silence,
		LastSeen: time.Now(),
	}
	state.wills.Set(willKey(w.ID), w)
	state.activeByOwner.Set(owner.String(), w)
	indexWill(&state.ownerWills, owner, w.ID)
	indexHeirs(w, heirs)
	return w
}

func setSuccessor(w *Will, successor address) {
	if h, done := handoverOf(w.Owner); done && successor != "" {
		panic("will " + strconv.Itoa(h.WillID) + " already handed your admin rights to " + h.To.String())
	}
	if w.Successor != "" {
		unindexWill(&state.successorWills, w.Successor, w.ID)
	}
	w.Successor = successor
	if successor != "" {
		indexWill(&state.successorWills, successor, w.ID)
	}
}

func getWill(id int) *Will {
	w, _ := state.wills.Get(willKey(id)).(*Will)
	return w
}

func getActiveWill(owner address) *Will {
	w, _ := state.activeByOwner.Get(owner.String()).(*Will)
	return w
}

func willKey(id int) string {
	return seqid.ID(id).Binary()
}

func indexHeirs(w *Will, heirs []*Heir) {
	for _, h := range w.Heirs {
		unindexWill(&state.heirWills, h.Addr, w.ID)
	}
	w.Heirs = heirs
	for _, h := range heirs {
		indexWill(&state.heirWills, h.Addr, w.ID)
	}
}

func deactivate(w *Will) {
	state.activeByOwner.Remove(w.Owner.String())
}

func removeWill(w *Will) {
	for _, h := range w.Heirs {
		unindexWill(&state.heirWills, h.Addr, w.ID)
	}
	unindexWill(&state.ownerWills, w.Owner, w.ID)
	if w.Successor != "" {
		unindexWill(&state.successorWills, w.Successor, w.ID)
	}
	deactivate(w)
	state.wills.Remove(willKey(w.ID))
}

func willsMadeBy(addr address, page int) ([]*Will, bool) {
	return willPage(&state.ownerWills, addr, page)
}

func willsNaming(addr address, page int) ([]*Will, bool) {
	return willPage(&state.heirWills, addr, page)
}

func willsPassingRightsTo(addr address, page int) ([]*Will, bool) {
	return willPage(&state.successorWills, addr, page)
}

func willPage(index *avl.Tree, addr address, page int) ([]*Will, bool) {
	ids, ok := index.Get(addr.String()).(*avl.Tree)
	if !ok {
		return nil, false
	}
	p := pager.NewPager(ids, listPageLen, true).GetPage(page)
	ws := make([]*Will, 0, len(p.Items))
	for _, item := range p.Items {
		if w, ok := state.wills.Get(item.Key).(*Will); ok {
			ws = append(ws, w)
		}
	}
	return ws, p.HasNext
}

func activeCount() int {
	return state.activeByOwner.Size()
}

func indexWill(index *avl.Tree, addr address, id int) {
	ids, ok := index.Get(addr.String()).(*avl.Tree)
	if !ok {
		ids = &avl.Tree{}
		index.Set(addr.String(), ids)
	}
	ids.Set(willKey(id), true)
}

func unindexWill(index *avl.Tree, addr address, id int) {
	ids, ok := index.Get(addr.String()).(*avl.Tree)
	if !ok {
		return
	}
	ids.Remove(willKey(id))
	if ids.Size() == 0 {
		index.Remove(addr.String())
	}
}

package heirloom

import (
	"strconv"
	"strings"

	"gno.land/p/nt/mux/v0"
)

var router = newRouter()

func newRouter() *mux.Router {
	router := mux.NewRouter()
	router.HandleFunc("", func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write(renderHome())
	})
	router.HandleFunc("will/{id}", func(res *mux.ResponseWriter, req *mux.Request) {
		id, err := strconv.Atoi(req.GetVar("id"))
		w := getWill(id)
		if err != nil || w == nil {
			res.Write(notFound("Will not found"))
			return
		}
		res.Write(renderWill(w))
	})
	router.HandleFunc("u/{addr}", func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write(userPage(req.GetVar("addr"), "1"))
	})
	router.HandleFunc("u/{addr}/{page}", func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write(userPage(req.GetVar("addr"), req.GetVar("page")))
	})
	router.SetNotFoundHandler(func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write(notFound("Page not found"))
	})
	return router
}

// Render serves the home page, "will/<id>", and "u/<address>" with an
// optional page number, "u/<address>/<n>".
func Render(path string) string {
	return router.Render(strings.Trim(path, "/"))
}

func userPage(rawAddr, rawPage string) string {
	addr := normalize(rawAddr)
	if !addr.IsValid() {
		return notFound("Invalid address")
	}
	page, err := strconv.Atoi(rawPage)
	if err != nil || page < 1 {
		return notFound("Page not found")
	}
	return renderUser(addr, page)
}

func notFound(title string) string {
	return "# " + title + "\n\n" + backLink() + "\n"
}

package heirloom

import (
	"chain/runtime"
	"strings"

	"gno.land/p/moul/fifo/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const recentLen = 5

type store struct {
	lastID         seqid.ID
	wills          avl.Tree
	activeByOwner  avl.Tree
	ownerWills     avl.Tree
	heirWills      avl.Tree
	successorWills avl.Tree
	rights         succession
	totalGNOT      int64
	releasedCount  int
	recent         *fifo.List
}

var (
	state    = newStore()
	pkgPath  string
	webPath  string
	selfAddr address
)

func init(cur realm) {
	pkgPath = cur.PkgPath()
	webPath = strings.TrimPrefix(pkgPath, runtime.ChainDomain())
	selfAddr = cur.Address()
}

func newStore() *store {
	return &store{recent: fifo.New(recentLen)}
}

package heirloom

func recordRelease(w *Will) {
	state.releasedCount++
	state.recent.Append(w.ID)
}

func recentlyReleased() []*Will {
	ids := state.recent.Entries()
	ws := make([]*Will, len(ids))
	for i, id := range ids {
		ws[len(ids)-1-i] = getWill(id.(int))
	}
	return ws
}

func totals() (active int, gnotHeld int64, released int) {
	return activeCount(), state.totalGNOT, state.releasedCount
}

package heirloom

import "gno.land/p/nt/avl/v0"

type handover struct {
	To     address
	WillID int
}

type succession struct {
	handovers avl.Tree
	parent    avl.Tree
	rank      avl.Tree
	holder    avl.Tree
}

type adminOutcome int

const (
	adminPending adminOutcome = iota
	adminHandedOverHere
	adminHandedOverByAnother
	adminNoSuccessor
	adminStaysWithOwner
)

func handoverOf(owner address) (handover, bool) {
	h, ok := state.rights.handovers.Get(owner.String()).(handover)
	return h, ok
}

func groupOf(addr address) address {
	for {
		parent, ok := state.rights.parent.Get(addr.String()).(address)
		if !ok {
			return addr
		}
		addr = parent
	}
}

func groupRank(root address) int {
	rank, _ := state.rights.rank.Get(root.String()).(int)
	return rank
}

func holderOfGroup(root address) address {
	if holder, ok := state.rights.holder.Get(root.String()).(address); ok {
		return holder
	}
	return root
}

func holderOf(addr address) address {
	return holderOfGroup(groupOf(addr))
}

func joinGroups(from, to address) {
	holder := holderOfGroup(to)
	fromRank, toRank := groupRank(from), groupRank(to)
	if fromRank > toRank {
		from, to = to, from
	}
	if fromRank == toRank {
		state.rights.rank.Set(to.String(), toRank+1)
	}
	state.rights.parent.Set(from.String(), to)
	state.rights.holder.Remove(from.String())
	state.rights.holder.Set(to.String(), holder)
}

func handoverGroups(w *Will) (from, to address, ok bool) {
	if _, done := handoverOf(w.Owner); done || w.Successor == "" {
		return "", "", false
	}
	from, to = groupOf(w.Owner), groupOf(w.Successor)
	return from, to, from != to
}

func recordHandover(w *Will) bool {
	from, to, ok := handoverGroups(w)
	if !ok {
		return false
	}
	state.rights.handovers.Set(w.Owner.String(), handover{w.Successor, w.ID})
	joinGroups(from, to)
	return true
}

func adminOutcomeOf(w *Will) (adminOutcome, handover) {
	if h, done := handoverOf(w.Owner); done {
		if h.WillID == w.ID {
			return adminHandedOverHere, h
		}
		return adminHandedOverByAnother, h
	}
	if w.Successor == "" {
		return adminNoSuccessor, handover{}
	}
	if _, _, ok := handoverGroups(w); w.isReleased() || !ok {
		return adminStaysWithOwner, handover{}
	}
	return adminPending, handover{}
}

package heirloom

import (
	"math/bits"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	MaxHeirs   = 10
	MaxAssets  = 10
	MinSilence = day
	MaxSilence = 3650 * day

	day = 24 * time.Hour
)

type willStatus string

const (
	statusActive   willStatus = "active"
	statusDue      willStatus = "due"
	statusReleased willStatus = "released"
)

type Heir struct {
	Addr    address
	Percent int

	claimed avl.Tree
}

type Will struct {
	ID         int
	Owner      address
	Heirs      []*Heir
	Successor  address
	Silence    time.Duration
	LastSeen   time.Time
	ReleasedAt time.Time

	held     avl.Tree
	snapshot avl.Tree
}

func (w *Will) releaseAt() time.Time {
	return w.LastSeen.Add(w.Silence)
}

func (w *Will) isReleased() bool {
	return !w.ReleasedAt.IsZero()
}

func (w *Will) isDue() bool {
	return !w.isReleased() && !time.Now().Before(w.releaseAt())
}

func (w *Will) status() willStatus {
	switch {
	case w.isReleased():
		return statusReleased
	case w.isDue():
		return statusDue
	}
	return statusActive
}

func (w *Will) touch() {
	w.LastSeen = time.Now()
}

func (w *Will) heir(addr address) *Heir {
	for _, h := range w.Heirs {
		if h.Addr == addr {
			return h
		}
	}
	return nil
}

func (w *Will) balance(asset string) int64 {
	amount, _ := w.held.Get(asset).(int64)
	return amount
}

func (w *Will) assets() []string {
	return keys(&w.held)
}

func (w *Will) snapshotAssets() []string {
	return keys(&w.snapshot)
}

func (w *Will) add(asset string, amount int64) {
	if !w.held.Has(asset) && w.held.Size() >= MaxAssets {
		panic(ufmt.Sprintf("a will can hold at most %d different assets", MaxAssets))
	}
	total := w.balance(asset) + amount
	if total < w.balance(asset) {
		panic("the will cannot hold that much of " + asset)
	}
	w.held.Set(asset, total)
}

func (w *Will) take(asset string, amount int64) {
	left := w.balance(asset) - amount
	switch {
	case left < 0:
		panic("the will does not hold that much of " + asset)
	case left == 0:
		w.held.Remove(asset)
	default:
		w.held.Set(asset, left)
	}
}

func (w *Will) release() {
	w.ReleasedAt = time.Now()
	w.held.Iterate("", "", func(k string, v any) bool {
		w.snapshot.Set(k, v)
		return false
	})
}

func (w *Will) shareOf(h *Heir, asset string) int64 {
	total, _ := w.snapshot.Get(asset).(int64)
	if h != w.Heirs[0] {
		return mulDiv(total, int64(h.Percent), 100)
	}
	rest := total
	for _, other := range w.Heirs[1:] {
		rest -= mulDiv(total, int64(other.Percent), 100)
	}
	return rest
}

func (h *Heir) hasClaimed(asset string) bool {
	return h.claimed.Has(asset)
}

func keys(t *avl.Tree) []string {
	var ks []string
	t.Iterate("", "", func(k string, _ any) bool {
		ks = append(ks, k)
		return false
	})
	return ks
}

func mulDiv(a, b, c int64) int64 {
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	quo, _ := bits.Div64(hi, lo, uint64(c))
	return int64(quo)
}

package keepersboard

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"

	"gno.land/r/g1klfptn25xf37smf27vqr4g6qlmtwc0lz6y5mcj/heirloom"
)

const (
	maxNoteLen = 280
	shownNotes = 20
)

type note struct {
	ID     int
	Author address
	Text   string
	At     time.Time
}

var (
	founder address
	pkgPath string
	lastID  seqid.ID
	notes   avl.Tree
	pinned  int
)

func init(cur realm) {
	pkgPath = cur.PkgPath()
	founder = address(strings.Split(pkgPath, "/")[2])
}

// Post adds a note of up to 280 characters to the board and returns its id.
// Anyone can post; it counts as a sign of life on Heirloom for the signer.
func Post(cur realm, text string) int {
	author := callerOf(cur)
	text = strings.Join(strings.Fields(text), " ")
	if text == "" || len(text) > maxNoteLen {
		panic("a note must be 1 to " + strconv.Itoa(maxNoteLen) + " characters")
	}
	n := &note{ID: int(lastID.Next()), Author: author, Text: text, At: time.Now()}
	notes.Set(noteKey(n.ID), n)
	heirloom.Touch(cross(cur))
	return n.ID
}

// Pin shows note id at the top of the board. Only the keeper can call it.
func Pin(cur realm, id int) {
	mustBeKeeper(cur)
	mustGetNote(id)
	pinned = id
	heirloom.Touch(cross(cur))
}

// Remove deletes note id. Only the keeper can call it.
func Remove(cur realm, id int) {
	mustBeKeeper(cur)
	mustGetNote(id)
	notes.Remove(noteKey(id))
	if pinned == id {
		pinned = 0
	}
	heirloom.Touch(cross(cur))
}

// Keeper returns who runs the board now: heirloom.Holder of the founder.
func Keeper() address {
	return heirloom.Holder(founder)
}

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	return cur.Previous().Address()
}

func mustBeKeeper(cur realm) {
	if callerOf(cur) != Keeper() {
		panic("only the keeper can do this; the keeper is " + Keeper().String())
	}
}

func mustGetNote(id int) *note {
	n, ok := notes.Get(noteKey(id)).(*note)
	if !ok {
		panic("note " + strconv.Itoa(id) + " not found")
	}
	return n
}

func noteKey(id int) string {
	return seqid.ID(id).Binary()
}

package keepersboard

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/jeronimoalbi/mdform/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1klfptn25xf37smf27vqr4g6qlmtwc0lz6y5mcj/heirloom"
)

// Render shows the board, its keeper and the founder's will on Heirloom.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# The Keeper's Board\n\n")
	b.WriteString("A small board that shows [Heirloom](" + heirloomWeb() + ") at work. ")
	b.WriteString("Anyone can post a note. The keeper can pin one note and remove any. ")
	b.WriteString("The keeper is `heirloom.Holder(founder)`: the founder, until a released will of the founder hands the board to a successor. ")
	b.WriteString("Every post, pin and removal counts as a sign of life on Heirloom for whoever signed it.\n\n")
	b.WriteString(keeperSection())
	b.WriteString(pinnedSection())
	b.WriteString(notesSection())
	b.WriteString(actionsSection())
	return b.String()
}

func keeperSection() string {
	keeper := Keeper()
	var b strings.Builder
	b.WriteString("## Keeper\n\n")
	b.WriteString("| Founder | Keeper now |\n| :--- | :--- |\n")
	b.WriteString("| " + userLink(founder) + " | " + userLink(keeper) + " |\n\n")
	if keeper != founder {
		b.WriteString("The founder's admin rights have passed on, so the board is now run by " + userLink(keeper) + ".\n\n")
		return b.String()
	}
	id, ok := heirloom.ActiveWill(founder)
	if !ok {
		b.WriteString("The founder has no will on Heirloom, so the board stays with the founder.\n\n")
		return b.String()
	}
	_, status, releaseAt, _ := heirloom.WillInfo(id)
	willLink := "[will " + strconv.Itoa(id) + "](" + heirloomWeb() + ":will/" + strconv.Itoa(id) + ")"
	switch status {
	case "due":
		b.WriteString("The founder's " + willLink + " is due: anyone but the founder can release it now.\n\n")
	default:
		b.WriteString("The founder's " + willLink + " can be released from " + formatTime(releaseAt) + " if the founder stays silent until then.\n\n")
	}
	return b.String()
}

func pinnedSection() string {
	n, ok := notes.Get(noteKey(pinned)).(*note)
	if pinned == 0 || !ok {
		return ""
	}
	return "## Pinned\n\n" + noteLine(n) + "\n"
}

func notesSection() string {
	if notes.Size() == 0 {
		return "## Notes\n\nNo notes yet.\n\n"
	}
	var b strings.Builder
	b.WriteString("## Notes\n\n")
	count := 0
	notes.ReverseIterate("", "", func(_ string, v any) bool {
		b.WriteString(noteLine(v.(*note)))
		count++
		return count >= shownNotes
	})
	return b.String() + "\n"
}

func actionsSection() string {
	var b strings.Builder
	b.WriteString("## Post a note\n\n")
	b.WriteString(mdform.New("exec", "Post").
		Input("text", "placeholder", "Up to 280 characters", "description", "Note").
		String() + "\n\n")
	b.WriteString("## Keeper only\n\n")
	b.WriteString(mdform.New("exec", "Pin").Input("id", "type", mdform.InputTypeNumber, "description", "Note to pin").String() + "\n\n")
	b.WriteString(mdform.New("exec", "Remove").Input("id", "type", mdform.InputTypeNumber, "description", "Note to remove").String() + "\n")
	return b.String()
}

func noteLine(n *note) string {
	return ufmt.Sprintf("- #%d %s · %s, %s\n", n.ID, sanitize.InlineText(n.Text), userLink(n.Author), formatTime(n.At))
}

func userLink(addr address) string {
	s := addr.String()
	short := s
	if len(s) > 14 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](" + heirloomWeb() + ":u/" + s + ")"
}

func heirloomWeb() string {
	return "/r/" + founder.String() + "/heirloom"
}

func formatTime(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04 UTC")
}
